window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k2v3"]=[{"id":"k2v3-b01","courseId":"k2v3","order":1,"title":"Cô ấy mời chúng tôi ăn vịt quay Bắc Kinh","titleZh":"她请我们吃了北京烤鸭","titlePy":"tā qǐng wǒmen chīle Běijīng Kǎoyā","vocab":[{"stt":1,"hanzi":"就","pinyin":"jiù","hanviet":"Tựu","pos":"Phó từ","meaning":"chính là, ngay (nhấn mạnh)","comps":"就是 (chính là), 就在这儿 (ngay ở đây)","example":{"zh":"你们就是她的学生吧？","py":"Nǐmen jiù shì tā de xuéshēng ba?","vi":"Các em chính là học sinh của cô ấy nhỉ?"}},{"stt":2,"hanzi":"给","pinyin":"gěi","hanviet":"Cấp","pos":"Giới từ","meaning":"cho, đối với (dẫn ra người nhận)","comps":"给我打电话 (gọi điện cho tôi), 给你介绍 (giới thiệu cho bạn)","example":{"zh":"我给妈妈打电话。","py":"Wǒ gěi māma dǎ diànhuà.","vi":"Mình gọi điện cho mẹ."}},{"stt":3,"hanzi":"让","pinyin":"ràng","hanviet":"Nhượng","pos":"Động từ","meaning":"để, cho, bảo (ai làm gì)","comps":"让我来 (để tôi làm), 让他休息 (để anh ấy nghỉ)","example":{"zh":"妈妈让我去买菜。","py":"Māma ràng wǒ qù mǎi cài.","vi":"Mẹ bảo mình đi mua đồ ăn."}},{"stt":4,"hanzi":"接","pinyin":"jiē","hanviet":"Tiếp","pos":"Động từ","meaning":"đón; nhận (điện thoại)","comps":"接人 (đón người), 接电话 (nghe điện thoại)","example":{"zh":"明天我去火车站接你。","py":"Míngtiān wǒ qù huǒchēzhàn jiē nǐ.","vi":"Mai mình ra ga tàu đón bạn."}},{"stt":5,"hanzi":"次","pinyin":"cì","hanviet":"Thứ","pos":"Lượng từ","meaning":"lần (đếm số lần, lần thứ mấy)","comps":"第一次 (lần đầu tiên), 一次 (một lần)","example":{"zh":"我是第一次来北京。","py":"Wǒ shì dì-yī cì lái Běijīng.","vi":"Đây là lần đầu tiên mình đến Bắc Kinh."}},{"stt":6,"hanzi":"旅游","pinyin":"lǚyóu","hanviet":"Lữ du","pos":"Động từ","meaning":"du lịch","comps":"去旅游 (đi du lịch), 来旅游 (đến du lịch)","example":{"zh":"我们是来旅游的。","py":"Wǒmen shì lái lǚyóu de.","vi":"Bọn mình đến đây để du lịch."}},{"stt":7,"hanzi":"帮忙","pinyin":"bāngmáng","hanviet":"Bang mang","pos":"Động từ","meaning":"giúp đỡ, giúp một tay","comps":"帮个忙 (giúp một việc), 请你帮忙 (nhờ bạn giúp)","example":{"zh":"我想请你帮个忙。","py":"Wǒ xiǎng qǐng nǐ bāng gè máng.","vi":"Mình muốn nhờ bạn giúp một việc."}},{"stt":8,"hanzi":"不好意思","pinyin":"bù hǎoyìsi","hanviet":"Bất hảo ý tứ","pos":"Cụm từ","meaning":"ngại quá, xin lỗi (lịch sự)","comps":"真不好意思 (thật ngại quá), 不好意思，我来晚了 (xin lỗi, tôi đến muộn)","example":{"zh":"不好意思，我来晚了。","py":"Bù hǎoyìsi, wǒ lái wǎn le.","vi":"Ngại quá, mình đến muộn."}},{"stt":9,"hanzi":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","pos":"Phó từ","meaning":"đã, rồi","comps":"已经到了 (đã đến rồi), 已经吃饭了 (đã ăn cơm rồi)","example":{"zh":"我已经到北京了。","py":"Wǒ yǐjīng dào Běijīng le.","vi":"Mình đã đến Bắc Kinh rồi."}},{"stt":10,"hanzi":"那","pinyin":"nà","hanviet":"Na","pos":"Liên từ","meaning":"vậy thì, thế thì","comps":"那好吧 (vậy được rồi), 那我们走吧 (thế thì mình đi thôi)","example":{"zh":"那我给他打个电话。","py":"Nà wǒ gěi tā dǎ gè diànhuà.","vi":"Vậy mình gọi điện cho cậu ấy."}},{"stt":11,"hanzi":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","pos":"Động từ","meaning":"giới thiệu","comps":"介绍一下 (giới thiệu một chút), 自我介绍 (tự giới thiệu)","example":{"zh":"我给你介绍一下。","py":"Wǒ gěi nǐ jièshào yíxià.","vi":"Để mình giới thiệu với bạn một chút."}},{"stt":12,"hanzi":"有时","pinyin":"yǒushí","hanviet":"Hữu thời","pos":"Phó từ","meaning":"có lúc, đôi khi","comps":"有时候 (có lúc), 有时不懂 (có lúc không hiểu)","example":{"zh":"我有时坐公交车上班。","py":"Wǒ yǒushí zuò gōngjiāochē shàngbān.","vi":"Đôi khi mình đi xe buýt đi làm."}},{"stt":13,"hanzi":"懂","pinyin":"dǒng","hanviet":"Đổng","pos":"Động từ","meaning":"hiểu, biết","comps":"听懂 (nghe hiểu), 看懂 (đọc hiểu)","example":{"zh":"你懂我的意思吗？","py":"Nǐ dǒng wǒ de yìsi ma?","vi":"Bạn hiểu ý mình không?"}},{"stt":14,"hanzi":"意思","pinyin":"yìsi","hanviet":"Ý tứ","pos":"Danh từ","meaning":"ý, ý nghĩa","comps":"什么意思 (nghĩa là gì), 有意思 (thú vị)","example":{"zh":"这个字是什么意思？","py":"Zhège zì shì shénme yìsi?","vi":"Chữ này nghĩa là gì?"}},{"stt":15,"hanzi":"北京烤鸭","pinyin":"Běijīng Kǎoyā","hanviet":"Bắc Kinh khảo áp","pos":"Danh từ riêng","meaning":"vịt quay Bắc Kinh","comps":"吃北京烤鸭 (ăn vịt quay Bắc Kinh), 烤鸭店 (quán vịt quay)","example":{"zh":"她请我们吃了北京烤鸭。","py":"Tā qǐng wǒmen chīle Běijīng Kǎoyā.","vi":"Cô ấy mời chúng tôi ăn vịt quay Bắc Kinh."}}],"hanzi":[{"char":"就","pinyin":"jiù","hanviet":"Tựu","chars":["就"],"story":"就 gồm 京 (gò đất cao, nơi đông người ở) và 尤 (vượt trội). Nghĩa gốc là \"đi tới chỗ cao\" — tìm đến, tiến đến. Từ \"đi tới ngay\" mà ra phó từ nhấn mạnh \"chính là, ngay\": 就是 = chính là."},{"char":"给","pinyin":"gěi","hanviet":"Cấp","chars":["给"],"story":"给 là chữ hình thanh: bộ Mịch 纟 (sợi tơ) chỉ nghĩa, 合 hé chỉ âm. Nghĩa gốc là \"cấp cho đủ\" — tơ lụa là thứ người xưa thường đem cấp, tặng. Nay làm giới từ \"cho\": 给我打电话 = gọi điện cho tôi."},{"char":"让","pinyin":"ràng","hanviet":"Nhượng","chars":["让"],"story":"让 gồm bộ Ngôn 讠 (lời nói) và 上. Chữ phồn thể 讓 = 言 + 襄 xiāng chỉ âm. Nghĩa gốc là \"nhường\" (lời lẽ khiêm nhường), từ đó mở rộng thành \"để, cho phép, bảo ai làm gì\"."},{"char":"接","pinyin":"jiē","hanviet":"Tiếp","chars":["接"],"story":"接 là chữ hình thanh: bộ Thủ 扌 (bàn tay) chỉ nghĩa, 妾 qiè chỉ âm. Đưa tay ra đón lấy — nên 接 là \"đón\" (接人) và \"nhận\" (接电话 — nhận cuộc gọi)."},{"char":"次","pinyin":"cì","hanviet":"Thứ","chars":["次"],"story":"次 gồm 冫 bên trái và 欠 (người há miệng thở) bên phải. Nghĩa gốc là \"dừng chân nghỉ\" dọc đường; các chặng nghỉ nối nhau thành \"thứ tự, lượt\", rồi thành lượng từ \"lần\": 第一次 = lần thứ nhất."},{"char":"旅游","pinyin":"lǚyóu","hanviet":"Lữ du","chars":["旅","游"],"story":"旅 vẽ lá cờ (方 + 𠂉) dẫn đầu một đoàn người — đoàn quân, đoàn người đi xa, nên có nghĩa \"lữ hành\". 游 = 氵(nước) + 斿 (dải cờ phấp phới): bơi, đi chơi thong dong. Ghép lại 旅游 = đi xa để vui chơi — du lịch."},{"char":"帮忙","pinyin":"bāngmáng","hanviet":"Bang mang","chars":["帮","忙"],"story":"帮 = 邦 bāng chỉ âm + 巾 (tấm vải) — nay nghĩa là \"giúp\". 忙 = 忄(tim) + 亡 (mất): lòng dạ rối như mất hồn — \"bận\". 帮忙 = giúp người đang bận. Đây là từ ly hợp: chen được chữ vào giữa — 帮个忙, 帮我的忙."},{"char":"不好意思","pinyin":"bù hǎoyìsi","hanviet":"Bất hảo ý tứ","chars":["不","好","意","思"],"story":"不 (không) + 好 (tốt: 女 người mẹ + 子 đứa con) + 意思 (ý tứ, xem từ 14). Nghĩa đen \"trong lòng thấy không ổn\" — tức là ngượng, ngại. Dùng để xin lỗi nhẹ nhàng hoặc khi làm phiền người khác."},{"char":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","chars":["已","经"],"story":"已 viết gần giống 己 jǐ và 巳 sì — mẹo nhớ: nét móc hở là 己, kín một nửa là 已, kín hẳn là 巳. 经 = 纟(sợi tơ) + 圣 (sợi dọc căng trên khung cửi) → \"đi qua, trải qua\". 已经 = đã trải qua rồi → \"đã\"."},{"char":"那","pinyin":"nà","hanviet":"Na","chars":["那"],"story":"那 gồm phần bên trái và bộ Ấp 阝(vùng đất) bên phải — vốn là tên một vùng đất, sau mượn làm đại từ \"kia\" (那个). Đứng đầu câu thì thành liên từ \"vậy thì\": 那我给他打个电话."},{"char":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","chars":["介","绍"],"story":"介 vẽ người 人 đứng giữa hai vạch — người đứng giữa làm trung gian. 绍 = 纟(sợi tơ) + 召 zhào chỉ âm — nối sợi cho liền. 介绍 = đứng giữa nối hai bên lại với nhau → giới thiệu."},{"char":"有时","pinyin":"yǒushí","hanviet":"Hữu thời","chars":["有","时"],"story":"有 vẽ bàn tay 𠂇 cầm miếng thịt 月 — trong tay có thịt là \"có\". 时 = 日 (mặt trời) + 寸 cùn (đo lường): đo bóng mặt trời để tính \"thời gian\". 有时 = có những lúc → đôi khi."},{"char":"懂","pinyin":"dǒng","hanviet":"Đổng","chars":["懂"],"story":"懂 là chữ hình thanh: bộ Tâm 忄 (trái tim) chỉ nghĩa, 董 dǒng chỉ âm. Hiểu là việc của \"lòng\" — hiểu thấu trong tâm. 听懂 = nghe hiểu, 看懂 = đọc hiểu."},{"char":"意思","pinyin":"yìsi","hanviet":"Ý tứ","chars":["意","思"],"story":"意 = 音 (âm thanh) + 心 (tim): tiếng nói trong lòng — ý nghĩ. 思 = 田 (vốn là 囟, cái thóp đầu) + 心: đầu và tim cùng nghĩ — suy nghĩ. 意思 = điều trong lòng muốn nói → ý, ý nghĩa."},{"char":"北京烤鸭","pinyin":"Běijīng Kǎoyā","hanviet":"Bắc Kinh khảo áp","chars":["北","京","烤","鸭"],"story":"北 vẽ hai người quay lưng vào nhau → \"phía bắc\". 京 vẽ toà nhà cao trên nền đất cao → \"kinh đô\". 烤 = 火 (lửa) + 考 kǎo chỉ âm → nướng. 鸭 = 甲 jiǎ chỉ âm + 鸟 (chim) → con vịt. 北京烤鸭 = vịt quay của kinh đô phía bắc."}],"grammar":[{"title":"Trợ từ ngữ khí 吧 (2)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>陈述句</b><small>câu trần thuật (điều đã đoán)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吧？</b><small>…nhỉ? / …phải không?</small></span></div>","summary":"<p class=\"gr-lead\">Phỏng đoán — hỏi để xác nhận</p><ul><li>Đặt <span class=\"zh\">吧</span> cuối câu hỏi khi người nói <b>đã đoán gần chắc</b>, hỏi lại để <b>xác nhận</b>.</li><li>So với <span class=\"zh\">吗</span>: <span class=\"zh\">……吗？</span> chưa biết, hỏi thật · <span class=\"zh\">……吧？</span> đã đoán, chờ xác nhận.</li><li>Trả lời: <span class=\"zh\">对 / 是的</span> (đúng vậy) hoặc <span class=\"zh\">不是</span> + thông tin đúng.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你们就是她的学生吧？</span> = Các em chính là học sinh của cô ấy nhỉ?</p>","note":"<b>Lưu ý:</b> Không dùng <span class=\"zh\">吧</span> phỏng đoán trong câu đã có từ để hỏi: ✗ <span class=\"zh\">你是谁吧？</span>","examples":[{"zh":"你们就是她的学生吧？","py":"Nǐmen jiù shì tā de xuéshēng ba?","vi":"Các em chính là học sinh của cô ấy nhỉ?"},{"zh":"她唱歌很好听吧？","py":"Tā chànggē hěn hǎotīng ba?","vi":"Cô ấy hát hay lắm nhỉ?"},{"zh":"陈天中是泰国人吧？","py":"Chén Tiānzhōng shì Tàiguó rén ba?","vi":"Trần Thiên Trung là người Thái Lan nhỉ?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这是____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对，是我的手机，谢谢你！</span></span></span><span class=\"qz-hint\">Đây là điện thoại của bạn nhỉ? — Đúng rồi, là điện thoại của mình, cảm ơn bạn!</span>","answer":["你的手机吧"],"explain":"这是你的手机吧？ (Zhè shì nǐ de shǒujī ba?)"}]},{"title":"Câu 是……的","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(是)</b><small>có thể lược</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>强调部分</b><small>thời gian · nơi · cách thức…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>trợ từ</small></span></div>","summary":"<p class=\"gr-lead\">Chi tiết của việc đã qua</p><ul><li>Dùng cho việc <b>đã xảy ra</b>, khi muốn <b>nhấn mạnh</b>: thời gian, địa điểm, cách thức, người làm, mục đích.</li><li>Phần được nhấn mạnh đứng <b>ngay sau</b> <span class=\"zh\">是</span>, động từ đứng ngay trước <span class=\"zh\">的</span>.</li><li>Câu khẳng định và câu hỏi <b>có thể lược</b> <span class=\"zh\">是</span>: <span class=\"zh\">苹果在哪儿买的？</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"是……的\" 句</span> · Ba dạng câu</h4><p>KĐ · PĐ · Câu hỏi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(是)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>强调部分</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b></span></div><div class=\"fx-ex zh\">我们是来旅游的。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>强调部分</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b></span></div><div class=\"fx-ex zh\">我不是坐车来的。</div><div class=\"fx-lbl\">Nghi vấn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(是)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>强调部分</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的吗？</b></span></div><div class=\"fx-ex zh\">你是怎么来的？</div></div><p class=\"gr-key\"><span class=\"hot\">Phủ định <b>không được lược</b> <span class=\"zh\">是</span>: <span class=\"zh\">不是……的</span></span>　✗ <span class=\"zh\">我不坐车来的</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我是今天早上到的。</span>　·　<span class=\"zh\">我们是来旅游的。</span>　·　<span class=\"zh\">苹果在哪儿买的？</span></p>","note":"","examples":[{"zh":"我们是来旅游的。","py":"Wǒmen shì lái lǚyóu de.","vi":"Chúng mình đến đây để du lịch."},{"zh":"苹果在哪儿买的？","py":"Píngguǒ zài nǎr mǎi de?","vi":"Táo mua ở đâu thế?"},{"zh":"我们不是坐出租车去的。","py":"Wǒmen bú shì zuò chūzūchē qù de.","vi":"Chúng mình không đi bằng taxi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我是在书店看见安妮的。</span></span></span><span class=\"qz-hint\">Bạn nhìn thấy Annie ở đâu? — Mình nhìn thấy Annie ở hiệu sách.</span>","answer":["你是在哪儿看见安妮的","你在哪儿看见安妮的","你是在哪里看见安妮的","你在哪里看见安妮的"],"explain":"你是在哪儿看见安妮的？ (Nǐ shì zài nǎr kànjiàn Ānnī de?)"}]},{"title":"Câu kiêm ngữ (兼语句) với 请 / 让 / 叫","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>请 / 让 / 叫</b><small>mời · bảo · gọi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语 (→主语)</b><small>tân ngữ = chủ ngữ ĐT2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>việc cần làm</small></span></div>","summary":"<p class=\"gr-lead\">Mời / bảo / nhờ ai làm việc gì</p><ul><li>Vị ngữ có <b>2 cụm động từ</b>; tân ngữ của động từ 1 đồng thời là <b>chủ ngữ</b> của động từ 2 (một từ \"kiêm\" hai vai).</li><li><span class=\"zh\">请</span> mời, nhờ (lịch sự) · <span class=\"zh\">让</span> để, bảo, cho phép · <span class=\"zh\">叫</span> bảo, gọi (khẩu ngữ).</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我想请你帮个忙。</span>　·　<span class=\"zh\">王老师让我们说中文。</span>　·　<span class=\"zh\">妈妈叫孩子们回家。</span></p>","note":"<b>Lưu ý:</b> Phủ định đặt <span class=\"zh\">不 / 没</span> <b>trước</b> <span class=\"zh\">请 / 让 / 叫</span>: <span class=\"zh\">妈妈不让我出去</span>, không đặt trước động từ 2.","examples":[{"zh":"我想请你帮个忙。","py":"Wǒ xiǎng qǐng nǐ bāng gè máng.","vi":"Mình muốn nhờ bạn giúp một việc."},{"zh":"王老师让我们说中文。","py":"Wáng lǎoshī ràng wǒmen shuō Zhōngwén.","vi":"Cô Vương bảo chúng mình nói tiếng Trung."},{"zh":"妈妈叫孩子们回家。","py":"Māma jiào háizimen huí jiā.","vi":"Mẹ gọi bọn trẻ về nhà."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在机场","titleVi":"Ở sân bay — chị Nhất Tuyết ra đón","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"请问，您是王一飞老师的姐姐吗？","py":"Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?","vi":"Xin hỏi, chị là chị gái của cô Vương Nhất Phi phải không ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"是的，你们就是她的学生吧？","py":"Shì de, nǐmen jiù shì tā de xuéshēng ba?","vi":"Đúng rồi, các em chính là học sinh của em ấy nhỉ?"},{"speaker":"月","name":"Gia Nguyệt","zh":"对。我是白家月，她是安妮。","py":"Duì. Wǒ shì Bái Jiāyuè, tā shì Ānnī.","vi":"Vâng ạ. Em là Bạch Gia Nguyệt, bạn ấy là Annie."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","py":"Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen.","vi":"Chào các em, chị là Vương Nhất Tuyết. Nhất Phi gọi điện cho chị, nhờ chị ra đón các em."},{"speaker":"妮","name":"Nguyệt · Annie","zh":"谢谢您。","py":"Xièxie nín.","vi":"Cảm ơn chị ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"不客气。","py":"Bú kèqi.","vi":"Không có gì."}]},{"titleZh":"课文二 · 在车里","titleVi":"Trên xe chị Nhất Tuyết — trò chuyện","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"你们是第一次来北京吗？","py":"Nǐmen shì dì-yī cì lái Běijīng ma?","vi":"Các em lần đầu đến Bắc Kinh à?"},{"speaker":"月","name":"Gia Nguyệt","zh":"是的，我们都是第一次来。","py":"Shì de, wǒmen dōu shì dì-yī cì lái.","vi":"Vâng, cả hai bọn em đều đến lần đầu ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你们是来学中文的吗？","py":"Nǐmen shì lái xué Zhōngwén de ma?","vi":"Các em sang đây học tiếng Trung à?"},{"speaker":"妮","name":"Annie","zh":"不是，我们是来旅游的。","py":"Bú shì, wǒmen shì lái lǚyóu de.","vi":"Không ạ, bọn em sang du lịch."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我这几天都不忙，你们有事就找我。","py":"Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ.","vi":"Mấy hôm nay chị đều rảnh, các em có việc gì cứ tìm chị."},{"speaker":"月","name":"Gia Nguyệt","zh":"好的，谢谢您。","py":"Hǎo de, xièxie nín.","vi":"Vâng, cảm ơn chị ạ."}]},{"titleZh":"课文三 · 在车上","titleVi":"Trên xe — Thiên Trung gọi điện tới","lines":[{"speaker":"中","name":"Thiên Trung","zh":"喂，家月，你明天有时间吗？我想请你帮个忙。","py":"Wèi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng gè máng.","vi":"A lô, Gia Nguyệt, mai cậu có rảnh không? Mình muốn nhờ cậu giúp một việc."},{"speaker":"月","name":"Gia Nguyệt","zh":"不好意思，天中，我已经到北京了。","py":"Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","vi":"Ngại quá, Thiên Trung, mình đến Bắc Kinh rồi."},{"speaker":"中","name":"Thiên Trung","zh":"你是什么时候到的？","py":"Nǐ shì shénme shíhou dào de?","vi":"Cậu đến lúc nào thế?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","py":"Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne.","vi":"Mình đến từ sáng nay. Cậu có việc thì nhờ Lý Văn giúp nhé, cậu ấy vẫn còn ở trường."},{"speaker":"中","name":"Thiên Trung","zh":"好的，那我给他打个电话。","py":"Hǎo de, nà wǒ gěi tā dǎ gè diànhuà.","vi":"Ừ, vậy mình gọi điện cho cậu ấy."},{"speaker":"月","name":"Gia Nguyệt","zh":"好，再见！","py":"Hǎo, zàijiàn!","vi":"Ừ, tạm biệt!"}]},{"titleZh":"课文四 · 在酒店","titleVi":"Ở khách sạn — nhắn tin cho cô Vương","para":true,"speaker":"月","lines":[{"zh":"王老师，我们已经到北京了，是您姐姐来接的我们。","py":"Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le, shì nín jiějie lái jiē de wǒmen.","vi":"Cô Vương ơi, chúng em đã đến Bắc Kinh rồi, là chị gái cô ra đón chúng em ạ."},{"zh":"她请我们吃了北京烤鸭，还给我们介绍了很多东西。","py":"Tā qǐng wǒmen chīle Běijīng Kǎoyā, hái gěi wǒmen jièshàole hěn duō dōngxi.","vi":"Chị ấy mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ."},{"zh":"我们的中文不太好，有时不太懂她的意思。","py":"Wǒmen de Zhōngwén bú tài hǎo, yǒushí bú tài dǒng tā de yìsi.","vi":"Tiếng Trung của chúng em chưa tốt lắm, đôi khi không hiểu lắm ý của chị ấy."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Đóng vai · Ra ga đón bạn","q":{"zh":"一人来火车站接朋友，一人刚出站。问问朋友：来做什么？现在去哪儿？","py":"Yì rén lái huǒchēzhàn jiē péngyou, yì rén gāng chū zhàn. Wènwen péngyou: lái zuò shénme? Xiànzài qù nǎr?","vi":"Một người ra ga đón bạn, một người vừa ra khỏi ga. Hỏi bạn: đến đây làm gì? Bây giờ định đi đâu?"},"items":[{"lines":[{"who":"A","zh":"你是第一次来北京吗？","py":"Nǐ shì dì-yī cì lái Běijīng ma?","vi":"Bạn đến Bắc Kinh lần đầu à?"},{"who":"B","zh":"不是，已经是第二次来北京了。","py":"Bú shì, yǐjīng shì dì-èr cì lái Běijīng le.","vi":"Không, lần thứ hai rồi."}]},{"zh":"你是什么时候到的？坐什么来的？","py":"Nǐ shì shénme shíhou dào de? Zuò shénme lái de?","vi":"Bạn đến lúc nào? Đi bằng gì đến?"},{"zh":"你是来旅游的吧？我请你吃烤鸭！","py":"Nǐ shì lái lǚyóu de ba? Wǒ qǐng nǐ chī kǎoyā!","vi":"Bạn đến du lịch nhỉ? Mình mời bạn ăn vịt quay!"}]}],"speak":[]}},{"id":"k2v3-b02","courseId":"k2v3","order":2,"title":"Hay là bắt taxi đến Đại học Bắc Kinh đi","titleZh":"还是打车去北大吧","titlePy":"háishi dǎchē qù Běidà ba","vocab":[{"stt":1,"hanzi":"公交车","pinyin":"gōngjiāochē","hanviet":"Công giao xa","pos":"Danh từ","meaning":"xe buýt","comps":"坐公交车 (đi xe buýt), 公交车站 (bến xe buýt)","example":{"zh":"我每天坐公交车去学校。","py":"Wǒ měi tiān zuò gōngjiāochē qù xuéxiào.","vi":"Ngày nào mình cũng đi xe buýt đến trường."}},{"stt":2,"hanzi":"但","pinyin":"dàn","hanviet":"Đãn","pos":"Liên từ","meaning":"nhưng","comps":"但是 (nhưng), 好看但贵 (đẹp nhưng đắt)","example":{"zh":"这件衣服很好看，但有点儿贵。","py":"Zhè jiàn yīfu hěn hǎokàn, dàn yǒudiǎnr guì.","vi":"Chiếc áo này rất đẹp, nhưng hơi đắt."}},{"stt":3,"hanzi":"车站","pinyin":"chēzhàn","hanviet":"Xa trạm","pos":"Danh từ","meaning":"bến xe, nhà ga","comps":"公交车站 (bến xe buýt), 去车站 (ra bến xe)","example":{"zh":"请问，车站在哪儿？","py":"Qǐngwèn, chēzhàn zài nǎr?","vi":"Xin hỏi, bến xe ở đâu ạ?"}},{"stt":4,"hanzi":"远","pinyin":"yuǎn","hanviet":"Viễn","pos":"Tính từ","meaning":"xa","comps":"很远 (rất xa), 不远 (không xa)","example":{"zh":"车站有点儿远。","py":"Chēzhàn yǒudiǎnr yuǎn.","vi":"Bến xe hơi xa."}},{"stt":5,"hanzi":"打车","pinyin":"dǎchē","hanviet":"Đả xa","pos":"Động từ","meaning":"bắt taxi, gọi xe","comps":"打车去 (bắt taxi đi), 好打车 (dễ bắt xe)","example":{"zh":"这儿好打车吗？","py":"Zhèr hǎo dǎchē ma?","vi":"Ở đây có dễ bắt taxi không?"}},{"stt":6,"hanzi":"还是","pinyin":"háishi","hanviet":"Hoàn thị","pos":"Phó từ","meaning":"tốt hơn là, hay là (đề nghị)","comps":"还是……吧 (hay là… đi), 还是别去了 (thôi đừng đi nữa)","example":{"zh":"我们还是打车去吧。","py":"Wǒmen háishi dǎchē qù ba.","vi":"Hay là chúng mình bắt taxi đi nhé."}},{"stt":7,"hanzi":"啊","pinyin":"a","hanviet":"A","pos":"Trợ từ","meaning":"…quá, …thế (cảm thán, đồng ý)","comps":"是啊 (đúng thế), 真多啊 (nhiều thật đấy)","example":{"zh":"今天天气真好啊！","py":"Jīntiān tiānqì zhēn hǎo a!","vi":"Hôm nay trời đẹp quá!"}},{"stt":8,"hanzi":"万","pinyin":"wàn","hanviet":"Vạn","pos":"Số từ","meaning":"vạn, mười nghìn","comps":"一万 (mười nghìn), 四万多 (hơn bốn vạn)","example":{"zh":"这个电脑一万多块钱。","py":"Zhège diànnǎo yíwàn duō kuài qián.","vi":"Chiếc máy tính này hơn mười nghìn tệ."}},{"stt":9,"hanzi":"名","pinyin":"míng","hanviet":"Danh","pos":"Lượng từ","meaning":"(lượng từ chỉ người); thứ hạng; tên","comps":"三名学生 (ba học sinh), 第一名 (hạng nhất)","example":{"zh":"我们班有二十名学生。","py":"Wǒmen bān yǒu èrshí míng xuéshēng.","vi":"Lớp mình có hai mươi học sinh."}},{"stt":10,"hanzi":"网上","pinyin":"wǎngshang","hanviet":"Võng thượng","pos":"Danh từ","meaning":"trên mạng","comps":"在网上买 (mua trên mạng), 网上说 (trên mạng nói)","example":{"zh":"我在网上买了一本书。","py":"Wǒ zài wǎngshang mǎile yì běn shū.","vi":"Mình mua một quyển sách trên mạng."}},{"stt":11,"hanzi":"外国","pinyin":"wàiguó","hanviet":"Ngoại quốc","pos":"Danh từ","meaning":"nước ngoài","comps":"外国人 (người nước ngoài), 外国学生 (du học sinh)","example":{"zh":"学校里有很多外国学生。","py":"Xuéxiào li yǒu hěn duō wàiguó xuéshēng.","vi":"Trong trường có rất nhiều sinh viên nước ngoài."}},{"stt":12,"hanzi":"间","pinyin":"jiān","hanviet":"Gian","pos":"Lượng từ","meaning":"gian, phòng (lượng từ cho phòng)","comps":"一间教室 (một phòng học), 这间房间 (căn phòng này)","example":{"zh":"这间教室很大。","py":"Zhè jiān jiàoshì hěn dà.","vi":"Phòng học này rất rộng."}},{"stt":13,"hanzi":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","pos":"Danh từ","meaning":"phòng học, lớp học","comps":"在教室 (ở lớp học), 大教室 (phòng học lớn)","example":{"zh":"老师在教室里等我们。","py":"Lǎoshī zài jiàoshì li děng wǒmen.","vi":"Cô giáo đang đợi chúng mình trong lớp."}},{"stt":14,"hanzi":"票","pinyin":"piào","hanviet":"Phiếu","pos":"Danh từ","meaning":"vé","comps":"电影票 (vé xem phim), 买票 (mua vé)","example":{"zh":"电影票很便宜。","py":"Diànyǐngpiào hěn piányi.","vi":"Vé xem phim rất rẻ."}},{"stt":15,"hanzi":"别","pinyin":"bié","hanviet":"Biệt","pos":"Phó từ","meaning":"đừng; tốt nhất là không","comps":"别去 (đừng đi), 别看了 (đừng xem nữa)","example":{"zh":"别看电视了，快睡觉吧。","py":"Bié kàn diànshì le, kuài shuìjiào ba.","vi":"Đừng xem tivi nữa, mau đi ngủ đi."}},{"stt":16,"hanzi":"过来","pinyin":"guòlái","hanviet":"Quá lai","pos":"Động từ","meaning":"qua đây, lại đây","comps":"过来看看 (qua đây xem), 你过来 (bạn lại đây)","example":{"zh":"你过来一下，好吗？","py":"Nǐ guòlái yíxià, hǎo ma?","vi":"Bạn qua đây một chút được không?"}},{"stt":17,"hanzi":"北京大学","pinyin":"Běijīng Dàxué","hanviet":"Bắc Kinh Đại học","pos":"Danh từ riêng","meaning":"Đại học Bắc Kinh","comps":"去北京大学 (đến ĐH Bắc Kinh), 北大 (gọi tắt)","example":{"zh":"我也想来北京大学学习。","py":"Wǒ yě xiǎng lái Běijīng Dàxué xuéxí.","vi":"Mình cũng muốn đến Đại học Bắc Kinh học."}}],"hanzi":[{"char":"公交车","pinyin":"gōngjiāochē","hanviet":"Công giao xa","chars":["公","交","车"],"story":"公 = 八 (chia ra) + 厶 (của riêng): đem cái riêng chia cho mọi người → \"chung, công cộng\". 交 vẽ người đứng bắt chéo hai chân → \"giao nhau, qua lại\". 车 vẽ cỗ xe nhìn từ trên xuống. 公交车 = xe chở chung mọi người đi lại → xe buýt."},{"char":"但","pinyin":"dàn","hanviet":"Đãn","chars":["但"],"story":"但 là chữ hình thanh: bộ Nhân 亻 (người) chỉ nghĩa, 旦 dàn chỉ âm (旦 = mặt trời 日 nhô lên trên đường chân trời 一). Nghĩa gốc là \"cởi trần\", về sau mượn làm liên từ \"nhưng\"."},{"char":"车站","pinyin":"chēzhàn","hanviet":"Xa trạm","chars":["车","站"],"story":"车 vẽ cỗ xe: nét sổ là trục, hai nét ngang là bánh xe. 站 = 立 (người đứng) chỉ nghĩa + 占 zhàn chỉ âm → chỗ dừng lại đứng đợi. 车站 = nơi xe dừng đỗ → bến xe, nhà ga."},{"char":"远","pinyin":"yuǎn","hanviet":"Viễn","chars":["远"],"story":"远 là chữ hình thanh: bộ Sước 辶 (bước đi) chỉ nghĩa, 元 yuán chỉ âm. Phải đi bộ mãi mới tới → \"xa\". Nhớ theo cặp: 远 (xa) ↔ 近 (gần) — cả hai đều có 辶."},{"char":"打车","pinyin":"dǎchē","hanviet":"Đả xa","chars":["打","车"],"story":"打 = bộ Thủ 扌 (bàn tay) + 丁 dīng chỉ âm → \"đánh\", rồi rộng ra là làm một động tác bằng tay (打电话, 打篮球). 车 = xe. 打车 = vẫy tay gọi xe → bắt taxi."},{"char":"还是","pinyin":"háishi","hanviet":"Hoàn thị","chars":["还","是"],"story":"还 = 辶 (bước đi) + 不; nghĩa gốc là \"quay về\" (đọc huán, như 还书 trả sách), đọc hái thì là \"vẫn, còn\". 是 = 日 + 正 → \"đúng\". 还是 = cân nhắc rồi quay về phương án đúng hơn → \"tốt hơn là, hay là\"."},{"char":"啊","pinyin":"a","hanviet":"A","chars":["啊"],"story":"啊 = bộ Khẩu 口 (miệng) chỉ nghĩa + 阿 ā chỉ âm → tiếng thốt ra từ miệng. Đặt cuối câu làm ngữ khí cảm thán, đồng tình: 是啊! 真多啊!"},{"char":"万","pinyin":"wàn","hanviet":"Vạn","chars":["万"],"story":"Chữ phồn thể 萬 vẽ con bọ cạp: trên là hai càng, giữa là thân, dưới là đuôi. Bọ cạp đẻ rất nhiều con nên được mượn chỉ số lớn \"mười nghìn\" — vạn. Chữ giản thể 万 chỉ giữ lại vài nét."},{"char":"名","pinyin":"míng","hanviet":"Danh","chars":["名"],"story":"名 = 夕 (buổi tối) + 口 (miệng): trời tối không nhìn rõ mặt nhau, phải lên tiếng xưng tên → \"tên\". Mỗi người một tên nên 名 làm lượng từ đếm người: 四万多名学生."},{"char":"网上","pinyin":"wǎngshang","hanviet":"Võng thượng","chars":["网","上"],"story":"网 vẽ tấm lưới đánh cá: khung 冂 bên ngoài, hai chữ 乂 là các mắt lưới đan chéo. Ngày nay \"lưới\" được dùng chỉ mạng internet. 上 = phía trên. 网上 = trên mạng."},{"char":"外国","pinyin":"wàiguó","hanviet":"Ngoại quốc","chars":["外","国"],"story":"外 = 夕 (buổi tối) + 卜 (bói): người xưa bói vào buổi sáng, bói buổi tối là chuyện \"ngoài lệ\" → \"ngoài\". 国 = 囗 (vòng biên giới) + 玉 (ngọc, của báu) → \"đất nước\". 外国 = nước ngoài."},{"char":"间","pinyin":"jiān","hanviet":"Gian","chars":["间"],"story":"间 = 门 (cánh cửa) + 日 (mặt trời): ánh nắng lọt qua khe cửa → \"khoảng giữa, gian\". Một khoảng phòng là một gian → lượng từ cho phòng. Nhớ: 间 trong cửa là 日, còn 问 trong cửa là 口."},{"char":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","chars":["教","室"],"story":"教 = 孝 (phía trái) + 攵 (bàn tay cầm roi) → thầy cầm thước dạy dỗ → \"dạy\". 室 = 宀 (mái nhà) + 至 (đến) → nơi người đến ở bên trong → \"căn phòng\". 教室 = phòng để dạy học."},{"char":"票","pinyin":"piào","hanviet":"Phiếu","chars":["票"],"story":"票 gồm phần trên 覀 và phần dưới 示 (bàn thờ, chỉ dấu hiệu, bằng chứng). Ngày nay 票 là tờ giấy làm bằng chứng cho một quyền lợi — tấm vé, lá phiếu: 电影票 (vé xem phim), 车票 (vé xe)."},{"char":"别","pinyin":"bié","hanviet":"Biệt","chars":["别"],"story":"别 = 另 (bên trái) + 刂 (con dao): dùng dao tách rời ra → \"chia lìa, khác\" (分别, 别的). Làm phó từ đứng trước động từ thì mang nghĩa khuyên ngăn \"đừng\": 别看了."},{"char":"过来","pinyin":"guòlái","hanviet":"Quá lai","chars":["过","来"],"story":"过 = 辶 (bước đi) + 寸 → \"đi qua\". 来 vốn vẽ cây lúa mì, được mượn làm động từ \"đến\". 过来 = đi qua về phía người nói → \"qua đây, lại đây\". Ngược hướng là 过去 (qua đó)."},{"char":"北京大学","pinyin":"Běijīng Dàxué","hanviet":"Bắc Kinh Đại học","chars":["北","京","大","学"],"story":"北 vẽ hai người quay lưng vào nhau → \"phía bắc\". 京 vẽ toà nhà cao trên nền đất cao → \"kinh đô\". 大 = người dang rộng tay chân → \"lớn\". 学 = mái nhà có đứa trẻ 子 ngồi học bên dưới → \"học\". 北京大学 gọi tắt là 北大."}],"grammar":[{"title":"Cấu trúc cố định 还是……吧","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还是</b><small>tốt hơn là</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词短语</b><small>cách làm được chọn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吧</b><small>nhé, đi</small></span></div>","summary":"<p class=\"gr-lead\">Chọn phương án tốt hơn</p><ul><li>Sau khi <b>cân nhắc</b> tình hình, người nói chọn phương án mình thấy <b>tốt hơn</b> — mang ý \"làm thế này thì hơn\".</li><li>Thường đứng sau một câu nêu lý do: <span class=\"zh\">车站有点儿远，……还是打车去吧</span>.</li><li>Khuyên <b>không làm</b>: <span class=\"zh\">还是别……了</span> — <span class=\"zh\">还是别看电影了</span> (thôi đừng xem phim nữa).</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我们还是打车去吧。</span> = Hay là chúng mình bắt taxi đi nhé.</p>","note":"<b>Lưu ý:</b> Khác <span class=\"zh\">还是</span> trong câu hỏi lựa chọn (bài 10): <span class=\"zh\">A还是B？</span> = \"A hay B?\" — ở đây là <b>đề nghị</b>, cuối câu có <span class=\"zh\">吧</span>.","examples":[{"zh":"我们还是打车去吧。","py":"Wǒmen háishi dǎchē qù ba.","vi":"Hay là chúng mình bắt taxi đi nhé."},{"zh":"那件衣服很好看，还是买那件吧。","py":"Nà jiàn yīfu hěn hǎokàn, háishi mǎi nà jiàn ba.","vi":"Chiếc áo kia đẹp lắm, hay là mua chiếc đó đi."},{"zh":"你第一次去北京，还是找个人接你吧。","py":"Nǐ dì-yī cì qù Běijīng, háishi zhǎo ge rén jiē nǐ ba.","vi":"Lần đầu bạn đi Bắc Kinh, tốt hơn là tìm người ra đón."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">不好意思，我今天太忙了，你____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，我们去找天中帮忙。</span></span></span><span class=\"qz-hint\">Ngại quá, hôm nay mình bận quá, bạn nhờ người khác giúp nhé. — Được, bọn mình đi nhờ Thiên Trung giúp.</span>","answer":["还是找别人帮忙吧","还是找别人吧","还是找别人帮忙","还是找别人帮个忙吧"],"explain":"不好意思，我今天太忙了，你还是找别人帮忙吧。 (Bù hǎoyìsi, wǒ jīntiān tài máng le, nǐ háishi zhǎo biérén bāngmáng ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">明天有雨，我们____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，那就今天去。</span></span></span><span class=\"qz-hint\">Mai có mưa, hay là mình đi hôm nay đi. — Được, vậy đi hôm nay.</span>","answer":["还是今天去吧","还是今天去","今天去吧"],"explain":"明天有雨，我们还是今天去吧。 (Míngtiān yǒu yǔ, wǒmen háishi jīntiān qù ba.)"}]},{"title":"Dùng 多 biểu đạt số ước lượng","formula":"<div class=\"fx-lbl\">Số tròn chục</div><div class=\"fx-row\"><span class=\"fx-p\"><b>数词</b><small>10 · 20 · 100 · 万…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b><small>hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(名词)</b><small>danh từ</small></span></div><div class=\"fx-ex zh\">二十多个学生</div><div class=\"fx-lbl\">Số không tròn chục</div><div class=\"fx-row\"><span class=\"fx-p\"><b>数词</b><small>1–9 · 15 · 23…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b><small>hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(名词)</b><small>danh từ</small></span></div><div class=\"fx-ex zh\">五块多钱</div>","summary":"<p class=\"gr-lead\">Hơn…, …có lẻ</p><ul><li><span class=\"zh\">多</span> sau số = \"<b>hơn</b>, có lẻ\" · số <b>tròn chục</b> → trước lượng từ · số <b>lẻ</b> → sau lượng từ.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">北京大学有四万多名学生。</span>　·　<span class=\"zh\">教室里有二十多个学生。</span>　·　<span class=\"zh\">这两个苹果五块多钱。</span></p>","note":"<b>Lưu ý:</b> Đổi chỗ là đổi nghĩa: <span class=\"zh\">十多块钱</span> = mười mấy tệ · <span class=\"zh\">十块多钱</span> = hơn mười tệ một chút (10 tệ lẻ hào).","examples":[{"zh":"北京大学有四万多名学生呢！","py":"Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","vi":"Đại học Bắc Kinh có hơn bốn vạn sinh viên cơ mà!"},{"zh":"教室里有二十多个学生。","py":"Jiàoshì li yǒu èrshí duō ge xuéshēng.","vi":"Trong lớp có hơn hai mươi học sinh."},{"zh":"这两个苹果五块多钱。","py":"Zhè liǎng ge píngguǒ wǔ kuài duō qián.","vi":"Hai quả táo này hơn năm tệ."}],"exercises":[]},{"title":"Động từ / cụm động từ / cụm chủ-vị làm định ngữ","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词 / 动词短语 / 主谓短语</b><small>bổ sung đặc điểm, trạng thái</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>trợ từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span></div>","summary":"<p class=\"gr-lead\">Cụm động từ + 的 + danh từ</p><ul><li>Đặt động từ, cụm động từ hoặc cụm chủ-vị <b>trước</b> danh từ để nói rõ <b>đặc điểm, trạng thái</b> của danh từ.</li><li>Giữa phần bổ sung và danh từ <b>bắt buộc có</b> <span class=\"zh\">的</span>: <span class=\"zh\">朋友给我的杯子</span>.</li><li>Danh từ đã rõ thì có thể lược, chỉ giữ <span class=\"zh\">……的</span> (cụm chữ 的, bài 4): <span class=\"zh\">我买的</span> = cái mình mua.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">定语 · 汉语 ↔ 越南语</span> · Đối chiếu</h4><p>Hai thứ tiếng ngược trật tự</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · Đối chiếu tiếng Việt</div><div class=\"ct-intro\"><span class=\"ct-lg a\">Phần bổ sung</span><span class=\"ct-lg k\">的</span><span class=\"ct-lg b\">Danh từ</span>cùng màu = cùng thành phần, sang tiếng Việt chỉ <b>đổi chỗ</b></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Tiếng Trung<small>Bổ sung + 的 + Danh từ</small></th><th>Tiếng Việt<small>Danh từ + Bổ sung</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">妈妈做</b><small>māma zuò</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">菜</b><small>cài</small></span></div><div class=\"ct-vi\">mẹ nấu + 的 + món ăn</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">món ăn</span><span class=\"ct-w c-a\">mẹ nấu</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">来北京旅游</b><small>lái Běijīng lǚyóu</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">人</b><small>rén</small></span></div><div class=\"ct-vi\">đến Bắc Kinh du lịch + 的 + người</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">người</span><span class=\"ct-w c-a\">đến Bắc Kinh du lịch</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">我昨天买</b><small>wǒ zuótiān mǎi</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">书</b><small>shū</small></span></div><div class=\"ct-vi\">tôi hôm qua mua + 的 + sách</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">quyển sách</span><span class=\"ct-w c-a\">tôi mua hôm qua</span></div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他们卖的电影票</span> = vé xem phim họ bán　·　<span class=\"zh\">学中文的学生</span> = học sinh học tiếng Trung</p>","note":"<b>Lưu ý:</b> Tiếng Việt nói ngược — \"cốc <b>bạn tặng tôi</b>\"; tiếng Trung đưa phần bổ sung <b>lên trước</b>: ✗ <span class=\"zh\">杯子朋友给我的</span>.","examples":[{"zh":"他们卖的电影票也很便宜。","py":"Tāmen mài de diànyǐngpiào yě hěn piányi.","vi":"Vé xem phim họ bán cũng rất rẻ."},{"zh":"现在学中文的学生很多。","py":"Xiànzài xué Zhōngwén de xuéshēng hěn duō.","vi":"Bây giờ học sinh học tiếng Trung rất đông."},{"zh":"这是朋友给我的杯子。","py":"Zhè shì péngyou gěi wǒ de bēizi.","vi":"Đây là cái cốc bạn tặng mình."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这是谁____的苹果？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我买的，很好吃。</span></span></span><span class=\"qz-hint\">Đây là táo ai mua thế? — Mình mua đấy, ngon lắm.</span>","answer":["买"],"explain":"这是谁买的苹果？ (Zhè shì shéi mǎi de píngguǒ?)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在宾馆前台","titleVi":"Quầy lễ tân — hỏi cách đến Bắc Đại","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"请问，这儿有到北京大学的公交车吗？","py":"Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","vi":"Xin hỏi, ở đây có xe buýt đến Đại học Bắc Kinh không ạ?"},{"speaker":"员","name":"Nhân viên","zh":"有，但车站有点儿远。","py":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","vi":"Có, nhưng bến xe hơi xa."},{"speaker":"月","name":"Gia Nguyệt","zh":"这儿好打车吗？","py":"Zhèr hǎo dǎchē ma?","vi":"Ở đây có dễ bắt taxi không ạ?"},{"speaker":"员","name":"Nhân viên","zh":"好打车。","py":"Hǎo dǎchē.","vi":"Dễ bắt lắm."},{"speaker":"月","name":"Gia Nguyệt","zh":"谢谢。安妮，我们还是打车去吧。","py":"Xièxie. Ānnī, wǒmen háishi dǎchē qù ba.","vi":"Cảm ơn chị. Annie, hay là bọn mình bắt taxi đi nhé."},{"speaker":"妮","name":"Annie","zh":"好，没问题。","py":"Hǎo, méi wèntí.","vi":"Ừ, không vấn đề gì."}]},{"titleZh":"课文二 · 在北京大学","titleVi":"Trong Bắc Đại — tham quan trường","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"学校里人真多啊！","py":"Xuéxiào li rén zhēn duō a!","vi":"Trong trường đông người thật đấy!"},{"speaker":"妮","name":"Annie","zh":"是啊，北京大学有四万多名学生呢！","py":"Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","vi":"Đúng thế, Đại học Bắc Kinh có hơn bốn vạn sinh viên cơ mà!"},{"speaker":"月","name":"Gia Nguyệt","zh":"你是怎么知道的？","py":"Nǐ shì zěnme zhīdào de?","vi":"Sao cậu biết?"},{"speaker":"妮","name":"Annie","zh":"是网上说的，网上还说北京大学有三千多名外国学生。","py":"Shì wǎngshang shuō de, wǎngshang hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuéshēng.","vi":"Trên mạng nói đấy, trên mạng còn nói Bắc Đại có hơn ba nghìn sinh viên nước ngoài."},{"speaker":"月","name":"Gia Nguyệt","zh":"我也想来这儿学习。","py":"Wǒ yě xiǎng lái zhèr xuéxí.","vi":"Mình cũng muốn đến đây học."},{"speaker":"妮","name":"Annie","zh":"那边就有一间教室，我们去看一下吧。","py":"Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba.","vi":"Bên kia có một phòng học đấy, bọn mình qua xem một chút đi."}]},{"titleZh":"课文三 · 在北京大学","titleVi":"Trong Bắc Đại — thấy rạp chiếu phim","lines":[{"speaker":"妮","name":"Annie","zh":"家月，你看，学校里有家电影院！","py":"Jiāyuè, nǐ kàn, xuéxiào li yǒu jiā diànyǐngyuàn!","vi":"Gia Nguyệt, cậu nhìn kìa, trong trường có một rạp chiếu phim!"},{"speaker":"月","name":"Gia Nguyệt","zh":"是啊，电影院还不小。","py":"Shì a, diànyǐngyuàn hái bù xiǎo.","vi":"Ừ, rạp phim cũng không nhỏ đâu."},{"speaker":"妮","name":"Annie","zh":"他们卖的电影票也很便宜。","py":"Tāmen mài de diànyǐngpiào yě hěn piányi.","vi":"Vé xem phim họ bán cũng rất rẻ."},{"speaker":"月","name":"Gia Nguyệt","zh":"天啊！有的还不到二十块钱。","py":"Tiān a! Yǒude hái bú dào èrshí kuài qián.","vi":"Trời ơi! Có vé còn chưa đến hai mươi tệ."},{"speaker":"妮","name":"Annie","zh":"那你想不想去看个电影？","py":"Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?","vi":"Thế cậu có muốn đi xem phim không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"还是别看电影了，北京大学就很好看！","py":"Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!","vi":"Thôi đừng xem phim nữa, ngắm Bắc Đại thôi cũng đẹp lắm rồi!"}]},{"titleZh":"课文四 · 在北京大学门口","titleVi":"Cổng Bắc Đại — nhắn tin cho Thiên Trung","para":true,"speaker":"月","lines":[{"zh":"北京大学很大，有四万多名学生。","py":"Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuéshēng.","vi":"Đại học Bắc Kinh rất rộng, có hơn bốn vạn sinh viên."},{"zh":"学校很漂亮，里边还有家电影院，电影票也不贵，","py":"Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn, diànyǐngpiào yě bú guì,","vi":"Trường rất đẹp, bên trong còn có một rạp chiếu phim, vé cũng không đắt,"},{"zh":"我们有时间还想再过来看个电影。","py":"wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng.","vi":"khi nào có thời gian bọn mình còn muốn lại qua đây xem phim."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Đóng vai · Hỏi đường","q":{"zh":"一人问路，一人回答：有没有到新新电影院的公交车？车站远不远？","py":"Yì rén wèn lù, yì rén huídá: yǒu méiyǒu dào Xīnxīn Diànyǐngyuàn de gōngjiāochē? Chēzhàn yuǎn bu yuǎn?","vi":"Một người hỏi đường, một người trả lời: có xe buýt đến rạp Tân Tân không? Bến xe có xa không?"},"items":[{"lines":[{"who":"A","zh":"请问，这儿有到新新电影院的公交车吗？","py":"Qǐngwèn, zhèr yǒu dào Xīnxīn Diànyǐngyuàn de gōngjiāochē ma?","vi":"Xin hỏi, ở đây có xe buýt đến rạp Tân Tân không?"},{"who":"B","zh":"有，但车站有点儿远。","py":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","vi":"Có, nhưng bến xe hơi xa."}]},{"zh":"坐公交车要二十多分钟。","py":"Zuò gōngjiāochē yào èrshí duō fēnzhōng.","vi":"Đi xe buýt mất hơn hai mươi phút."},{"zh":"车站太远了，你还是打车去吧。","py":"Chēzhàn tài yuǎn le, nǐ háishi dǎchē qù ba.","vi":"Bến xe xa quá, bạn bắt taxi đi thì hơn."}]}],"speak":[]}},{"id":"k2v3-b03","courseId":"k2v3","order":3,"title":"Tôi muốn đi du lịch Tây An","titleZh":"我想去西安旅游","titlePy":"wǒ xiǎng qù Xī'ān lǚyóu","vocab":[{"stt":1,"hanzi":"回来","pinyin":"huílái","hanviet":"Hồi lai","pos":"Động từ","meaning":"trở về, quay lại (đây)","comps":"回来了 (về rồi), 回来晚 (về muộn)","example":{"zh":"你什么时候回来？","py":"Nǐ shénme shíhou huílái?","vi":"Khi nào bạn về?"}},{"stt":2,"hanzi":"这么","pinyin":"zhème","hanviet":"Giá ma","pos":"Đại từ","meaning":"thế này, như thế này","comps":"这么晚 (muộn thế này), 这么多 (nhiều thế này)","example":{"zh":"你有这么多书啊！","py":"Nǐ yǒu zhème duō shū a!","vi":"Bạn có nhiều sách thế!"}},{"stt":3,"hanzi":"完","pinyin":"wán","hanviet":"Hoàn","pos":"Động từ","meaning":"xong, hết","comps":"吃完 (ăn xong), 做完 (làm xong)","example":{"zh":"我吃完饭了。","py":"Wǒ chīwán fàn le.","vi":"Mình ăn cơm xong rồi."}},{"stt":4,"hanzi":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","pos":"Phó từ","meaning":"cùng nhau","comps":"一起去 (cùng đi), 一起吃饭 (cùng ăn cơm)","example":{"zh":"我们一起去吃饭吧。","py":"Wǒmen yìqǐ qù chī fàn ba.","vi":"Chúng mình cùng đi ăn cơm nhé."}},{"stt":5,"hanzi":"出去","pinyin":"chūqù","hanviet":"Xuất khứ","pos":"Động từ","meaning":"đi ra ngoài","comps":"出去玩 (ra ngoài chơi), 出去吃饭 (ra ngoài ăn)","example":{"zh":"今天天气很好，我们出去玩吧。","py":"Jīntiān tiānqì hěn hǎo, wǒmen chūqù wán ba.","vi":"Hôm nay trời đẹp, mình ra ngoài chơi đi."}},{"stt":6,"hanzi":"洗","pinyin":"xǐ","hanviet":"Tẩy","pos":"Động từ","meaning":"rửa, giặt","comps":"洗手 (rửa tay), 洗衣服 (giặt quần áo)","example":{"zh":"妈妈在洗衣服。","py":"Māma zài xǐ yīfu.","vi":"Mẹ đang giặt quần áo."}},{"stt":7,"hanzi":"自己","pinyin":"zìjǐ","hanviet":"Tự kỷ","pos":"Đại từ","meaning":"tự mình, bản thân","comps":"我自己 (tự tôi), 自己做 (tự làm)","example":{"zh":"我自己做饭。","py":"Wǒ zìjǐ zuò fàn.","vi":"Mình tự nấu cơm."}},{"stt":8,"hanzi":"拿","pinyin":"ná","hanviet":"Nã","pos":"Động từ","meaning":"cầm, lấy","comps":"拿东西 (cầm đồ), 拿来 (mang đến)","example":{"zh":"我去给你拿杯水。","py":"Wǒ qù gěi nǐ ná bēi shuǐ.","vi":"Mình đi lấy cho bạn cốc nước."}},{"stt":9,"hanzi":"手","pinyin":"shǒu","hanviet":"Thủ","pos":"Danh từ","meaning":"tay","comps":"洗手 (rửa tay), 手机 (điện thoại di động)","example":{"zh":"吃饭前要洗手。","py":"Chī fàn qián yào xǐ shǒu.","vi":"Trước khi ăn phải rửa tay."}},{"stt":10,"hanzi":"为什么","pinyin":"wèi shénme","hanviet":"Vị thập ma","pos":"Đại từ nghi vấn","meaning":"tại sao, vì sao","comps":"为什么不去 (sao không đi), 为什么想去 (sao muốn đi)","example":{"zh":"你为什么不去？","py":"Nǐ wèi shénme bú qù?","vi":"Sao bạn không đi?"}},{"stt":11,"hanzi":"不错","pinyin":"búcuò","hanviet":"Bất thác","pos":"Tính từ","meaning":"khá tốt, không tệ, hay","comps":"很不错 (rất tốt), 还不错 (cũng được)","example":{"zh":"这家饭店的菜很不错。","py":"Zhè jiā fàndiàn de cài hěn búcuò.","vi":"Món ăn của nhà hàng này rất ngon."}},{"stt":12,"hanzi":"送","pinyin":"sòng","hanviet":"Tống","pos":"Động từ","meaning":"đưa, tiễn; tặng","comps":"送孩子 (đưa con), 送礼物 (tặng quà)","example":{"zh":"爸爸开车送我去学校。","py":"Bàba kāichē sòng wǒ qù xuéxiào.","vi":"Bố lái xe đưa mình đến trường."}},{"stt":13,"hanzi":"回去","pinyin":"huíqù","hanviet":"Hồi khứ","pos":"Động từ","meaning":"quay về, trở về (đó)","comps":"回去上班 (về đi làm), 我要回去了 (tôi phải về đây)","example":{"zh":"太晚了，我要回去了。","py":"Tài wǎn le, wǒ yào huíqù le.","vi":"Muộn quá rồi, mình phải về đây."}},{"stt":14,"hanzi":"每","pinyin":"měi","hanviet":"Mỗi","pos":"Đại từ","meaning":"mỗi","comps":"每天 (mỗi ngày), 每个人 (mỗi người)","example":{"zh":"我每天七点起床。","py":"Wǒ měi tiān qī diǎn qǐchuáng.","vi":"Mỗi ngày mình dậy lúc bảy giờ."}},{"stt":15,"hanzi":"累","pinyin":"lèi","hanviet":"Luỵ","pos":"Tính từ","meaning":"mệt","comps":"很累 (rất mệt), 不累 (không mệt)","example":{"zh":"今天工作太多，我很累。","py":"Jīntiān gōngzuò tài duō, wǒ hěn lèi.","vi":"Hôm nay nhiều việc quá, mình rất mệt."}}],"hanzi":[{"char":"回来","pinyin":"huílái","hanviet":"Hồi lai","chars":["回","来"],"story":"回 vẽ hai vòng 口 lồng vào nhau — dòng nước xoáy cuộn vòng trở lại → \"quay về\". 来 vốn vẽ cây lúa mì, được mượn làm động từ \"đến\". 回来 = quay về phía người nói → \"trở về (đây)\"."},{"char":"这么","pinyin":"zhème","hanviet":"Giá ma","chars":["这","么"],"story":"这 = 辶 (bước đi) + 文: chỉ vật ở gần người nói → \"này\". 么 là hậu tố hay gặp (什么, 怎么). 这么 = \"như thế này\" — đứng trước tính từ để nhấn mạnh: 这么晚, 这么多."},{"char":"完","pinyin":"wán","hanviet":"Hoàn","chars":["完"],"story":"完 là chữ hình thanh: bộ Miên 宀 (mái nhà) chỉ nghĩa, 元 yuán chỉ âm. Nhà đã lợp mái là dựng xong trọn vẹn → \"xong, hết\". Hay đứng sau động từ: 吃完, 做完."},{"char":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","chars":["一","起"],"story":"一 = một. 起 = 走 (đi) chỉ nghĩa + 己 jǐ chỉ âm → \"đứng dậy, bắt đầu\". 一起 = cùng đứng dậy đi về một chỗ → \"cùng nhau\"."},{"char":"出去","pinyin":"chūqù","hanviet":"Xuất khứ","chars":["出","去"],"story":"出 vẽ bàn chân bước ra khỏi cái hố 凵 → \"ra\". 去 vốn vẽ người rời khỏi cửa → \"đi\". 出去 = đi ra ngoài, rời xa chỗ người nói. Ngược hướng là 出来 (ra đây)."},{"char":"洗","pinyin":"xǐ","hanviet":"Tẩy","chars":["洗"],"story":"洗 là chữ hình thanh: bộ Thuỷ 氵 (nước) chỉ nghĩa, 先 xiān chỉ âm. Có nước mới rửa, giặt được → \"rửa, giặt\": 洗手, 洗衣服."},{"char":"自己","pinyin":"zìjǐ","hanviet":"Tự kỷ","chars":["自","己"],"story":"自 vẽ cái mũi — người Trung Quốc khi nói \"tôi\" thường chỉ tay vào mũi mình, nên 自 mang nghĩa \"tự mình\". 己 vẽ sợi dây cuộn, được mượn chỉ \"bản thân\". 自己 = chính mình."},{"char":"拿","pinyin":"ná","hanviet":"Nã","chars":["拿"],"story":"拿 = 合 (khép lại) + 手 (bàn tay): khép bàn tay lại để nắm lấy đồ vật → \"cầm, lấy\". Chữ hội ý rất dễ nhớ."},{"char":"手","pinyin":"shǒu","hanviet":"Thủ","chars":["手"],"story":"手 là chữ tượng hình vẽ bàn tay xoè năm ngón. Khi làm bộ thủ bên trái chữ, 手 viết thành 扌 (bộ Thủ): 打, 拿 cũng có \"tay\" trong đó."},{"char":"为什么","pinyin":"wèi shénme","hanviet":"Vị thập ma","chars":["为","什","么"],"story":"为 (phồn thể 為) vốn vẽ bàn tay dắt con voi đi làm việc → \"làm\"; đọc wèi thì là \"vì, cho\". 什么 = cái gì. 为什么 = \"vì cái gì\" → tại sao."},{"char":"不错","pinyin":"búcuò","hanviet":"Bất thác","chars":["不","错"],"story":"不 = không. 错 = bộ Kim 钅 (kim loại) chỉ nghĩa + 昔 xī chỉ âm → \"sai, lầm\". 不错 nghĩa đen \"không sai\" → dùng để khen \"khá tốt, không tệ\". 不 trước thanh 4 đọc bú."},{"char":"送","pinyin":"sòng","hanviet":"Tống","chars":["送"],"story":"送 = 辶 (bước đi) + 关: đi theo người khác một đoạn → \"đưa, tiễn\" (送孩子去学校); đem đồ đến tận tay người ta → \"tặng\" (送礼物)."},{"char":"回去","pinyin":"huíqù","hanviet":"Hồi khứ","chars":["回","去"],"story":"回 = quay về (hai vòng 口 lồng nhau). 去 = đi, rời xa người nói. 回去 = quay về chỗ cũ, xa người nói. Nhớ theo cặp: 回来 (về đây) ↔ 回去 (về đó)."},{"char":"每","pinyin":"měi","hanviet":"Mỗi","chars":["每"],"story":"每 gồm phần trên 𠂉 và phần dưới 母 (người mẹ). Mẹo nhớ: \"mỗi người đều có một người mẹ\" → 每 = \"mỗi\": 每天, 每个人."},{"char":"累","pinyin":"lèi","hanviet":"Luỵ","chars":["累"],"story":"累 = 田 (ruộng) + 糸 (sợi tơ): cả ngày làm ruộng rồi lại dệt vải thì mệt rã rời → \"mệt\". Nhớ: 我很累 = tôi rất mệt."}],"grammar":[{"title":"Bổ ngữ kết quả (结果补语)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b><small>动词 / 形容词 chỉ kết quả</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Kết quả của động tác</p><ul><li>Một số động từ / tính từ đứng <b>ngay sau</b> động từ để nói <b>kết quả</b> của động tác.</li><li>Hay gặp: <span class=\"zh\">好</span> (xong, tốt) · <span class=\"zh\">完</span> (xong, hết) · <span class=\"zh\">懂</span> (hiểu) · <span class=\"zh\">对 / 错</span> (đúng / sai) · <span class=\"zh\">晚</span> (muộn).</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语</span> · Ba dạng câu</h4><p>KĐ · PĐ · Câu hỏi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>补语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">我吃完饭了。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>没(有)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>补语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">我没吃完饭。</div><div class=\"fx-lbl\">Câu hỏi</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>补语</b></span></div><div class=\"fx-ex zh\">你学没学会？</div></div><p class=\"gr-key\"><span class=\"hot\">Phủ định dùng <span class=\"zh\">没(有)</span> và <b>bỏ</b> <span class=\"zh\">了</span></span>　Hỏi: <span class=\"zh\">……了吗？</span> · <span class=\"zh\">……(了)没有？</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">菜都做好了。</span>　·　<span class=\"zh\">我吃完饭了。</span>　·　<span class=\"zh\">小雪今天来晚了。</span></p>","note":"<b>Lưu ý:</b> Động từ và bổ ngữ <b>dính liền</b>, tân ngữ đứng <b>sau</b> bổ ngữ: <span class=\"zh\">吃完饭</span> — ✗ <span class=\"zh\">吃饭完</span>.","examples":[{"zh":"菜都做好了。","py":"Cài dōu zuòhǎo le.","vi":"Đồ ăn nấu xong cả rồi."},{"zh":"我吃完饭了。","py":"Wǒ chīwán fàn le.","vi":"Mình ăn cơm xong rồi."},{"zh":"小雪今天来晚了。","py":"Xiǎoxuě jīntiān láiwǎn le.","vi":"Hôm nay Tiểu Tuyết đến muộn."},{"zh":"我没吃完饭。","py":"Wǒ méi chīwán fàn.","vi":"Mình chưa ăn xong cơm."},{"zh":"你吃完饭了吗？","py":"Nǐ chīwán fàn le ma?","vi":"Bạn ăn cơm xong chưa?"},{"zh":"你学没学会？","py":"Nǐ xué méi xuéhuì?","vi":"Bạn học biết chưa?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小明，你____衣服没有？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我穿好了。</span></span></span><span class=\"qz-hint\">Tiểu Minh, con mặc xong quần áo chưa? — Con mặc xong rồi.</span>","answer":["穿好"],"explain":"小明，你穿好衣服没有？ (Xiǎomíng, nǐ chuānhǎo yīfu méiyǒu?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">老师，我写完了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">很好，这几个字都____了。</span></span></span><span class=\"qz-hint\">Thưa cô, em viết xong rồi ạ. — Tốt lắm, mấy chữ này em đều viết đúng rồi.</span>","answer":["写对","写好"],"explain":"很好，这几个字都写对了。 (Hěn hǎo, zhè jǐ ge zì dōu xiěduì le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这本书你____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没看懂，我有很多问题。</span></span></span><span class=\"qz-hint\">Quyển sách này bạn đọc hiểu chưa? — Chưa hiểu, mình có nhiều câu hỏi lắm.</span>","answer":["看懂了吗","看懂了没有","看懂没有"],"explain":"这本书你看懂了吗？ (Zhè běn shū nǐ kàndǒng le ma?)"}]},{"title":"Động từ lặp lại (1)","formula":"<div class=\"fx-lbl\">Đơn âm tiết</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(一)</b><small>có thể thêm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>A</b></span></div><div class=\"fx-ex zh\">想(一)想　看看</div><div class=\"fx-lbl\">Song âm tiết</div><div class=\"fx-row\"><span class=\"fx-p\"><b>AB</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>AB</b></span></div><div class=\"fx-ex zh\">休息休息　介绍介绍</div><div class=\"fx-lbl\">Từ ly hợp</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>phần động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>phần tân ngữ</small></span></div><div class=\"fx-ex zh\">帮帮忙　洗洗手</div>","summary":"<p class=\"gr-lead\">Làm thử, làm chút</p><ul><li>Lặp động từ = thời gian <b>ngắn</b>, số lượng <b>ít</b>, hoặc <b>thử</b> làm; giọng <b>nhẹ nhàng, tuỳ ý</b>, hay dùng trong khẩu ngữ.</li></ul>","note":"<b>Lưu ý:</b> Chỉ lặp động từ chỉ <b>hành động</b> (lặp lại / kéo dài được) — không lặp <span class=\"zh\">是、有、在、喜欢</span>…","examples":[{"zh":"那你再想一想，你想好了，我来买票。","py":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","vi":"Vậy em nghĩ thêm đi, nghĩ xong thì anh mua vé."},{"zh":"我有点儿累，现在想休息休息。","py":"Wǒ yǒudiǎnr lèi, xiànzài xiǎng xiūxi xiūxi.","vi":"Mình hơi mệt, giờ muốn nghỉ ngơi một chút."},{"zh":"你能过来帮帮忙吗？","py":"Nǐ néng guòlái bāngbang máng ma?","vi":"Bạn qua đây giúp một tay được không?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">家月，学校里有没有超市？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我也不知道，你去____老师吧。</span></span></span><span class=\"qz-hint\">Gia Nguyệt, trong trường có siêu thị không? — Mình cũng không biết, bạn đi hỏi cô giáo thử xem.</span>","answer":["问问","问一问"],"explain":"我也不知道，你去问问老师吧。 (Wǒ yě bù zhīdào, nǐ qù wènwen lǎoshī ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">那个人是谁？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">你不认识？那我给你____。</span></span></span><span class=\"qz-hint\">Người kia là ai thế? — Bạn không quen à? Vậy để mình giới thiệu cho.</span>","answer":["介绍介绍","介绍一下"],"explain":"你不认识？那我给你介绍介绍。 (Nǐ bú rènshi? Nà wǒ gěi nǐ jièshào jièshào.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">他的歌真好听！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是吗？让我____。</span></span></span><span class=\"qz-hint\">Bài hát của anh ấy hay thật! — Thật à? Để mình nghe thử.</span>","answer":["听听","听一听"],"explain":"是吗？让我听听。 (Shì ma? Ràng wǒ tīngting.)"}]},{"title":"Động từ lặp lại (2) — việc đã xảy ra","formula":"<div class=\"fx-lbl\">Đơn âm tiết</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>A</b></span></div><div class=\"fx-ex zh\">看了看　想了想</div><div class=\"fx-lbl\">Song âm tiết</div><div class=\"fx-row\"><span class=\"fx-p\"><b>AB</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了一下</b></span></div><div class=\"fx-ex zh\">休息了一下</div><div class=\"fx-lbl\">Từ ly hợp</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span></div><div class=\"fx-ex zh\">帮了帮忙　洗了洗手</div>","summary":"<p class=\"gr-lead\">Đã làm qua một chút</p><ul><li>Nói việc <b>đã xảy ra</b>: thêm <span class=\"zh\">了</span> vào <b>giữa</b> hai động từ lặp.</li></ul>","note":"<b>Lưu ý:</b> Động từ <b>song âm tiết</b> thường <b>không lặp</b> khi có <span class=\"zh\">了</span> → dùng <span class=\"zh\">AB了一下</span>: ✗ <span class=\"zh\">休息了休息</span>.","examples":[{"zh":"我看了看网上的介绍。","py":"Wǒ kànle kàn wǎngshang de jièshào.","vi":"Mình đã xem qua giới thiệu trên mạng."},{"zh":"我休息了一下，现在觉得不累了。","py":"Wǒ xiūxile yíxià, xiànzài juéde bú lèi le.","vi":"Mình nghỉ một chút rồi, giờ thấy không mệt nữa."},{"zh":"他昨天来帮了帮忙。","py":"Tā zuótiān lái bāngle bāng máng.","vi":"Hôm qua anh ấy có đến giúp một tay."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">昨天你在家吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我有点儿事，____了一下。</span></span></span><span class=\"qz-hint\">Hôm qua bạn có ở nhà không? — Mình có chút việc nên ra ngoài một lát.</span>","answer":["出去"],"explain":"我有点儿事，出去了一下。 (Wǒ yǒu diǎnr shì, chūqùle yíxià.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你的手机是不是在桌子上？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我在桌子上____，但没有。</span></span></span><span class=\"qz-hint\">Điện thoại của bạn có phải ở trên bàn không? — Mình tìm thử trên bàn rồi, nhưng không có.</span>","answer":["找了找"],"explain":"我在桌子上找了找，但没有。 (Wǒ zài zhuōzi shang zhǎole zhǎo, dàn méiyǒu.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">昨天下午你做什么了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我在房间{{0}}书，{{1}}字。</span></span></span><span class=\"qz-hint\">Chiều hôm qua bạn làm gì? — Mình ở trong phòng đọc chút sách, viết chút chữ.</span>","blanks":[["看了看","看了一下"],["写了写","写了一下"]],"explain":"我在房间看了看书，写了写字。 (Wǒ zài fángjiān kànle kàn shū, xiěle xiě zì.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家门口","titleVi":"Ở cửa nhà — anh Lưu Minh đi làm về","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"今天回来这么晚啊！","py":"Jīntiān huílái zhème wǎn a!","vi":"Hôm nay anh về muộn thế!"},{"speaker":"明","name":"Lưu Minh","zh":"工作太多了，下班的时候没做完。","py":"Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","vi":"Việc nhiều quá, đến giờ tan làm vẫn chưa làm xong."},{"speaker":"雪","name":"Nhất Tuyết","zh":"菜都做好了，过来吃饭吧。","py":"Cài dōu zuòhǎo le, guòlái chī fàn ba.","vi":"Đồ ăn nấu xong cả rồi, lại đây ăn cơm đi."},{"speaker":"明","name":"Lưu Minh","zh":"我想休息一下，喝杯水。","py":"Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ.","vi":"Anh muốn nghỉ một chút, uống cốc nước đã."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好的。","py":"Hǎo de.","vi":"Vâng."}]},{"titleZh":"课文二 · 在客厅","titleVi":"Phòng khách — bàn chuyện đi du lịch","lines":[{"speaker":"明","name":"Lưu Minh","zh":"我们找个时间去旅游，怎么样？","py":"Wǒmen zhǎo ge shíjiān qù lǚyóu, zěnmeyàng?","vi":"Mình tìm lúc nào đi du lịch, em thấy sao?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"好啊，我也很想一起出去玩。","py":"Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán.","vi":"Hay đấy, em cũng rất muốn cùng đi chơi."},{"speaker":"明","name":"Lưu Minh","zh":"你想去哪儿？","py":"Nǐ xiǎng qù nǎr?","vi":"Em muốn đi đâu?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我还没想好呢。","py":"Wǒ hái méi xiǎnghǎo ne.","vi":"Em vẫn chưa nghĩ ra."},{"speaker":"明","name":"Lưu Minh","zh":"那你再想一想，你想好了，我来买票。","py":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","vi":"Vậy em nghĩ thêm đi, em nghĩ xong thì anh mua vé."}]},{"titleZh":"课文三 · 在客厅","titleVi":"Phòng khách — chọn đi Tây An","lines":[{"speaker":"明","name":"Lưu Minh","zh":"吃个苹果吧，我都洗好了。","py":"Chī ge píngguǒ ba, wǒ dōu xǐhǎo le.","vi":"Ăn quả táo đi, anh rửa sạch hết rồi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好的。","py":"Hǎo de.","vi":"Vâng."},{"speaker":"明","name":"Lưu Minh","zh":"就在桌子上，你自己拿。","py":"Jiù zài zhuōzi shang, nǐ zìjǐ ná.","vi":"Ở ngay trên bàn đấy, em tự lấy nhé."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我去洗洗手。对了，我们去西安旅游，怎么样？","py":"Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?","vi":"Em đi rửa tay đã. À phải rồi, mình đi Tây An du lịch, anh thấy sao?"},{"speaker":"明","name":"Lưu Minh","zh":"为什么想去西安？","py":"Wèi shénme xiǎng qù Xī'ān?","vi":"Sao lại muốn đi Tây An?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我看了看网上的介绍，这个时候去西安很不错！","py":"Wǒ kànle kàn wǎngshang de jièshào, zhège shíhou qù Xī'ān hěn búcuò!","vi":"Em xem qua giới thiệu trên mạng rồi, đi Tây An dịp này rất tuyệt!"}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — chị Nhất Tuyết gọi cho bạn thân","para":true,"speaker":"雪","lines":[{"zh":"早上，刘明开车送孩子去学校，","py":"Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào,","vi":"Buổi sáng, Lưu Minh lái xe đưa con đến trường,"},{"zh":"送完孩子回家后，医院就来电话了，让他回去上班。","py":"sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān.","vi":"đưa con xong vừa về nhà thì bệnh viện đã gọi điện, bảo anh ấy quay lại làm việc."},{"zh":"我觉得他这个月每天都很累，真想让他休息休息。","py":"Wǒ juéde tā zhège yuè měi tiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi.","vi":"Mình thấy tháng này ngày nào anh ấy cũng rất mệt, thật muốn để anh ấy nghỉ ngơi một chút."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hỏi · Đáp · Đi du lịch","q":{"zh":"互相问问：想不想去旅游？想好去哪儿了吗？为什么想去那儿？","py":"Hùxiāng wènwen: xiǎng bu xiǎng qù lǚyóu? Xiǎnghǎo qù nǎr le ma? Wèi shénme xiǎng qù nàr?","vi":"Hỏi nhau: có muốn đi du lịch không? Nghĩ xong đi đâu chưa? Vì sao muốn đến đó?"},"items":[{"lines":[{"who":"A","zh":"你想去旅游吗？","py":"Nǐ xiǎng qù lǚyóu ma?","vi":"Bạn có muốn đi du lịch không?"},{"who":"B","zh":"我想去旅游。","py":"Wǒ xiǎng qù lǚyóu.","vi":"Mình muốn đi du lịch."}]},{"zh":"你想好去哪儿了吗？","py":"Nǐ xiǎnghǎo qù nǎr le ma?","vi":"Bạn nghĩ xong đi đâu chưa?"},{"zh":"我看了看网上的介绍，……很不错！","py":"Wǒ kànle kàn wǎngshang de jièshào, …… hěn búcuò!","vi":"Mình xem qua giới thiệu trên mạng rồi, … tuyệt lắm!"}]}],"speak":[]},"review":{"range":"1–3","rows":[{"l":1,"zh":"语气助词 \"吧\" (2)","vi":"Trợ từ ngữ khí 吧 (2)","ex":{"zh":"你是老师吧？","py":"Nǐ shì lǎoshī ba?","vi":"Bạn là giáo viên nhỉ?"}},{"l":1,"zh":"\"是……的\" 句","vi":"Câu 是……的","ex":{"zh":"我是昨天到的。","py":"Wǒ shì zuótiān dào de.","vi":"Mình đến hôm qua."}},{"l":1,"zh":"兼语句","vi":"Câu kiêm ngữ","ex":{"zh":"我想请你帮个忙。","py":"Wǒ xiǎng qǐng nǐ bāng ge máng.","vi":"Mình muốn nhờ bạn giúp một việc."}},{"l":2,"zh":"固定格式 \"还是……吧\"","vi":"Cấu trúc 还是……吧","ex":{"zh":"我们还是打车去吧。","py":"Wǒmen háishi dǎchē qù ba.","vi":"Hay là mình bắt taxi đi nhé."}},{"l":2,"zh":"用 \"多\" 表达概数","vi":"Dùng 多 biểu đạt số ước lượng","ex":{"zh":"我有二十多本中文书。","py":"Wǒ yǒu èrshí duō běn Zhōngwén shū.","vi":"Mình có hơn 20 quyển sách tiếng Trung."}},{"l":2,"zh":"动词 (短语)、主谓短语作定语","vi":"Động từ / cụm C-V làm định ngữ","ex":{"zh":"你认识那个唱歌的人吗？","py":"Nǐ rènshi nàge chànggē de rén ma?","vi":"Bạn có quen người đang hát kia không?"}},{"l":3,"zh":"结果补语","vi":"Bổ ngữ kết quả","ex":{"zh":"我吃完饭了。","py":"Wǒ chīwán fàn le.","vi":"Mình ăn cơm xong rồi."}},{"l":3,"zh":"动词重叠 (1)","vi":"Động từ lặp lại (1)","ex":{"zh":"我想休息休息。","py":"Wǒ xiǎng xiūxi xiūxi.","vi":"Mình muốn nghỉ ngơi một chút."}},{"l":3,"zh":"动词重叠 (2)","vi":"Động từ lặp lại (2)","ex":{"zh":"我看了看这本书。","py":"Wǒ kànle kàn zhè běn shū.","vi":"Mình đã xem qua quyển sách này."}}]}},{"id":"k2v3-b04","courseId":"k2v3","order":4,"title":"Bạn mặc màu đỏ rất đẹp","titleZh":"你穿红色的很好看","titlePy":"nǐ chuān hóngsè de hěn hǎokàn","vocab":[{"stt":1,"hanzi":"过","pinyin":"guo","hanviet":"Quá","pos":"Trợ từ","meaning":"đã từng (trợ từ động thái)","comps":"去过 (đã từng đi), 没吃过 (chưa ăn bao giờ)","example":{"zh":"我去过北京。","py":"Wǒ qùguo Běijīng.","vi":"Mình đã từng đến Bắc Kinh."}},{"stt":2,"hanzi":"商场","pinyin":"shāngchǎng","hanviet":"Thương trường","pos":"Danh từ","meaning":"trung tâm thương mại","comps":"去商场 (đi trung tâm thương mại), 新开的商场 (TTTM mới mở)","example":{"zh":"这家商场很大。","py":"Zhè jiā shāngchǎng hěn dà.","vi":"Trung tâm thương mại này rất rộng."}},{"stt":3,"hanzi":"进去","pinyin":"jìnqù","hanviet":"Tiến khứ","pos":"Động từ","meaning":"đi vào (trong đó)","comps":"进去看看 (vào xem thử), 走进去 (đi vào)","example":{"zh":"我们进去看看吧。","py":"Wǒmen jìnqù kànkan ba.","vi":"Mình vào xem thử đi."}},{"stt":4,"hanzi":"条","pinyin":"tiáo","hanviet":"Điều","pos":"Lượng từ","meaning":"chiếc, con, cái (vật dài, mảnh)","comps":"一条裤子 (một chiếc quần), 一条鱼 (một con cá)","example":{"zh":"我想买一条裤子。","py":"Wǒ xiǎng mǎi yì tiáo kùzi.","vi":"Mình muốn mua một chiếc quần."}},{"stt":5,"hanzi":"裤子","pinyin":"kùzi","hanviet":"Khố tử","pos":"Danh từ","meaning":"quần","comps":"买裤子 (mua quần), 黑色的裤子 (quần màu đen)","example":{"zh":"这条裤子很好看。","py":"Zhè tiáo kùzi hěn hǎokàn.","vi":"Chiếc quần này rất đẹp."}},{"stt":6,"hanzi":"白色","pinyin":"báisè","hanviet":"Bạch sắc","pos":"Danh từ","meaning":"màu trắng","comps":"白色的衣服 (áo trắng), 喜欢白色 (thích màu trắng)","example":{"zh":"我喜欢白色。","py":"Wǒ xǐhuan báisè.","vi":"Mình thích màu trắng."}},{"stt":7,"hanzi":"因为","pinyin":"yīnwèi","hanviet":"Nhân vị","pos":"Liên từ","meaning":"vì, bởi vì","comps":"因为……所以…… (vì… nên…), 因为下雨 (vì trời mưa)","example":{"zh":"因为下雨，我没出去。","py":"Yīnwèi xià yǔ, wǒ méi chūqù.","vi":"Vì trời mưa nên mình không ra ngoài."}},{"stt":8,"hanzi":"试","pinyin":"shì","hanviet":"Thí","pos":"Động từ","meaning":"thử","comps":"试试 (thử xem), 试衣服 (thử quần áo)","example":{"zh":"你试试这件衣服吧。","py":"Nǐ shìshi zhè jiàn yīfu ba.","vi":"Bạn mặc thử chiếc áo này xem."}},{"stt":9,"hanzi":"红色","pinyin":"hóngsè","hanviet":"Hồng sắc","pos":"Danh từ","meaning":"màu đỏ","comps":"红色的裤子 (quần màu đỏ), 穿红色的 (mặc màu đỏ)","example":{"zh":"红色的衣服很漂亮。","py":"Hóngsè de yīfu hěn piàoliang.","vi":"Quần áo màu đỏ rất đẹp."}},{"stt":10,"hanzi":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","pos":"Liên từ","meaning":"cho nên, vì vậy","comps":"所以没去 (nên không đi), 所以要试试 (nên phải thử)","example":{"zh":"我生病了，所以没去上班。","py":"Wǒ shēngbìng le, suǒyǐ méi qù shàngbān.","vi":"Mình bị ốm nên không đi làm."}},{"stt":11,"hanzi":"书包","pinyin":"shūbāo","hanviet":"Thư bao","pos":"Danh từ","meaning":"cặp sách","comps":"新书包 (cặp mới), 我的书包 (cặp của tôi)","example":{"zh":"我的书包是黑色的。","py":"Wǒ de shūbāo shì hēisè de.","vi":"Cặp sách của mình màu đen."}},{"stt":12,"hanzi":"过去","pinyin":"guòqù","hanviet":"Quá khứ","pos":"Động từ","meaning":"đi qua (đó), sang (đó)","comps":"过去看看 (sang đó xem), 走过去 (đi qua đó)","example":{"zh":"那边卖书包，我们过去看看吧。","py":"Nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","vi":"Bên kia bán cặp, mình sang đó xem nhé."}},{"stt":13,"hanzi":"绿色","pinyin":"lǜsè","hanviet":"Lục sắc","pos":"Danh từ","meaning":"màu xanh lá","comps":"绿色的书包 (cặp xanh lá), 喜欢绿色 (thích màu xanh lá)","example":{"zh":"我喜欢绿色的书包。","py":"Wǒ xǐhuan lǜsè de shūbāo.","vi":"Mình thích chiếc cặp màu xanh lá."}},{"stt":14,"hanzi":"黑色","pinyin":"hēisè","hanviet":"Hắc sắc","pos":"Danh từ","meaning":"màu đen","comps":"黑色的裤子 (quần đen), 黑色的狗 (chó đen)","example":{"zh":"他穿了一条黑色的裤子。","py":"Tā chuānle yì tiáo hēisè de kùzi.","vi":"Anh ấy mặc một chiếc quần màu đen."}},{"stt":15,"hanzi":"更","pinyin":"gèng","hanviet":"Cánh","pos":"Phó từ","meaning":"càng, hơn","comps":"更好看 (đẹp hơn), 更喜欢 (thích hơn)","example":{"zh":"我觉得绿色的更好看。","py":"Wǒ juéde lǜsè de gèng hǎokàn.","vi":"Mình thấy cái màu xanh lá đẹp hơn."}},{"stt":16,"hanzi":"颜色","pinyin":"yánsè","hanviet":"Nhan sắc","pos":"Danh từ","meaning":"màu sắc","comps":"什么颜色 (màu gì), 颜色很多 (nhiều màu)","example":{"zh":"你喜欢什么颜色？","py":"Nǐ xǐhuan shénme yánsè?","vi":"Bạn thích màu gì?"}}],"hanzi":[{"char":"过","pinyin":"guo","hanviet":"Quá","chars":["过"],"story":"过 = 辶 (bước đi) + 寸 → \"đi qua\". Đọc guò là động từ (过来, 过去); đứng sau động từ đọc nhẹ guo thành trợ từ \"đã từng\" — việc đã \"đi qua\" trong đời: 去过, 吃过."},{"char":"商场","pinyin":"shāngchǎng","hanviet":"Thương trường","chars":["商","场"],"story":"商 = buôn bán (người nước Thương xưa nổi tiếng giỏi buôn bán, nên gọi người buôn là 商人). 场 = 土 (đất) chỉ nghĩa + 昜 chỉ âm → bãi đất rộng. 商场 = khu rộng lớn để buôn bán → trung tâm thương mại."},{"char":"进去","pinyin":"jìnqù","hanviet":"Tiến khứ","chars":["进","去"],"story":"进 = 辶 (bước đi) + 井 → \"tiến vào\". 去 = đi, rời xa người nói. 进去 = đi vào trong (người nói đứng ngoài). Cặp đối: 进来 (vào đây) ↔ 进去 (vào đó)."},{"char":"条","pinyin":"tiáo","hanviet":"Điều","chars":["条"],"story":"条 = 夂 + 木 (cây): cành cây nhỏ dài, mảnh → \"cành\". Từ đó làm lượng từ cho vật dài, mảnh: 一条裤子 (quần), 一条鱼 (cá), 一条路 (con đường)."},{"char":"裤子","pinyin":"kùzi","hanviet":"Khố tử","chars":["裤","子"],"story":"裤 là chữ hình thanh: bộ Y 衤 (áo, quần áo) chỉ nghĩa, 库 kù chỉ âm. 子 là hậu tố danh từ, đọc nhẹ. 裤子 = cái quần."},{"char":"白色","pinyin":"báisè","hanviet":"Bạch sắc","chars":["白","色"],"story":"白 vẽ đốm sáng của mặt trời vừa ló lên → \"sáng, trắng\". 色 = sắc, màu. 白色 = màu trắng. Các màu khác cũng ghép với 色: 红色, 绿色, 黑色."},{"char":"因为","pinyin":"yīnwèi","hanviet":"Nhân vị","chars":["因","为"],"story":"因 = 囗 (tấm chiếu) + 大 (người nằm dang tay chân): người nằm dựa trên chiếu → \"dựa vào\" → \"nguyên nhân\". 为 = vì. 因为 = bởi vì."},{"char":"试","pinyin":"shì","hanviet":"Thí","chars":["试"],"story":"试 là chữ hình thanh: bộ Ngôn 讠 (lời nói) chỉ nghĩa, 式 shì (khuôn phép) chỉ âm. Nghĩa gốc là dùng lời để thử, kiểm tra → \"thử\": 试试, 考试."},{"char":"红色","pinyin":"hóngsè","hanviet":"Hồng sắc","chars":["红","色"],"story":"红 = bộ Mịch 纟 (sợi tơ) chỉ nghĩa + 工 gōng chỉ âm → sợi tơ được nhuộm đỏ → \"đỏ\". 色 = màu. 红色 = màu đỏ — màu may mắn của người Trung Quốc."},{"char":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","chars":["所","以"],"story":"所 = 户 (cánh cửa) + 斤 (cái rìu) → nghĩa gốc là \"nơi, chốn\". 以 = lấy, dùng. 所以 = \"lấy đó (làm lý do) mà…\" → \"cho nên\". Thường đi cặp với 因为."},{"char":"书包","pinyin":"shūbāo","hanviet":"Thư bao","chars":["书","包"],"story":"书 = sách. 包 vẽ bào thai được bọc trong bụng mẹ → \"bọc, gói, túi\". 书包 = túi đựng sách → cặp sách."},{"char":"过去","pinyin":"guòqù","hanviet":"Quá khứ","chars":["过","去"],"story":"过 = đi qua. 去 = đi, rời xa người nói. 过去 = đi qua phía bên kia, xa người nói → \"sang đó\". Cặp đối với 过来 (lại đây) đã học ở bài 2."},{"char":"绿色","pinyin":"lǜsè","hanviet":"Lục sắc","chars":["绿","色"],"story":"绿 = bộ Mịch 纟 (sợi tơ) chỉ nghĩa + 录 lù chỉ âm → sợi tơ nhuộm màu xanh lá. 绿色 = màu xanh lá. Chú ý pinyin lǜ có ü."},{"char":"黑色","pinyin":"hēisè","hanviet":"Hắc sắc","chars":["黑","色"],"story":"黑 vẽ ống khói bám đầy muội than, bên dưới là lửa 灬 → \"đen\". 色 = màu. 黑色 = màu đen."},{"char":"更","pinyin":"gèng","hanviet":"Cánh","chars":["更"],"story":"更 có hai âm: đọc gēng nghĩa gốc là \"thay đổi, đổi mới\" (更换 — thay thế); đọc gèng thì thành phó từ \"càng, hơn nữa\" — từ ý \"đổi sang một mức khác\" mà ra. Nhớ 更好 (tốt hơn nữa), 更多 (nhiều hơn nữa)."},{"char":"颜色","pinyin":"yánsè","hanviet":"Nhan sắc","chars":["颜","色"],"story":"颜 = 彦 yàn chỉ âm + 页 (cái đầu, khuôn mặt) → \"nét mặt\". 色 = sắc. 颜色 nghĩa gốc là sắc mặt, nay chỉ chung \"màu sắc\"."}],"grammar":[{"title":"Trợ từ động thái 过","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b><small>đã từng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Đã từng làm</p><ul><li><span class=\"zh\">过</span> đặt <b>ngay sau động từ</b>: việc <b>đã từng</b> xảy ra trong quá khứ, nay không còn tiếp diễn — nói về <b>trải nghiệm</b>.</li><li>Đọc <b>nhẹ</b> guo; khác động từ <span class=\"zh\">过</span> guò (qua) trong <span class=\"zh\">过来 / 过去</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">动态助词 \"过\"</span> · Ba dạng câu</h4><p>KĐ · PĐ · Câu hỏi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b></span></div><div class=\"fx-ex zh\">她去过中国。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没(有)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b></span></div><div class=\"fx-ex zh\">她没去过中国。</div><div class=\"fx-lbl\">Câu hỏi</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b></span></div><div class=\"fx-ex zh\">你看没看过那个电影？</div></div><p class=\"gr-key\">Hỏi còn có: <span class=\"zh\">……过……吗？</span> · <span class=\"zh\">……过……没有？</span>　<span class=\"zh\">陈天中吃过饺子没有？</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">她去过中国。</span>　·　<span class=\"zh\">我吃过饺子，很好吃。</span></p>","note":"<b>Lưu ý:</b> Phủ định <span class=\"zh\">没(有) + 动词 + 过</span> — <b>giữ</b> <span class=\"zh\">过</span>, không dùng <span class=\"zh\">不</span>: ✗ <span class=\"zh\">她不去过中国</span>.","examples":[{"zh":"她去过中国。","py":"Tā qùguo Zhōngguó.","vi":"Cô ấy đã từng đến Trung Quốc."},{"zh":"我吃过饺子，很好吃。","py":"Wǒ chīguo jiǎozi, hěn hǎochī.","vi":"Mình từng ăn sủi cảo rồi, ngon lắm."},{"zh":"她没去过中国。","py":"Tā méi qùguo Zhōngguó.","vi":"Cô ấy chưa từng đến Trung Quốc."},{"zh":"我们来过这家商场吗？","py":"Wǒmen láiguo zhè jiā shāngchǎng ma?","vi":"Mình đã đến trung tâm thương mại này bao giờ chưa?"},{"zh":"陈天中吃过饺子没有？","py":"Chén Tiānzhōng chīguo jiǎozi méiyǒu?","vi":"Trần Thiên Trung đã từng ăn sủi cảo chưa?"},{"zh":"你看没看过那个电影？","py":"Nǐ kàn méi kànguo nàge diànyǐng?","vi":"Bạn đã xem bộ phim đó chưa?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今天晚上我想看个电影。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">这个电影不错，____，你也看看吧。</span></span></span><span class=\"qz-hint\">Tối nay mình muốn xem một bộ phim. — Phim này hay đấy, mình xem rồi, bạn cũng xem đi.</span>","answer":["我看过","看过","我看过了"],"explain":"这个电影不错，我看过，你也看看吧。 (Zhège diànyǐng búcuò, wǒ kànguo, nǐ yě kànkan ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这家超市的苹果好吃吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，我也不知道。</span></span></span><span class=\"qz-hint\">Táo ở siêu thị này có ngon không? — Mình chưa ăn bao giờ, mình cũng không biết.</span>","answer":["我没吃过","没吃过","我没有吃过"],"explain":"我没吃过，我也不知道。 (Wǒ méi chīguo, wǒ yě bù zhīdào.)"}]},{"title":"Câu phức nhân quả 因为……，所以……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>因为</b><small>vì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>原因</b><small>nguyên nhân</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，所以</b><small>nên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>结果</b><small>kết quả</small></span></div>","summary":"<p class=\"gr-lead\">Vì… nên…</p><ul><li>Vế trước nêu <b>nguyên nhân</b>, vế sau nêu <b>kết quả</b> — giống \"vì… nên…\" trong tiếng Việt.</li><li>Có thể dùng <b>cả cặp</b>, hoặc <b>chỉ một</b>: <span class=\"zh\">因为我生病了，今天没去上班</span> · <span class=\"zh\">我没去过他家，所以……</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">就是因为没穿过，所以要试试啊！</span> = Chính vì chưa mặc bao giờ nên mới phải thử!</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">所以</span> đứng <b>đầu vế sau</b>, trước chủ ngữ: <span class=\"zh\">所以我没去</span> — ✗ <span class=\"zh\">我所以没去</span>.","examples":[{"zh":"就是因为没穿过，所以要试试啊！","py":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","vi":"Chính vì chưa mặc bao giờ nên mới phải thử chứ!"},{"zh":"因为我生病了，今天没去上班。","py":"Yīnwèi wǒ shēngbìng le, jīntiān méi qù shàngbān.","vi":"Vì mình bị ốm nên hôm nay không đi làm."},{"zh":"我没去过他家，所以让他来车站接我。","py":"Wǒ méi qùguo tā jiā, suǒyǐ ràng tā lái chēzhàn jiē wǒ.","vi":"Mình chưa đến nhà anh ấy bao giờ, nên bảo anh ấy ra bến xe đón."}],"exercises":[]},{"title":"Cụm chữ 的 (的字短语)","formula":"<div class=\"fx-lbl\">Danh từ / Đại từ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>名词 / 代词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b></span></div><div class=\"fx-ex zh\">妈妈的　我的</div><div class=\"fx-lbl\">Động từ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>(主语) + 动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b></span></div><div class=\"fx-ex zh\">爸爸买的　妈妈做的</div><div class=\"fx-lbl\">Tính từ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>形容词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b></span></div><div class=\"fx-ex zh\">红色的　便宜的</div>","summary":"<p class=\"gr-lead\">…的 = cái…, người…</p><ul><li><span class=\"zh\">的</span> đặt sau danh từ, đại từ, động từ, tính từ → cụm <span class=\"zh\">……的</span> dùng <b>như một danh từ</b>.</li><li>Dùng khi danh từ <b>đã rõ</b>, khỏi nhắc lại: <span class=\"zh\">红色的</span> = <span class=\"zh\">红色的书包</span>.</li></ul>","note":"<b>Lưu ý:</b> Đừng quên <span class=\"zh\">的</span>: <span class=\"zh\">我要红色的</span> — ✗ <span class=\"zh\">我要红色</span> (= tôi muốn \"màu đỏ\").","examples":[{"zh":"红色的、绿色的、黑色的，你想买哪个？","py":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","vi":"Cái màu đỏ, xanh lá, đen — con muốn mua cái nào?"},{"zh":"这个面包是爸爸买的，妈妈买的在那儿。","py":"Zhège miànbāo shì bàba mǎi de, māma mǎi de zài nàr.","vi":"Cái bánh mì này bố mua, cái mẹ mua ở kia."},{"zh":"这件衣服太贵了，还是买那件便宜的吧。","py":"Zhè jiàn yīfu tài guì le, háishi mǎi nà jiàn piányi de ba.","vi":"Áo này đắt quá, hay là mua chiếc rẻ kia đi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你看见我的书了吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">桌子上那本是____吗？</span></span></span><span class=\"qz-hint\">Bạn có thấy sách của mình không? — Quyển trên bàn kia có phải của bạn không?</span>","answer":["你的"],"explain":"桌子上那本是你的吗？ (Zhuōzi shang nà běn shì nǐ de ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今天的饭菜是爸爸做的，好吃吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好吃，但我更喜欢吃妈妈____。</span></span></span><span class=\"qz-hint\">Cơm hôm nay bố nấu đấy, có ngon không? — Ngon ạ, nhưng con thích món mẹ nấu hơn.</span>","answer":["做的"],"explain":"好吃，但我更喜欢吃妈妈做的。 (Hǎochī, dàn wǒ gèng xǐhuan chī māma zuò de.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在商场门口","titleVi":"Cửa TTTM — hai mẹ con đi mua sắm","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，我们来过这家商场吗？","py":"Māma, wǒmen láiguo zhè jiā shāngchǎng ma?","vi":"Mẹ ơi, mình đã đến trung tâm thương mại này bao giờ chưa?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"没来过，这是新开的。","py":"Méi láiguo, zhè shì xīn kāi de.","vi":"Chưa đến bao giờ, chỗ này mới mở."},{"speaker":"小","name":"Tiểu Tuyết","zh":"我们进去看看吧。","py":"Wǒmen jìnqù kànkan ba.","vi":"Mình vào xem thử đi mẹ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好啊！你想买点儿什么？","py":"Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?","vi":"Được thôi! Con muốn mua gì nào?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"我想买条裤子。","py":"Wǒ xiǎng mǎi tiáo kùzi.","vi":"Con muốn mua một chiếc quần."},{"speaker":"雪","name":"Nhất Tuyết","zh":"没问题。","py":"Méi wèntí.","vi":"Không vấn đề gì."}]},{"titleZh":"课文二 · 在商场","titleVi":"Trong TTTM — chọn quần cho con","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，我想买这条白色的裤子。","py":"Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","vi":"Mẹ ơi, con muốn mua chiếc quần màu trắng này."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你有很多白色的衣服，为什么还买白色的？","py":"Nǐ yǒu hěn duō báisè de yīfu, wèi shénme hái mǎi báisè de?","vi":"Con có nhiều quần áo trắng rồi, sao còn mua màu trắng nữa?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"因为我喜欢白色啊！","py":"Yīnwèi wǒ xǐhuan báisè a!","vi":"Vì con thích màu trắng mà!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我觉得这条白色的不太好看，你试试那条红色的吧。","py":"Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba.","vi":"Mẹ thấy chiếc màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem."},{"speaker":"小","name":"Tiểu Tuyết","zh":"我没穿过红色的，红色的好看吗？","py":"Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?","vi":"Con chưa mặc màu đỏ bao giờ, màu đỏ có đẹp không ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"就是因为没穿过，所以要试试啊！","py":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","vi":"Chính vì chưa mặc bao giờ nên mới phải thử chứ!"}]},{"titleZh":"课文三 · 在商场","titleVi":"Trong TTTM — chọn cặp sách mới","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，我想买个新书包。","py":"Māma, wǒ xiǎng mǎi ge xīn shūbāo.","vi":"Mẹ ơi, con muốn mua một chiếc cặp mới."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好，那边卖书包，我们过去看看吧。","py":"Hǎo, nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","vi":"Được, bên kia bán cặp, mình sang đó xem nhé."},{"speaker":"小","name":"Tiểu Tuyết","zh":"这么多漂亮的书包！","py":"Zhème duō piàoliang de shūbāo!","vi":"Nhiều cặp đẹp thế!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"红色的、绿色的、黑色的，你想买哪个？","py":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","vi":"Màu đỏ, màu xanh lá, màu đen — con muốn mua cái nào?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"绿色的吧。","py":"Lǜsè de ba.","vi":"Cái màu xanh lá ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"不错，我也觉得绿色的更好看。","py":"Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn.","vi":"Được đấy, mẹ cũng thấy màu xanh lá đẹp hơn."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — Tiểu Tuyết viết nhật ký","para":true,"speaker":"小","lines":[{"zh":"我和妈妈去了一家商场。","py":"Wǒ hé māma qùle yì jiā shāngchǎng.","vi":"Mình và mẹ đã đi một trung tâm thương mại."},{"zh":"因为是新开的，所以这几天东西很便宜。","py":"Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi.","vi":"Vì mới khai trương nên mấy hôm nay đồ rất rẻ."},{"zh":"商场里的衣服颜色很多。","py":"Shāngchǎng li de yīfu yánsè hěn duō.","vi":"Quần áo trong trung tâm có rất nhiều màu."},{"zh":"我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。","py":"Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn.","vi":"Mình chưa mặc quần màu đỏ bao giờ, mẹ bảo mình thử, mình thấy mình mặc màu đỏ cũng rất đẹp."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Bán hàng · Mua quần","q":{"zh":"A是顾客，B是售货员。A想买裤子，问问颜色、大小和价钱。","py":"A shì gùkè, B shì shòuhuòyuán. A xiǎng mǎi kùzi, wènwen yánsè, dàxiǎo hé jiàqián.","vi":"A là khách, B là người bán hàng. A muốn mua quần, hỏi về màu sắc, cỡ và giá tiền."},"items":[{"lines":[{"who":"A","zh":"请问，你们有白色的裤子吗？","py":"Qǐngwèn, nǐmen yǒu báisè de kùzi ma?","vi":"Xin hỏi, ở đây có quần màu trắng không?"},{"who":"B","zh":"有，您看看。","py":"Yǒu, nín kànkan.","vi":"Có ạ, chị xem thử."}]},{"zh":"我可以试试吗？这条多少钱？","py":"Wǒ kěyǐ shìshi ma? Zhè tiáo duōshao qián?","vi":"Tôi thử được không? Chiếc này bao nhiêu tiền?"},{"zh":"有没有黑色的？黑色的更好看。","py":"Yǒu méiyǒu hēisè de? Hēisè de gèng hǎokàn.","vi":"Có màu đen không? Màu đen đẹp hơn."}]}],"speak":[]}},{"id":"k2v3-b05","courseId":"k2v3","order":5,"title":"Lần đầu đến nhà bạn Trung Quốc","titleZh":"第一次去中国朋友家","titlePy":"dì-yī cì qù Zhōngguó péngyou jiā","vocab":[{"stt":1,"hanzi":"快","pinyin":"kuài","hanviet":"Khoái","pos":"Phó từ / Tính từ","meaning":"mau, nhanh lên; nhanh","comps":"快来 (mau đến), 快点儿 (nhanh lên)","example":{"zh":"快下来吧，别晚了。","py":"Kuài xiàlái ba, bié wǎn le.","vi":"Mau xuống đi, đừng muộn."}},{"stt":2,"hanzi":"下来","pinyin":"xiàlái","hanviet":"Hạ lai","pos":"Động từ","meaning":"xuống (đây)","comps":"快下来 (mau xuống đây), 走下来 (đi xuống)","example":{"zh":"我在楼下，你下来吧。","py":"Wǒ zài lóu xià, nǐ xiàlái ba.","vi":"Mình ở dưới nhà, bạn xuống đây đi."}},{"stt":3,"hanzi":"上来","pinyin":"shànglái","hanviet":"Thượng lai","pos":"Động từ","meaning":"lên (đây)","comps":"你上来吧 (bạn lên đây đi), 拿上来 (mang lên đây)","example":{"zh":"还有时间，你上来吧。","py":"Hái yǒu shíjiān, nǐ shànglái ba.","vi":"Vẫn còn thời gian, bạn lên đây đi."}},{"stt":4,"hanzi":"上去","pinyin":"shàngqù","hanviet":"Thượng khứ","pos":"Động từ","meaning":"lên (đó)","comps":"不上去了 (không lên nữa), 走上去 (đi lên)","example":{"zh":"我不上去了，就在下面等你。","py":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","vi":"Mình không lên đâu, đợi bạn ở dưới này."}},{"stt":5,"hanzi":"下面","pinyin":"xiàmiàn","hanviet":"Hạ diện","pos":"Danh từ","meaning":"bên dưới, dưới nhà","comps":"在下面 (ở dưới), 桌子下面 (dưới bàn)","example":{"zh":"我在下面等你。","py":"Wǒ zài xiàmiàn děng nǐ.","vi":"Mình đợi bạn ở dưới."}},{"stt":6,"hanzi":"面","pinyin":"miàn","hanviet":"Diện","pos":"Hậu tố","meaning":"phía, mặt (tạo từ chỉ phương vị)","comps":"上面 (bên trên), 外面 (bên ngoài)","example":{"zh":"书在桌子上面。","py":"Shū zài zhuōzi shàngmiàn.","vi":"Sách ở trên bàn."}},{"stt":7,"hanzi":"等","pinyin":"děng","hanviet":"Đẳng","pos":"Động từ","meaning":"đợi, chờ","comps":"等你 (đợi bạn), 等一下 (đợi một chút)","example":{"zh":"请等一下。","py":"Qǐng děng yíxià.","vi":"Xin đợi một chút."}},{"stt":8,"hanzi":"一会儿","pinyin":"yíhuìr","hanviet":"Nhất hội nhi","pos":"Số lượng từ","meaning":"một lát, lát nữa","comps":"等一会儿 (đợi một lát), 一会儿见 (lát gặp)","example":{"zh":"那我一会儿就下去。","py":"Nà wǒ yíhuìr jiù xiàqù.","vi":"Vậy lát nữa mình xuống ngay."}},{"stt":9,"hanzi":"下去","pinyin":"xiàqù","hanviet":"Hạ khứ","pos":"Động từ","meaning":"xuống (đó)","comps":"下去接她 (xuống đón cô ấy), 走下去 (đi xuống)","example":{"zh":"家月到了，你下去接她吧。","py":"Jiāyuè dào le, nǐ xiàqù jiē tā ba.","vi":"Gia Nguyệt đến rồi, bạn xuống đón cô ấy đi."}},{"stt":10,"hanzi":"进来","pinyin":"jìnlái","hanviet":"Tiến lai","pos":"Động từ","meaning":"vào (đây)","comps":"快进来 (mau vào đi), 请进来 (mời vào)","example":{"zh":"快进来，外边很冷。","py":"Kuài jìnlái, wàibian hěn lěng.","vi":"Mau vào đi, bên ngoài lạnh lắm."}},{"stt":11,"hanzi":"爷爷","pinyin":"yéye","hanviet":"Gia gia","pos":"Danh từ","meaning":"ông nội","comps":"我爷爷 (ông nội tôi), 爷爷、奶奶 (ông bà nội)","example":{"zh":"这是我爷爷。","py":"Zhè shì wǒ yéye.","vi":"Đây là ông nội mình."}},{"stt":12,"hanzi":"奶奶","pinyin":"nǎinai","hanviet":"Nãi nãi","pos":"Danh từ","meaning":"bà nội","comps":"我奶奶 (bà nội tôi), 奶奶做的菜 (món bà nấu)","example":{"zh":"奶奶做的菜很好吃。","py":"Nǎinai zuò de cài hěn hǎochī.","vi":"Món bà nội nấu rất ngon."}},{"stt":13,"hanzi":"礼物","pinyin":"lǐwù","hanviet":"Lễ vật","pos":"Danh từ","meaning":"quà, món quà","comps":"送礼物 (tặng quà), 生日礼物 (quà sinh nhật)","example":{"zh":"这是送你们的礼物。","py":"Zhè shì sòng nǐmen de lǐwù.","vi":"Đây là quà tặng mọi người."}},{"stt":14,"hanzi":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","pos":"Động từ","meaning":"chuẩn bị","comps":"准备好了 (chuẩn bị xong rồi), 准备礼物 (chuẩn bị quà)","example":{"zh":"我给孩子们准备了礼物。","py":"Wǒ gěi háizimen zhǔnbèile lǐwù.","vi":"Mình chuẩn bị quà cho các cháu."}},{"stt":15,"hanzi":"奶茶","pinyin":"nǎichá","hanviet":"Nãi trà","pos":"Danh từ","meaning":"trà sữa","comps":"喝奶茶 (uống trà sữa), 一杯奶茶 (một cốc trà sữa)","example":{"zh":"我想喝杯奶茶。","py":"Wǒ xiǎng hē bēi nǎichá.","vi":"Mình muốn uống một cốc trà sữa."}},{"stt":16,"hanzi":"跟","pinyin":"gēn","hanviet":"Cân","pos":"Giới từ / Liên từ","meaning":"với, cùng; và","comps":"跟我去 (đi cùng tôi), 跟朋友一起 (cùng bạn bè)","example":{"zh":"你们可以跟我去看看。","py":"Nǐmen kěyǐ gēn wǒ qù kànkan.","vi":"Các bạn có thể đi cùng mình xem thử."}},{"stt":17,"hanzi":"走","pinyin":"zǒu","hanviet":"Tẩu","pos":"Động từ","meaning":"đi (bộ), rời đi","comps":"走路 (đi bộ), 走回去 (đi bộ về)","example":{"zh":"我们走回酒店吧。","py":"Wǒmen zǒuhuí jiǔdiàn ba.","vi":"Mình đi bộ về khách sạn đi."}},{"stt":18,"hanzi":"酒店","pinyin":"jiǔdiàn","hanviet":"Tửu điếm","pos":"Danh từ","meaning":"khách sạn","comps":"住酒店 (ở khách sạn), 回酒店 (về khách sạn)","example":{"zh":"这家酒店很漂亮。","py":"Zhè jiā jiǔdiàn hěn piàoliang.","vi":"Khách sạn này rất đẹp."}}],"hanzi":[{"char":"快","pinyin":"kuài","hanviet":"Khoái","chars":["快"],"story":"快 là chữ hình thanh: bộ Tâm 忄 (lòng) chỉ nghĩa, 夬 guài chỉ âm. Nghĩa gốc là \"lòng vui sướng\" (快乐), từ cảm giác sảng khoái mà ra nghĩa \"nhanh\". Đứng đầu câu cầu khiến = \"mau lên\": 快下来吧."},{"char":"下来","pinyin":"xiàlái","hanviet":"Hạ lai","chars":["下","来"],"story":"下 = vạch ngang là mặt đất, nét chấm phía dưới chỉ vị trí \"bên dưới\" → \"xuống\". 来 = đến (về phía người nói). 下来 = đi xuống về phía người nói — người nói đang ở dưới."},{"char":"上来","pinyin":"shànglái","hanviet":"Thượng lai","chars":["上","来"],"story":"上 = vạch ngang là mặt đất, nét phía trên chỉ vị trí \"bên trên\" → \"lên\". 来 = về phía người nói. 上来 = đi lên chỗ người nói — người nói đang ở trên."},{"char":"上去","pinyin":"shàngqù","hanviet":"Thượng khứ","chars":["上","去"],"story":"上 = lên. 去 = đi, rời xa người nói. 上去 = đi lên chỗ khác, xa người nói — người nói đang ở dưới. Cặp đối: 上来 ↔ 上去."},{"char":"下面","pinyin":"xiàmiàn","hanviet":"Hạ diện","chars":["下","面"],"story":"下 = bên dưới. 面 vẽ khuôn mặt người (khung ngoài là gương mặt, bên trong là mắt) → \"mặt\", rồi \"phía\". 下面 = phía dưới."},{"char":"面","pinyin":"miàn","hanviet":"Diện","chars":["面"],"story":"面 là chữ tượng hình vẽ khuôn mặt người: khung ngoài là gương mặt, nét bên trong là con mắt → \"mặt\". Từ \"mặt\" thành \"phía\": ghép sau 上 / 下 / 里 / 外 / 前 / 后 tạo từ phương vị — 上面, 下面, 外面."},{"char":"等","pinyin":"děng","hanviet":"Đẳng","chars":["等"],"story":"等 = bộ Trúc ⺮ (thẻ tre) + 寺 (nơi làm việc của quan). Xưa sắp xếp thẻ tre thành từng hàng, từng bậc → \"bậc, loại\"; đứng xếp hàng chờ đến lượt → \"đợi\"."},{"char":"一会儿","pinyin":"yíhuìr","hanviet":"Nhất hội nhi","chars":["一","会","儿"],"story":"一 = một. 会 = hội họp, gặp gỡ → khoảnh khắc. 儿 là hậu tố er (giọng Bắc Kinh). 一会儿 = một khoảnh khắc → \"một lát\". Đọc yíhuìr: 一 trước thanh 4 đổi thành yí."},{"char":"下去","pinyin":"xiàqù","hanviet":"Hạ khứ","chars":["下","去"],"story":"下 = xuống. 去 = đi, rời xa người nói. 下去 = đi xuống chỗ khác — người nói đang ở trên. Cặp đối: 下来 ↔ 下去."},{"char":"进来","pinyin":"jìnlái","hanviet":"Tiến lai","chars":["进","来"],"story":"进 = 辶 (bước đi) + 井 → \"tiến vào\". 来 = về phía người nói. 进来 = đi vào chỗ người nói đang ở (người nói ở trong). Cặp đối với 进去 (bài 4)."},{"char":"爷爷","pinyin":"yéye","hanviet":"Gia gia","chars":["爷","爷"],"story":"爷 = 父 (cha) ở trên + 卩 ở dưới: người đứng trên cả cha → \"ông\". Lặp lại thành 爷爷 nghe thân mật = ông nội."},{"char":"奶奶","pinyin":"nǎinai","hanviet":"Nãi nãi","chars":["奶","奶"],"story":"奶 = bộ Nữ 女 (phụ nữ) + 乃 nǎi chỉ âm → \"sữa\"; người phụ nữ lớn tuổi trong nhà gọi là 奶奶 = bà nội. Từ lặp, âm sau đọc nhẹ: nǎinai."},{"char":"礼物","pinyin":"lǐwù","hanviet":"Lễ vật","chars":["礼","物"],"story":"礼 = bộ Kỳ 礻 (thần linh, cúng tế) + 乚: nghi lễ cúng tế → \"lễ\". 物 = bộ Ngưu 牛 (con trâu) + 勿 wù chỉ âm → \"vật\". 礼物 = vật mang theo khi đi lễ, thăm hỏi → món quà."},{"char":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","chars":["准","备"],"story":"准 = 冫 + 隹 (con chim): nhắm chuẩn như bắn chim → \"chuẩn, đúng\". 备 = sắp sẵn, đầy đủ (备 vốn vẽ ống tên đựng sẵn mũi tên). 准备 = sắp sẵn cho chuẩn → chuẩn bị."},{"char":"奶茶","pinyin":"nǎichá","hanviet":"Nãi trà","chars":["奶","茶"],"story":"奶 = sữa (女 + 乃). 茶 = bộ Thảo 艹 (cỏ cây) + 人 + 木 (cây): người hái lá cây để pha uống → \"trà\". 奶茶 = trà pha sữa — trà sữa."},{"char":"跟","pinyin":"gēn","hanviet":"Cân","chars":["跟"],"story":"跟 là chữ hình thanh: bộ Túc ⻊ (bàn chân) chỉ nghĩa, 艮 gèn chỉ âm. Nghĩa gốc là \"gót chân\" → đi theo gót ai đó → \"theo, cùng với\": 跟我去."},{"char":"走","pinyin":"zǒu","hanviet":"Tẩu","chars":["走"],"story":"走 vẽ người vung tay sải bước trên, bàn chân 止 dưới → nghĩa gốc là \"chạy\". Tiếng Trung hiện đại dùng 走 là \"đi (bộ), rời đi\": 走路, 走回酒店."},{"char":"酒店","pinyin":"jiǔdiàn","hanviet":"Tửu điếm","chars":["酒","店"],"story":"酒 = 氵 (chất lỏng) + 酉 (vò rượu) → \"rượu\". 店 = 广 (mái hiên) + 占 zhàn chỉ âm → \"cửa hàng\". 酒店 nghĩa gốc là quán rượu, nay dùng chỉ \"khách sạn\" lớn."}],"grammar":[{"title":"Bổ ngữ xu hướng đơn (1): Động từ + 来 / 去","formula":"<div class=\"fx-lbl\">Về phía người nói</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>上 下 进 出 回 过…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来</b><small>lại đây</small></span></div><div class=\"fx-ex zh\">你上来吧。</div><div class=\"fx-lbl\">Ra xa người nói</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>上 下 进 出 回 过…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>去</b><small>đi đến đó</small></span></div><div class=\"fx-ex zh\">我不上去了。</div>","summary":"<p class=\"gr-lead\">Hướng động tác</p><ul><li><span class=\"zh\">来</span>: động tác hướng <b>về phía người nói</b> · <span class=\"zh\">去</span>: động tác hướng <b>ra xa người nói</b>.</li><li>Còn dùng với <span class=\"zh\">叫、开、买、拿、请、送、要、找、走</span>: <span class=\"zh\">拿来、送去</span> · <span class=\"zh\">起来</span> = dậy, hướng lên.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">……来 · ……去</span> · Bảng tổng hợp</h4><p>6 cặp hay dùng</p><div class=\"ct-box\"><div class=\"ct-cap\">Bảng · 来 ↔ 去</div><div class=\"ct-intro\"><span class=\"ct-lg k\">来</span> về phía người nói　<span class=\"ct-lg a\">去</span> ra xa người nói</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>…来<small>về phía người nói</small></th><th>…去<small>ra xa người nói</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">上</b><small>shàng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">lên đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">上</b><small>shàng</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">lên đó</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">下</b><small>xià</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">xuống đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">下</b><small>xià</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">xuống đó</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">进</b><small>jìn</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">vào đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">进</b><small>jìn</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">vào đó</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">出</b><small>chū</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">ra đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">出</b><small>chū</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">ra đó (ra ngoài)</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">回</b><small>huí</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">về đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">回</b><small>huí</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">về đó</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">过</b><small>guò</small></span><span class=\"ct-w c-k\"><b class=\"zh\">来</b><small>lái</small></span></div><div class=\"ct-vi\">qua đây</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">过</b><small>guò</small></span><span class=\"ct-w c-a\"><b class=\"zh\">去</b><small>qù</small></span></div><div class=\"ct-vi\">qua đó</div></td></tr></tbody></table></div></div></div>","note":"","examples":[{"zh":"我不上去了，就在下面等你。","py":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","vi":"Mình không lên đâu, đợi bạn ở dưới này."},{"zh":"家月到下边了，你下去接她吧。","py":"Jiāyuè dào xiàbian le, nǐ xiàqù jiē tā ba.","vi":"Gia Nguyệt đến dưới rồi, bạn xuống đón cô ấy đi."},{"zh":"我在外边呢，你出来吧。","py":"Wǒ zài wàibian ne, nǐ chūlái ba.","vi":"Mình đang ở bên ngoài, bạn ra đây đi."},{"zh":"她拿来一本中文书。","py":"Tā nálái yì běn Zhōngwén shū.","vi":"Cô ấy mang đến một quyển sách tiếng Trung."},{"zh":"你别过来拿了，我给你送去。","py":"Nǐ bié guòlái ná le, wǒ gěi nǐ sòngqù.","vi":"Bạn đừng qua lấy nữa, mình mang sang cho."},{"zh":"今天早上5点她就起来了。","py":"Jīntiān zǎoshang wǔ diǎn tā jiù qǐlái le.","vi":"Sáng nay 5 giờ cô ấy đã dậy rồi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这就是我家，____看看吧。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">你家真漂亮！</span></span></span><span class=\"qz-hint\">Đây là nhà mình, vào xem đi. — Nhà bạn đẹp thật!</span>","answer":["进来"],"explain":"这就是我家，进来看看吧。 (Zhè jiù shì wǒ jiā, jìnlái kànkan ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这些人都是你____的吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对，他们都是我的朋友，你有事可以让他们帮忙。</span></span></span><span class=\"qz-hint\">Những người này đều do bạn gọi đến à? — Đúng, họ đều là bạn mình, bạn có việc có thể nhờ họ giúp.</span>","answer":["叫来","请来"],"explain":"这些人都是你叫来的吗？ (Zhèxiē rén dōu shì nǐ jiàolái de ma?)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">喂！刘小雪，你什么时候{{0}}？我们都在下面等你呢。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">不好意思，我现在就{{1}}。</span></span></span><span class=\"qz-hint\">A lô! Tiểu Tuyết, khi nào cậu xuống? Bọn mình đang đợi ở dưới. — Ngại quá, mình xuống ngay đây.</span>","blanks":[["下来"],["下去"]],"explain":"喂！刘小雪，你什么时候下来？我们都在下面等你呢。 (Wèi! Liú Xiǎoxuě, nǐ shénme shíhou xiàlái? Wǒmen dōu zài xiàmiàn děng nǐ ne.) · 不好意思，我现在就下去。 (Bù hǎoyìsi, wǒ xiànzài jiù xiàqù.)"}]},{"title":"Bổ ngữ xu hướng đơn (2): vị trí tân ngữ","formula":"<div class=\"fx-lbl\">Nơi chốn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>进 回 上…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>地点</b><small>nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span></div><div class=\"fx-ex zh\">快进教室来吧。</div><div class=\"fx-lbl\">Sự vật (1)</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>事物</b><small>đồ vật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span></div><div class=\"fx-ex zh\">还拿这么多礼物来！</div><div class=\"fx-lbl\">Sự vật (2)</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>事物</b><small>đồ vật</small></span></div><div class=\"fx-ex zh\">家月给我送来了一本书。</div>","summary":"<p class=\"gr-lead\">Vị trí tân ngữ</p><p class=\"gr-key\"><b>Câu mẫu:</b> Mở rộng: <span class=\"zh\">买、拿、走…</span> + <span class=\"zh\">回、出、进…</span> + tân ngữ　<span class=\"zh\">爸爸买回了很多水果。</span></p>","note":"<b>Lưu ý:</b> Không đặt nơi chốn sau <span class=\"zh\">来 / 去</span>: <span class=\"zh\">进教室来</span> — ✗ <span class=\"zh\">进来教室</span>.","examples":[{"zh":"你们太客气了，还拿这么多礼物来！","py":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","vi":"Các cháu khách sáo quá, còn mang nhiều quà đến thế!"},{"zh":"家月给我送来了一本书。","py":"Jiāyuè gěi wǒ sònglái le yì běn shū.","vi":"Gia Nguyệt mang đến cho mình một quyển sách."},{"zh":"上课了，你们快进教室来吧。","py":"Shàngkè le, nǐmen kuài jìn jiàoshì lái ba.","vi":"Vào học rồi, các em mau vào lớp đi."},{"zh":"爸爸今天买回了很多水果。","py":"Bàba jīntiān mǎihuí le hěn duō shuǐguǒ.","vi":"Hôm nay bố mua về rất nhiều hoa quả."},{"zh":"妈妈拿出了二十块钱，让小雪自己去买点儿吃的。","py":"Māma náchū le èrshí kuài qián, ràng Xiǎoxuě zìjǐ qù mǎi diǎnr chī de.","vi":"Mẹ lấy ra hai mươi tệ, bảo Tiểu Tuyết tự đi mua chút đồ ăn."}],"exercises":[{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小李没来吃饭吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">他吃完了，已经{{0}}公司{{1}}了。</span></span></span><span class=\"qz-hint\">Tiểu Lý không đến ăn cơm à? — Cậu ấy ăn xong rồi, đã về công ty rồi.</span>","blanks":[["回"],["去"]],"explain":"他吃完了，已经回公司去了。 (Tā chīwán le, yǐjīng huí gōngsī qù le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这么多水果是谁____的？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">家月和李文。你现在想吃吗？我去洗一洗。</span></span></span><span class=\"qz-hint\">Nhiều hoa quả thế này là ai mang đến? — Gia Nguyệt và Lý Văn. Giờ bạn muốn ăn không? Mình đi rửa.</span>","answer":["送来","拿来","买来"],"explain":"这么多水果是谁送来的？ (Zhème duō shuǐguǒ shì shéi sònglái de?)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你看见天中了吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我看见他{{0}}书店{{1}}了。</span></span></span><span class=\"qz-hint\">Bạn có thấy Thiên Trung không? — Mình thấy cậu ấy đi vào hiệu sách rồi.</span>","blanks":[["走进"],["去"]],"explain":"我看见他走进书店去了。 (Wǒ kànjiàn tā zǒujìn shūdiàn qù le.)"}]},{"title":"Cấu trúc cố định 都……了","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>都</b><small>đã… tận</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>时间 / 数量 / 情况</b><small>thời gian · số lượng · sự việc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Đã… rồi đấy!</p><ul><li><span class=\"zh\">都……了</span> = \"<b>đã</b>… rồi / đã đến mức…\", giọng <b>nhấn mạnh</b>, nhiều khi <b>không hài lòng</b>, giục giã.</li><li>Hay đi với giờ giấc, tuổi tác, số lượng: <span class=\"zh\">都12点了</span> · <span class=\"zh\">我都去过北京了</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">都12点了，我们吃饭吧。</span>　·　<span class=\"zh\">都8点半了，你还不起床吗？</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">都</span> ở đây <b>không</b> nghĩa là \"đều\"; cuối câu <b>bắt buộc</b> có <span class=\"zh\">了</span>.","examples":[{"zh":"都12点了，我们吃饭吧。","py":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","vi":"12 giờ rồi đấy, chúng ta ăn cơm thôi."},{"zh":"都8点半了，你还不起床吗？","py":"Dōu bā diǎn bàn le, nǐ hái bù qǐchuáng ma?","vi":"8 rưỡi rồi, con vẫn chưa dậy à?"},{"zh":"我都去过北京了，不想再去了。","py":"Wǒ dōu qùguo Běijīng le, bù xiǎng zài qù le.","vi":"Mình đi Bắc Kinh rồi, không muốn đi nữa."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你这么晚回来，我们____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没关系，我在公司吃饭了。</span></span></span><span class=\"qz-hint\">Anh về muộn thế, cả nhà ăn cơm xong rồi. — Không sao, anh ăn ở công ty rồi.</span>","answer":["都吃完饭了","都吃完了","都吃过饭了"],"explain":"你这么晚回来，我们都吃完饭了。 (Nǐ zhème wǎn huílái, wǒmen dōu chīwán fàn le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你的病____，为什么还不去上班？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我想再休息休息。</span></span></span><span class=\"qz-hint\">Bệnh của bạn khỏi rồi, sao vẫn chưa đi làm? — Mình muốn nghỉ thêm chút nữa.</span>","answer":["都好了"],"explain":"你的病都好了，为什么还不去上班？ (Nǐ de bìng dōu hǎo le, wèi shénme hái bú qù shàngbān?)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在宾馆楼下","titleVi":"Dưới khách sạn — Annie gọi Gia Nguyệt","lines":[{"speaker":"妮","name":"Annie","zh":"家月，快下来吧，第一次去中国朋友家，别晚了。","py":"Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","vi":"Gia Nguyệt, mau xuống đi, lần đầu đến nhà bạn Trung Quốc, đừng đến muộn."},{"speaker":"月","name":"Gia Nguyệt","zh":"还有时间，你上来吧。","py":"Hái yǒu shíjiān, nǐ shànglái ba.","vi":"Vẫn còn thời gian mà, cậu lên đây đi."},{"speaker":"妮","name":"Annie","zh":"我不上去了，就在下面等你。","py":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","vi":"Mình không lên đâu, đợi cậu ở dưới này."},{"speaker":"月","name":"Gia Nguyệt","zh":"那我一会儿就下去。","py":"Nà wǒ yíhuìr jiù xiàqù.","vi":"Vậy lát nữa mình xuống ngay."},{"speaker":"妮","name":"Annie","zh":"你快点儿吧。","py":"Nǐ kuài diǎnr ba.","vi":"Cậu nhanh lên nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"没事，一雪姐说11点前到就可以。","py":"Méishì, Yīxuě jiě shuō shíyī diǎn qián dào jiù kěyǐ.","vi":"Không sao, chị Nhất Tuyết nói trước 11 giờ đến là được."}]},{"titleZh":"课文二 · 在王一雪家","titleVi":"Nhà chị Nhất Tuyết — đến làm khách","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","py":"Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai.","vi":"Gia Nguyệt, Annie, mau vào đi! Chị giới thiệu nhé, đây là ông nội, bà nội của bọn trẻ."},{"speaker":"妮","name":"Nguyệt, Annie","zh":"你们好！","py":"Nǐmen hǎo!","vi":"Chào ông bà ạ!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","py":"Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuéshēng.","vi":"Bố, mẹ, đây là Bạch Gia Nguyệt, đây là Annie. Hai em đều là học sinh của Nhất Phi."},{"speaker":"爷","name":"Ông Lưu","zh":"家月、安妮，你们好！","py":"Jiāyuè, Ānnī, nǐmen hǎo!","vi":"Gia Nguyệt, Annie, chào các cháu!"},{"speaker":"月","name":"Gia Nguyệt","zh":"这是送你们的礼物。","py":"Zhè shì sòng nǐmen de lǐwù.","vi":"Đây là quà tặng ông bà ạ."},{"speaker":"爷","name":"Ông Lưu","zh":"你们太客气了，还拿这么多礼物来！","py":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","vi":"Các cháu khách sáo quá, còn mang nhiều quà đến thế!"},{"speaker":"月","name":"Gia Nguyệt","zh":"一雪姐，这是给孩子们准备的礼物。","py":"Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù.","vi":"Chị Nhất Tuyết, đây là quà chuẩn bị cho các cháu ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"谢谢！你们别客气，快坐吧！","py":"Xièxie! Nǐmen bié kèqi, kuài zuò ba!","vi":"Cảm ơn em! Các em đừng khách sáo, ngồi đi!"}]},{"titleZh":"课文三 · 在王一雪家","titleVi":"Nhà chị Nhất Tuyết — cùng ăn cơm","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"都12点了，我们吃饭吧。","py":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","vi":"12 giờ rồi đấy, chúng ta ăn cơm thôi."},{"speaker":"月","name":"Gia Nguyệt","zh":"这么多好吃的，您太客气了！","py":"Zhème duō hǎochī de, nín tài kèqi le!","vi":"Nhiều món ngon thế này, chị khách sáo quá!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"都是我自己做的，你们多吃点儿。","py":"Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr.","vi":"Đều do chị tự nấu, các em ăn nhiều vào nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"奶茶也很好喝，是您自己做的吗？","py":"Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?","vi":"Trà sữa cũng ngon quá, là chị tự làm ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"不是，奶茶是爷爷买的。","py":"Bú shì, nǎichá shì yéye mǎi de.","vi":"Không, trà sữa là ông mua đấy."},{"speaker":"月","name":"Gia Nguyệt","zh":"在哪儿买的？我还没喝过这么好喝的奶茶。","py":"Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá.","vi":"Mua ở đâu thế ạ? Em chưa từng uống trà sữa nào ngon thế này."},{"speaker":"雪","name":"Nhất Tuyết","zh":"就在前边的商场，吃完饭你们可以跟我去看看。","py":"Jiù zài qiánbian de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","vi":"Ở ngay trung tâm thương mại phía trước, ăn xong các em đi cùng chị qua xem."}]},{"titleZh":"课文四 · 在宾馆","titleVi":"Ở khách sạn — nhắn tin cho Lý Văn","para":true,"speaker":"月","lines":[{"zh":"回国前一天，我们去一雪姐家了。","py":"Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le.","vi":"Một ngày trước khi về nước, bọn mình đến nhà chị Nhất Tuyết."},{"zh":"到她家的时候，饭菜都做好了。","py":"Dào tā jiā de shíhou, fàncài dōu zuòhǎo le.","vi":"Lúc đến nhà chị, cơm nước đã nấu xong cả rồi."},{"zh":"刘爷爷还准备了奶茶。","py":"Liú yéye hái zhǔnbèile nǎichá.","vi":"Ông Lưu còn chuẩn bị trà sữa."},{"zh":"因为吃了太多东西，我们吃完饭是走回酒店的。","py":"Yīnwèi chīle tài duō dōngxi, wǒmen chīwán fàn shì zǒuhuí jiǔdiàn de.","vi":"Vì ăn nhiều quá nên ăn xong bọn mình đi bộ về khách sạn."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Nhóm 4 · Đến nhà làm khách","q":{"zh":"四人一组：一人是主人，两人是家里人，一人是客人。客人来家里做客。","py":"Sì rén yì zǔ: yì rén shì zhǔrén, liǎng rén shì jiā li rén, yì rén shì kèrén. Kèrén lái jiā li zuòkè.","vi":"Nhóm 4 người: 1 chủ nhà, 2 người trong gia đình, 1 khách. Khách đến nhà chơi."},"items":[{"lines":[{"who":"A","zh":"天中，快进来！","py":"Tiānzhōng, kuài jìnlái!","vi":"Thiên Trung, mau vào đi!"},{"who":"B","zh":"谢谢，你家真漂亮啊！","py":"Xièxie, nǐ jiā zhēn piàoliang a!","vi":"Cảm ơn, nhà bạn đẹp quá!"}]},{"zh":"我给你介绍一下，这是我爷爷、奶奶。","py":"Wǒ gěi nǐ jièshào yíxià, zhè shì wǒ yéye, nǎinai.","vi":"Mình giới thiệu nhé, đây là ông bà nội mình."},{"zh":"这是送你们的礼物。—— 你太客气了！","py":"Zhè shì sòng nǐmen de lǐwù. —— Nǐ tài kèqi le!","vi":"Đây là quà tặng mọi người. — Bạn khách sáo quá!"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 1–5 · Chuyến du lịch","prep":3,"talk":2,"q":{"zh":"请你说说你的一次旅游。","py":"Qǐng nǐ shuōshuo nǐ de yí cì lǚyóu.","vi":"Hãy kể về một chuyến du lịch của bạn."},"frame":[{"lbl":"开头","zh":"我去过……，我想说说那次旅游。","py":"Wǒ qùguo ……, wǒ xiǎng shuōshuo nà cì lǚyóu.","vi":"Mình từng đến …, mình muốn kể về chuyến đi đó.","ex":{"zh":"我去过北京，我想说说那次旅游。","py":"Wǒ qùguo Běijīng, wǒ xiǎng shuōshuo nà cì lǚyóu.","vi":"Mình từng đến Bắc Kinh, mình muốn kể về chuyến đi đó."}},{"lbl":"中间","zh":"我是……和……一起去的，是坐……去的。","py":"Wǒ shì …… hé …… yìqǐ qù de, shì zuò …… qù de.","vi":"Mình đi vào … cùng …, đi bằng …","ex":{"zh":"我是去年八月和朋友一起去的，是坐飞机去的。","py":"Wǒ shì qùnián bā yuè hé péngyou yìqǐ qù de, shì zuò fēijī qù de.","vi":"Mình đi vào tháng 8 năm ngoái cùng bạn bè, đi bằng máy bay."}},{"lbl":"中间","zh":"我们在那儿玩了……天，去了……，还吃了……。","py":"Wǒmen zài nàr wánle …… tiān, qùle ……, hái chīle …….","vi":"Bọn mình chơi ở đó … ngày, đã đi …, còn ăn …","ex":{"zh":"我们在那儿玩了十多天，去了北京大学，还吃了北京烤鸭。","py":"Wǒmen zài nàr wánle shí duō tiān, qùle Běijīng Dàxué, hái chīle Běijīng Kǎoyā.","vi":"Bọn mình chơi ở đó hơn mười ngày, đi Đại học Bắc Kinh, còn ăn vịt quay Bắc Kinh."}},{"lbl":"中间","zh":"因为……，所以我觉得……。","py":"Yīnwèi ……, suǒyǐ wǒ juéde …….","vi":"Vì …, nên mình thấy …","ex":{"zh":"因为朋友给我们介绍了很多东西，所以我觉得这次旅游很不错。","py":"Yīnwèi péngyou gěi wǒmen jièshàole hěn duō dōngxi, suǒyǐ wǒ juéde zhè cì lǚyóu hěn búcuò.","vi":"Vì bạn giới thiệu cho bọn mình rất nhiều thứ, nên mình thấy chuyến đi này rất tuyệt."}},{"lbl":"结尾","zh":"有时间我还想再去看看。","py":"Yǒu shíjiān wǒ hái xiǎng zài qù kànkan.","vi":"Có thời gian mình còn muốn đến xem lần nữa.","ex":{"zh":"北京太大了，我还没玩完呢，有时间我还想再去看看。","py":"Běijīng tài dà le, wǒ hái méi wánwán ne, yǒu shíjiān wǒ hái xiǎng zài qù kànkan.","vi":"Bắc Kinh rộng quá, mình còn chưa chơi hết, có thời gian mình còn muốn đến xem lần nữa."}}]}]}},{"id":"k2v3-b06","courseId":"k2v3","order":6,"title":"Tiểu Tuyết, chúc mừng sinh nhật!","titleZh":"小雪，生日快乐！","titlePy":"Xiǎoxuě, shēngrì kuàilè!","vocab":[{"stt":1,"hanzi":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","pos":"Danh từ","meaning":"sinh nhật","comps":"过生日 (đón sinh nhật), 生日蛋糕 (bánh sinh nhật)","example":{"zh":"明天是我的生日。","py":"Míngtiān shì wǒ de shēngrì.","vi":"Ngày mai là sinh nhật mình."}},{"stt":2,"hanzi":"忘","pinyin":"wàng","hanviet":"Vong","pos":"Động từ","meaning":"quên","comps":"忘了 (quên mất rồi), 别忘了 (đừng quên)","example":{"zh":"你不说，我还真忘了。","py":"Nǐ bù shuō, wǒ hái zhēn wàng le.","vi":"Bạn không nói thì mình quên mất thật."}},{"stt":3,"hanzi":"画","pinyin":"huà","hanviet":"Hoạ","pos":"Động từ / Danh từ","meaning":"vẽ; bức tranh","comps":"画画 (vẽ tranh), 画一只猫 (vẽ một con mèo)","example":{"zh":"她很喜欢画画。","py":"Tā hěn xǐhuan huà huà.","vi":"Cô bé rất thích vẽ tranh."}},{"stt":4,"hanzi":"画笔","pinyin":"huàbǐ","hanviet":"Hoạ bút","pos":"Danh từ","meaning":"bút vẽ, bút màu","comps":"买画笔 (mua bút vẽ), 送画笔 (tặng bút vẽ)","example":{"zh":"我们就送她画笔吧。","py":"Wǒmen jiù sòng tā huàbǐ ba.","vi":"Mình tặng con bé bút vẽ nhé."}},{"stt":5,"hanzi":"蛋糕","pinyin":"dàngāo","hanviet":"Đản cao","pos":"Danh từ","meaning":"bánh ngọt, bánh kem","comps":"生日蛋糕 (bánh sinh nhật), 吃蛋糕 (ăn bánh)","example":{"zh":"我给她买了个生日蛋糕。","py":"Wǒ gěi tā mǎile ge shēngrì dàngāo.","vi":"Mình mua cho cô ấy một chiếc bánh sinh nhật."}},{"stt":6,"hanzi":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","pos":"Tính từ","meaning":"vui vẻ, hạnh phúc","comps":"生日快乐 (chúc mừng sinh nhật), 新年快乐 (chúc mừng năm mới)","example":{"zh":"今天我很快乐。","py":"Jīntiān wǒ hěn kuàilè.","vi":"Hôm nay mình rất vui."}},{"stt":7,"hanzi":"打开","pinyin":"dǎkāi","hanviet":"Đả khai","pos":"Động từ","meaning":"mở ra","comps":"打开门 (mở cửa), 打开看看 (mở ra xem)","example":{"zh":"你打开看看吧。","py":"Nǐ dǎkāi kànkan ba.","vi":"Bạn mở ra xem đi."}},{"stt":8,"hanzi":"长","pinyin":"cháng","hanviet":"Trường","pos":"Tính từ","meaning":"dài","comps":"很长 (rất dài), 长长的 (dài dài)","example":{"zh":"这条裤子太长了。","py":"Zhè tiáo kùzi tài cháng le.","vi":"Cái quần này dài quá."}},{"stt":9,"hanzi":"鱼","pinyin":"yú","hanviet":"Ngư","pos":"Danh từ","meaning":"cá","comps":"吃鱼 (ăn cá), 一条鱼 (một con cá)","example":{"zh":"我很喜欢吃鱼。","py":"Wǒ hěn xǐhuan chī yú.","vi":"Mình rất thích ăn cá."}},{"stt":10,"hanzi":"肉","pinyin":"ròu","hanviet":"Nhục","pos":"Danh từ","meaning":"thịt","comps":"吃肉 (ăn thịt), 鱼和肉 (cá và thịt)","example":{"zh":"他不喜欢吃肉。","py":"Tā bù xǐhuan chī ròu.","vi":"Anh ấy không thích ăn thịt."}},{"stt":11,"hanzi":"过","pinyin":"guò","hanviet":"Quá","pos":"Động từ","meaning":"trải qua; đón, mừng (sinh nhật, Tết)","comps":"过生日 (đón sinh nhật), 过年 (ăn Tết)","example":{"zh":"今天我们给小雪过生日。","py":"Jīntiān wǒmen gěi Xiǎoxuě guò shēngrì.","vi":"Hôm nay cả nhà tổ chức sinh nhật cho Tiểu Tuyết."}},{"stt":12,"hanzi":"地","pinyin":"de","hanviet":"Địa","pos":"Trợ từ","meaning":"trợ từ kết cấu (đứng trước động từ)","comps":"高兴地 (một cách vui vẻ), 早早地 (từ sớm)","example":{"zh":"他高高兴兴地回家了。","py":"Tā gāogāoxìngxìng de huí jiā le.","vi":"Cậu ấy vui vẻ về nhà."}},{"stt":13,"hanzi":"床","pinyin":"chuáng","hanviet":"Sàng","pos":"Danh từ","meaning":"giường","comps":"上床 (lên giường), 起床 (thức dậy)","example":{"zh":"孩子们早早地上床了。","py":"Háizimen zǎozǎo de shàng chuáng le.","vi":"Bọn trẻ lên giường từ sớm."}},{"stt":14,"hanzi":"舒服","pinyin":"shūfu","hanviet":"Thư phục","pos":"Tính từ","meaning":"dễ chịu, thoải mái","comps":"很舒服 (rất dễ chịu), 不舒服 (khó chịu, mệt)","example":{"zh":"我今天有点儿不舒服。","py":"Wǒ jīntiān yǒudiǎnr bù shūfu.","vi":"Hôm nay mình hơi mệt trong người."}}],"hanzi":[{"char":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","chars":["生","日"],"story":"生 vẽ mầm cây nhú lên khỏi mặt đất → \"sinh ra\". 日 vẽ mặt trời → \"ngày\". 生日 = ngày mình được sinh ra — sinh nhật."},{"char":"忘","pinyin":"wàng","hanviet":"Vong","chars":["忘"],"story":"忘 = 亡 (mất) ở trên + 心 (lòng) ở dưới; 亡 wáng còn chỉ âm. Điều đã mất khỏi lòng → \"quên\"."},{"char":"画","pinyin":"huà","hanviet":"Hoạ","chars":["画"],"story":"画 xưa vẽ bàn tay cầm bút vạch ranh giới quanh thửa ruộng 田 → \"vạch, vẽ\". Nay: nét ngang trên + 田 trong khung 凵. Vừa là động từ \"vẽ\", vừa là danh từ \"bức tranh\": 画画 = vẽ tranh."},{"char":"画笔","pinyin":"huàbǐ","hanviet":"Hoạ bút","chars":["画","笔"],"story":"画 = vẽ. 笔 = bộ Trúc ⺮ (tre) + 毛 (lông): bút lông cán tre. 画笔 = bút dùng để vẽ — bút vẽ, bút màu."},{"char":"蛋糕","pinyin":"dàngāo","hanviet":"Đản cao","chars":["蛋","糕"],"story":"蛋 = 疋 + 虫 (loài bò sát, chim…) → \"trứng\". 糕 = bộ Mễ 米 (gạo) chỉ nghĩa + 羔 gāo chỉ âm → bánh làm từ bột. 蛋糕 = bánh làm từ trứng và bột → bánh ngọt, bánh kem."},{"char":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","chars":["快","乐"],"story":"快 = 忄 (lòng) + 夬 → lòng sảng khoái (đã học ở bài 5). 乐 (樂) xưa vẽ đàn dây đặt trên giá gỗ → \"âm nhạc\" (yuè), nghe nhạc thì vui → \"vui\" (lè). 快乐 = vui vẻ."},{"char":"打开","pinyin":"dǎkāi","hanviet":"Đả khai","chars":["打","开"],"story":"打 = bộ Thủ 扌 (tay) chỉ nghĩa + 丁 dīng chỉ âm → làm động tác bằng tay. 开 (開) vẽ hai tay đẩy then cài cửa → \"mở\". 打开 = mở ra."},{"char":"长","pinyin":"cháng","hanviet":"Trường","chars":["长"],"story":"长 (長) vẽ người già tóc dài chống gậy → \"dài\". Chữ đa âm: cháng = dài (长长的面条儿) · zhǎng = lớn lên."},{"char":"鱼","pinyin":"yú","hanviet":"Ngư","chars":["鱼"],"story":"鱼 là chữ tượng hình con cá: phía trên là đầu, 田 ở giữa là thân có vảy, nét ngang dưới cùng là đuôi."},{"char":"肉","pinyin":"ròu","hanviet":"Nhục","chars":["肉"],"story":"肉 là chữ tượng hình miếng thịt có thớ thịt bên trong. Khi làm bộ thủ, 肉 viết thành ⺼ (nhục nguyệt), gặp trong các chữ chỉ bộ phận cơ thể."},{"char":"过","pinyin":"guò","hanviet":"Quá","chars":["过"],"story":"过 (過) = bộ Sước 辶 (bước đi) + 寸 → \"đi qua\". Đi qua một quãng thời gian → \"trải qua\": 过生日 = đón sinh nhật. Khác trợ từ guo (bài 4: 去过)."},{"char":"地","pinyin":"de","hanviet":"Địa","chars":["地"],"story":"地 = bộ Thổ 土 (đất) + 也 → nghĩa gốc \"đất\" (dì). Ở bài này mượn làm trợ từ, đọc nhẹ de, đứng trước động từ: 高高兴兴地玩."},{"char":"床","pinyin":"chuáng","hanviet":"Sàng","chars":["床"],"story":"床 = 广 (mái nhà) + 木 (gỗ): đồ làm bằng gỗ kê trong nhà để nằm → \"giường\"."},{"char":"舒服","pinyin":"shūfu","hanviet":"Thư phục","chars":["舒","服"],"story":"舒 = 舍 (nhà) + 予 → duỗi ra, thư thái. 服 = áo quần (衣服), mặc vừa người. 舒服 = thân thể thư thái, dễ chịu. Từ này đọc nhẹ âm sau: shūfu."}],"grammar":[{"title":"Lặp lại tính từ (形容词重叠)","formula":"<div class=\"fx-lbl\">Đơn âm tiết</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>A</b><small>大 · 小 · 长</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>AA</b><small>大大</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>的</b></span></div><div class=\"fx-ex zh\">大大的生日蛋糕</div><div class=\"fx-lbl\">Song âm tiết</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>AB</b><small>漂亮 · 高兴</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>AABB</b><small>漂漂亮亮</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>的</b></span></div><div class=\"fx-ex zh\">每天都漂漂亮亮的</div>","summary":"<p class=\"gr-lead\">AA · AABB</p><ul><li>Lặp tính từ để nói <b>mức độ cao</b> hoặc tỏ ý <b>yêu thích</b>: <span class=\"zh\">大大的蛋糕</span> = cái bánh to ơi là to.</li><li>Sau dạng lặp thường có <span class=\"zh\">的</span>: <span class=\"zh\">小小的</span> · <span class=\"zh\">漂漂亮亮的</span>.</li></ul>","note":"<b>Lưu ý:</b> Dạng lặp đã là mức độ cao — <b>không</b> thêm <span class=\"zh\">很</span>: ✗ <span class=\"zh\">很大大的</span>.","examples":[{"zh":"我再给她买个大大的生日蛋糕。","py":"Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","vi":"Anh mua thêm cho con một chiếc bánh sinh nhật thật to."},{"zh":"这只猫小小的，真让人喜欢。","py":"Zhè zhī māo xiǎoxiǎo de, zhēn ràng rén xǐhuan.","vi":"Con mèo này nhỏ xíu, thật đáng yêu."},{"zh":"一雪的女儿每天都漂漂亮亮的。","py":"Yīxuě de nǚ'ér měi tiān dōu piàopiàoliàngliàng de.","vi":"Con gái chị Nhất Tuyết ngày nào cũng xinh xắn."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这家饭店的饺子____，我一次能吃二十个。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">吃吧，我知道你爱吃饺子。</span></span></span><span class=\"qz-hint\">Sủi cảo quán này nhỏ xíu, mình ăn một lần được hai mươi cái. — Ăn đi, mình biết bạn mê sủi cảo mà.</span>","answer":["小小的"],"explain":"这家饭店的饺子小小的，我一次能吃二十个。 (Zhè jiā fàndiàn de jiǎozi xiǎoxiǎo de, wǒ yí cì néng chī èrshí ge.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这几天你在家____休息，别出去了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，我也觉得太累了。</span></span></span><span class=\"qz-hint\">Mấy hôm nay con ở nhà nghỉ ngơi cho tốt, đừng ra ngoài nữa. — Vâng, con cũng thấy mệt quá rồi.</span>","answer":["好好","好好地"],"explain":"这几天你在家好好休息，别出去了。 (Zhè jǐ tiān nǐ zài jiā hǎohǎo xiūxi, bié chūqù le.)"}]},{"title":"Cụm cố định 什么的","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>A、B (、C)</b><small>các thứ liệt kê</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么的</b><small>các thứ, vân vân</small></span></div>","summary":"<p class=\"gr-lead\">… các thứ</p><ul><li><span class=\"zh\">什么的</span> đặt <b>cuối</b> chuỗi liệt kê = \"… các thứ, vân vân\" — còn nữa chưa kể hết.</li><li>Khẩu ngữ hay chêm <span class=\"zh\">啊</span> giữa các thứ: <span class=\"zh\">鱼啊肉啊什么的</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">桌子上有电脑、杯子、书和画笔什么的。</span>　·　<span class=\"zh\">鱼啊肉啊什么的</span></p>","note":"<b>Lưu ý:</b> Phải có <span class=\"zh\">的</span>: <span class=\"zh\">鱼啊肉啊什么的</span> — ✗ <span class=\"zh\">鱼啊肉啊什么</span> (thành câu hỏi \"cá thịt gì\").","examples":[{"zh":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","py":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","vi":"Vẽ nhà mình! Có bố, mẹ, em trai, còn có chó đen, mèo trắng các thứ."},{"zh":"桌子上有电脑、杯子、书和画笔什么的。","py":"Zhuōzi shang yǒu diànnǎo, bēizi, shū hé huàbǐ shénmede.","vi":"Trên bàn có máy tính, cốc, sách, bút vẽ các thứ."},{"zh":"她拿来了一些水、面包和苹果什么的。","py":"Tā náláile yìxiē shuǐ, miànbāo hé píngguǒ shénmede.","vi":"Cô ấy mang đến ít nước, bánh mì, táo các thứ."}],"exercises":[]},{"title":"Trợ từ kết cấu 地","formula":"<div class=\"fx-lbl\">AA</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>AA</b><small>早早</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>地</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span></div><div class=\"fx-ex zh\">老师早早地到了教室。</div><div class=\"fx-lbl\">AABB</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>AABB</b><small>高高兴兴</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>地</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span></div><div class=\"fx-ex zh\">高高兴兴地玩</div>","summary":"<p class=\"gr-lead\">Làm một cách…</p><ul><li><span class=\"zh\">地</span> (đọc nhẹ de) nối <b>tính từ</b> với <b>động từ</b> phía sau — \"làm một cách…\".</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> Còn gặp: <span class=\"zh\">很 + 形容词 + 地</span>　<span class=\"zh\">爸爸很快地吃完早饭。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">的</span> + danh từ: <span class=\"zh\">大大的蛋糕</span> · <span class=\"zh\">地</span> + động từ: <span class=\"zh\">高高兴兴地玩</span> — ✗ <span class=\"zh\">高高兴兴的玩</span>.","examples":[{"zh":"过生日就要吃好吃的，还要高高兴兴地玩。","py":"Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","vi":"Sinh nhật là phải ăn ngon, còn phải vui vẻ đi chơi nữa."},{"zh":"老师早早地到了教室。","py":"Lǎoshī zǎozǎo de dàole jiàoshì.","vi":"Cô giáo đến lớp từ sớm."},{"zh":"爸爸很快地吃完早饭，就去上班了。","py":"Bàba hěn kuài de chīwán zǎofàn, jiù qù shàngbān le.","vi":"Bố ăn sáng thật nhanh rồi đi làm."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你姐姐去哪儿了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">她生病了，____回房间休息了。</span></span></span><span class=\"qz-hint\">Chị bạn đi đâu rồi? — Chị ấy bị ốm, về phòng nghỉ từ sớm rồi.</span>","answer":["早早地","早早"],"explain":"她生病了，早早地回房间休息了。 (Tā shēngbìng le, zǎozǎo de huí fángjiān xiūxi le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你回家____睡一觉，明天也别来上班了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，您也别太累了。</span></span></span><span class=\"qz-hint\">Cậu về nhà ngủ một giấc cho đẫy, mai cũng đừng đi làm. — Vâng, anh cũng đừng làm mệt quá nhé.</span>","answer":["好好地","好好"],"explain":"你回家好好地睡一觉，明天也别来上班了。 (Nǐ huí jiā hǎohǎo de shuì yí jiào, míngtiān yě bié lái shàngbān le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小明喜欢你送的礼物吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">喜欢，他拿到礼物____说：\"这个礼物太好了！\"</span></span></span><span class=\"qz-hint\">Tiểu Minh có thích quà bạn tặng không? — Thích lắm, cầm quà cậu bé vui vẻ nói: \"Quà này tuyệt quá!\"</span>","answer":["高高兴兴地","高高兴兴","很高兴地","高兴地"],"explain":"喜欢，他拿到礼物高高兴兴地说：\"这个礼物太好了！\" (Xǐhuan, tā nádào lǐwù gāogāoxìngxìng de shuō: \"Zhège lǐwù tài hǎo le!\")"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — bàn chuyện quà sinh nhật","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"明天就是女儿的生日了。","py":"Míngtiān jiù shì nǚ'ér de shēngrì le.","vi":"Mai là sinh nhật con gái rồi đấy."},{"speaker":"明","name":"Lưu Minh","zh":"你不说，我还真忘了。我们给她准备个什么礼物呢？","py":"Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi ge shénme lǐwù ne?","vi":"Em không nói thì anh quên mất thật. Mình chuẩn bị quà gì cho con đây?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"她喜欢画画，你觉得画笔怎么样？","py":"Tā xǐhuan huà huà, nǐ juéde huàbǐ zěnmeyàng?","vi":"Con thích vẽ tranh, anh thấy bút vẽ thế nào?"},{"speaker":"明","name":"Lưu Minh","zh":"就送画笔吧！","py":"Jiù sòng huàbǐ ba!","vi":"Thế thì tặng bút vẽ đi!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"那我明天上午就去买。","py":"Nà wǒ míngtiān shàngwǔ jiù qù mǎi.","vi":"Vậy sáng mai em đi mua luôn."},{"speaker":"明","name":"Lưu Minh","zh":"好的！我再给她买个大大的生日蛋糕。","py":"Hǎo de! Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","vi":"Được! Anh mua thêm cho con một chiếc bánh sinh nhật thật to."}]},{"titleZh":"课文二 · 在客厅","titleVi":"Phòng khách — tặng quà Tiểu Tuyết","lines":[{"speaker":"明","name":"Lưu Minh","zh":"小雪，生日快乐！","py":"Xiǎoxuě, shēngrì kuàilè!","vi":"Tiểu Tuyết, chúc mừng sinh nhật con!"},{"speaker":"弟","name":"Tiểu Minh","zh":"姐姐，生日快乐！","py":"Jiějie, shēngrì kuàilè!","vi":"Chị ơi, chúc mừng sinh nhật!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"小雪，这是爸爸、妈妈送你的礼物。","py":"Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù.","vi":"Tiểu Tuyết, đây là quà bố mẹ tặng con."},{"speaker":"明","name":"Lưu Minh","zh":"你打开看看喜欢不喜欢。","py":"Nǐ dǎkāi kànkan xǐhuan bu xǐhuan.","vi":"Con mở ra xem có thích không."},{"speaker":"小","name":"Tiểu Tuyết","zh":"画笔！我很喜欢！","py":"Huàbǐ! Wǒ hěn xǐhuan!","vi":"Bút vẽ! Con thích lắm!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"那你想画点儿什么？","py":"Nà nǐ xiǎng huà diǎnr shénme?","vi":"Vậy con muốn vẽ gì nào?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","py":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","vi":"Vẽ nhà mình! Có bố, mẹ, em trai, còn có chó đen, mèo trắng các thứ."},{"speaker":"弟","name":"Tiểu Minh","zh":"那我要画一个穿白色衣服的姐姐。","py":"Nà wǒ yào huà yí ge chuān báisè yīfu de jiějie.","vi":"Thế em sẽ vẽ một chị gái mặc áo trắng."}]},{"titleZh":"课文三 · 在客厅","titleVi":"Phòng khách — mừng sinh nhật","lines":[{"speaker":"明","name":"Lưu Minh","zh":"小雪，看看今天有什么好吃的。","py":"Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de.","vi":"Tiểu Tuyết, xem hôm nay có món gì ngon nào."},{"speaker":"小","name":"Tiểu Tuyết","zh":"长长的面条儿，大大的蛋糕。","py":"Chángcháng de miàntiáor, dàdà de dàngāo.","vi":"Mì sợi dài dài, bánh kem to to."},{"speaker":"明","name":"Lưu Minh","zh":"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","py":"Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de.","vi":"Con xem, còn có cá, thịt các thứ, đều là món con thích."},{"speaker":"小","name":"Tiểu Tuyết","zh":"谢谢爸爸、妈妈！","py":"Xièxie bàba, māma!","vi":"Con cảm ơn bố mẹ!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","py":"Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne.","vi":"Mau đi gọi em trai lại ăn cơm đi, ăn xong cả nhà còn đi chơi nữa."},{"speaker":"小","name":"Tiểu Tuyết","zh":"过生日真好啊！","py":"Guò shēngrì zhēn hǎo a!","vi":"Được đón sinh nhật thích thật đấy!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"是的，过生日就要吃好吃的，还要高高兴兴地玩。","py":"Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","vi":"Đúng vậy, sinh nhật là phải ăn ngon, còn phải vui vẻ đi chơi nữa."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký của Nhất Tuyết","para":true,"speaker":"雪","lines":[{"zh":"今天是女儿的生日。","py":"Jīntiān shì nǚ'ér de shēngrì.","vi":"Hôm nay là sinh nhật con gái."},{"zh":"我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。","py":"Wǒmen mǎile dàngāo, zuòle miàntiáor, hái zuòle yú a ròu a shénmede.","vi":"Chúng tôi mua bánh kem, nấu mì, còn làm cá, thịt các món."},{"zh":"吃完晚饭，一家人去看了个电影。","py":"Chīwán wǎnfàn, yì jiā rén qù kànle ge diànyǐng.","vi":"Ăn tối xong, cả nhà đi xem một bộ phim."},{"zh":"回家后，孩子们早早地就上床了。","py":"Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le.","vi":"Về đến nhà, bọn trẻ lên giường từ sớm."},{"zh":"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。","py":"Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng.","vi":"Mai không phải đi học, chúng nói muốn ngủ một giấc thật đã, bảo chúng tôi gọi dậy muộn một chút."},{"zh":"这是很忙、很累，但很快乐的一天。","py":"Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān.","vi":"Đây là một ngày rất bận, rất mệt nhưng rất vui."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Nhóm 3 · Mừng sinh nhật","q":{"zh":"三人一组：一人过生日，两人是朋友。送礼物，问问他想吃什么、想去哪儿玩。","py":"Sān rén yì zǔ: yì rén guò shēngrì, liǎng rén shì péngyou. Sòng lǐwù, wènwen tā xiǎng chī shénme, xiǎng qù nǎr wán.","vi":"Nhóm 3: 1 người có sinh nhật, 2 người là bạn. Tặng quà, hỏi bạn ấy muốn ăn gì, muốn đi đâu chơi."},"items":[{"lines":[{"who":"A","zh":"明明，今天是你的生日！","py":"Míngming, jīntiān shì nǐ de shēngrì!","vi":"Minh Minh, hôm nay là sinh nhật cậu!"},{"who":"B","zh":"生日快乐！","py":"Shēngrì kuàilè!","vi":"Chúc mừng sinh nhật!"}]},{"zh":"这是我们送你的礼物，你打开看看吧！","py":"Zhè shì wǒmen sòng nǐ de lǐwù, nǐ dǎkāi kànkan ba!","vi":"Đây là quà bọn mình tặng, cậu mở ra xem đi!"},{"zh":"你想吃什么？—— 蛋糕啊面条儿啊什么的，我都想吃！","py":"Nǐ xiǎng chī shénme? —— Dàngāo a miàntiáor a shénmede, wǒ dōu xiǎng chī!","vi":"Cậu muốn ăn gì? — Bánh kem, mì các thứ, mình đều muốn ăn!"}]}],"speak":[]},"review":{"range":"4–6","rows":[{"l":4,"zh":"动态助词 \"过\"","vi":"Trợ từ động thái 过","ex":{"zh":"我去过北京。","py":"Wǒ qùguo Běijīng.","vi":"Mình từng đến Bắc Kinh."}},{"l":4,"zh":"因果复句 \"因为……，所以……\"","vi":"Câu phức nhân quả 因为……所以……","ex":{"zh":"因为我生病了，所以没去上班。","py":"Yīnwèi wǒ shēngbìng le, suǒyǐ méi qù shàngbān.","vi":"Vì mình bị ốm nên không đi làm."}},{"l":4,"zh":"\"的\" 字短语","vi":"Cụm chữ 的","ex":{"zh":"红色的好看。","py":"Hóngsè de hǎokàn.","vi":"Cái màu đỏ đẹp."}},{"l":5,"zh":"简单趋向补语 (1)","vi":"Bổ ngữ xu hướng đơn (1)","ex":{"zh":"你过来吧。","py":"Nǐ guòlái ba.","vi":"Bạn qua đây đi."}},{"l":5,"zh":"简单趋向补语 (2)","vi":"Bổ ngữ xu hướng đơn (2)","ex":{"zh":"王老师进教室去了。","py":"Wáng lǎoshī jìn jiàoshì qù le.","vi":"Cô Vương vào lớp rồi."}},{"l":5,"zh":"固定格式 \"都……了\"","vi":"Cấu trúc 都……了","ex":{"zh":"都12点了，你快睡觉吧。","py":"Dōu shí'èr diǎn le, nǐ kuài shuìjiào ba.","vi":"12 giờ rồi đấy, con mau đi ngủ đi."}},{"l":6,"zh":"形容词重叠","vi":"Lặp lại tính từ","ex":{"zh":"他每天都高高兴兴的。","py":"Tā měi tiān dōu gāogāoxìngxìng de.","vi":"Ngày nào cậu ấy cũng vui vẻ."}},{"l":6,"zh":"固定短语 \"什么的\"","vi":"Cụm cố định 什么的","ex":{"zh":"妈妈做了鱼啊肉啊什么的。","py":"Māma zuòle yú a ròu a shénmede.","vi":"Mẹ nấu cá, thịt các thứ."}},{"l":6,"zh":"结构助词 \"地\"","vi":"Trợ từ kết cấu 地","ex":{"zh":"他早早地到了教室。","py":"Tā zǎozǎo de dàole jiàoshì.","vi":"Cậu ấy đến lớp từ sớm."}}]}},{"id":"k2v3-b07","courseId":"k2v3","order":7,"title":"Anh ấy chơi bóng rổ rất giỏi","titleZh":"他篮球打得很好","titlePy":"tā lánqiú dǎ de hěn hǎo","vocab":[{"stt":1,"hanzi":"从","pinyin":"cóng","hanviet":"Tòng","pos":"Giới từ","meaning":"từ (nơi chốn, thời gian)","comps":"从北京来 (đến từ Bắc Kinh), 从……开始 (bắt đầu từ…)","example":{"zh":"我从学校回来。","py":"Wǒ cóng xuéxiào huílái.","vi":"Mình từ trường về."}},{"stt":2,"hanzi":"往","pinyin":"wǎng","hanviet":"Vãng","pos":"Giới từ / Động từ","meaning":"về phía, hướng về; đi","comps":"往外跑 (chạy ra ngoài), 往前走 (đi về phía trước)","example":{"zh":"你往前走，就到了。","py":"Nǐ wǎng qián zǒu, jiù dào le.","vi":"Bạn đi thẳng về phía trước là đến."}},{"stt":3,"hanzi":"跑","pinyin":"pǎo","hanviet":"Bào","pos":"Động từ","meaning":"chạy","comps":"往外跑 (chạy ra ngoài), 跑得快 (chạy nhanh)","example":{"zh":"他跑得很快。","py":"Tā pǎo de hěn kuài.","vi":"Cậu ấy chạy rất nhanh."}},{"stt":4,"hanzi":"打","pinyin":"dǎ","hanviet":"Đả","pos":"Động từ","meaning":"chơi (bóng); đánh","comps":"打篮球 (chơi bóng rổ), 打电话 (gọi điện thoại)","example":{"zh":"我们一起去打篮球吧。","py":"Wǒmen yìqǐ qù dǎ lánqiú ba.","vi":"Mình cùng đi chơi bóng rổ nhé."}},{"stt":5,"hanzi":"篮球","pinyin":"lánqiú","hanviet":"Lam cầu","pos":"Danh từ","meaning":"bóng rổ","comps":"打篮球 (chơi bóng rổ), 一个篮球 (một quả bóng rổ)","example":{"zh":"他很喜欢打篮球。","py":"Tā hěn xǐhuan dǎ lánqiú.","vi":"Cậu ấy rất thích chơi bóng rổ."}},{"stt":6,"hanzi":"运动","pinyin":"yùndòng","hanviet":"Vận động","pos":"Danh từ / Động từ","meaning":"thể thao; vận động, tập thể thao","comps":"喜欢运动 (thích thể thao), 去运动 (đi tập thể thao)","example":{"zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?"}},{"stt":7,"hanzi":"踢","pinyin":"tī","hanviet":"Thích","pos":"Động từ","meaning":"đá","comps":"踢足球 (đá bóng), 踢球 (đá bóng)","example":{"zh":"星期天我们去踢球吧。","py":"Xīngqītiān wǒmen qù tī qiú ba.","vi":"Chủ nhật mình đi đá bóng nhé."}},{"stt":8,"hanzi":"足球","pinyin":"zúqiú","hanviet":"Túc cầu","pos":"Danh từ","meaning":"bóng đá","comps":"踢足球 (đá bóng), 看足球 (xem bóng đá)","example":{"zh":"我哥哥很喜欢踢足球。","py":"Wǒ gēge hěn xǐhuan tī zúqiú.","vi":"Anh trai mình rất thích đá bóng."}},{"stt":9,"hanzi":"球","pinyin":"qiú","hanviet":"Cầu","pos":"Danh từ","meaning":"quả bóng; bóng","comps":"打球 (chơi bóng), 踢球 (đá bóng)","example":{"zh":"这个球是谁的？","py":"Zhège qiú shì shéi de?","vi":"Quả bóng này của ai?"}},{"stt":10,"hanzi":"得","pinyin":"de","hanviet":"Đắc","pos":"Trợ từ","meaning":"trợ từ (nối động từ với bổ ngữ)","comps":"跑得快 (chạy nhanh), 玩得很高兴 (chơi rất vui)","example":{"zh":"他们玩得很高兴。","py":"Tāmen wán de hěn gāoxìng.","vi":"Họ chơi rất vui."}},{"stt":11,"hanzi":"跑步","pinyin":"pǎobù","hanviet":"Bào bộ","pos":"Động từ","meaning":"chạy bộ","comps":"去跑步 (đi chạy bộ), 每天跑步 (chạy bộ mỗi ngày)","example":{"zh":"我每天早上都去跑步。","py":"Wǒ měi tiān zǎoshang dōu qù pǎobù.","vi":"Sáng nào mình cũng đi chạy bộ."}},{"stt":12,"hanzi":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","pos":"Động từ","meaning":"bơi, bơi lội","comps":"去游泳 (đi bơi), 喜欢游泳 (thích bơi)","example":{"zh":"你喜欢游泳吗？","py":"Nǐ xǐhuan yóuyǒng ma?","vi":"Bạn có thích bơi không?"}},{"stt":13,"hanzi":"游","pinyin":"yóu","hanviet":"Du","pos":"Động từ","meaning":"bơi","comps":"游得快 (bơi nhanh), 游一会儿 (bơi một lát)","example":{"zh":"她游得不快。","py":"Tā yóu de bú kuài.","vi":"Cô ấy bơi không nhanh."}},{"stt":14,"hanzi":"爱好","pinyin":"àihào","hanviet":"Ái hảo","pos":"Danh từ / Động từ","meaning":"sở thích; yêu thích","comps":"我的爱好 (sở thích của tôi), 有什么爱好 (có sở thích gì)","example":{"zh":"我的爱好是画画。","py":"Wǒ de àihào shì huà huà.","vi":"Sở thích của mình là vẽ tranh."}},{"stt":15,"hanzi":"开始","pinyin":"kāishǐ","hanviet":"Khai thuỷ","pos":"Động từ / Danh từ","meaning":"bắt đầu; sự bắt đầu","comps":"开始上课 (bắt đầu vào học), 从……开始 (bắt đầu từ…)","example":{"zh":"我们九点开始上课。","py":"Wǒmen jiǔ diǎn kāishǐ shàngkè.","vi":"Chúng mình bắt đầu học lúc 9 giờ."}}],"hanzi":[{"char":"从","pinyin":"cóng","hanviet":"Tòng","chars":["从"],"story":"从 vẽ hai người 人 đi nối nhau, người sau theo người trước → \"theo\" (Hán Việt: tòng). Nay dùng làm giới từ \"từ\": 从北京来, 从……开始."},{"char":"往","pinyin":"wǎng","hanviet":"Vãng","chars":["往"],"story":"往 = bộ Xích 彳 (bước chân) chỉ nghĩa + phần bên phải vốn là chữ chỉ âm wǎng. Bước đi tới đâu → \"đi, về phía\": 往外跑, 往前走."},{"char":"跑","pinyin":"pǎo","hanviet":"Bào","chars":["跑"],"story":"跑 là chữ hình thanh: bộ Túc ⻊ (bàn chân) chỉ nghĩa, 包 bāo chỉ âm. Dùng chân thật nhanh → \"chạy\"."},{"char":"打","pinyin":"dǎ","hanviet":"Đả","chars":["打"],"story":"打 = bộ Thủ 扌 (tay) + 丁 dīng chỉ âm → làm động tác bằng tay: đánh. Các môn chơi bằng tay dùng 打: 打篮球; còn 打电话 = gọi điện."},{"char":"篮球","pinyin":"lánqiú","hanviet":"Lam cầu","chars":["篮","球"],"story":"篮 = bộ Trúc ⺮ (tre) + 监 jiān chỉ âm → cái giỏ đan bằng tre. 球 = 王 (ngọc) + 求 qiú chỉ âm → viên ngọc tròn → quả bóng. 篮球 = ném bóng vào giỏ — bóng rổ."},{"char":"运动","pinyin":"yùndòng","hanviet":"Vận động","chars":["运","动"],"story":"运 = bộ Sước 辶 (bước đi) + 云 yún chỉ âm → chuyển đi, vận chuyển. 动 = 云 + 力 (sức lực) → dùng sức thì chuyển động. 运动 = vận động, chơi thể thao."},{"char":"踢","pinyin":"tī","hanviet":"Thích","chars":["踢"],"story":"踢 là chữ hình thanh: bộ Túc ⻊ (bàn chân) chỉ nghĩa, 易 yì chỉ âm. Động tác bằng chân → \"đá\": 踢足球."},{"char":"足球","pinyin":"zúqiú","hanviet":"Túc cầu","chars":["足","球"],"story":"足 vẽ cẳng chân (口 phía trên là đầu gối) và bàn chân 止 → \"chân\". 球 = quả bóng. 足球 = môn bóng chơi bằng chân — bóng đá."},{"char":"球","pinyin":"qiú","hanviet":"Cầu","chars":["球"],"story":"球 = bộ Ngọc 王 (玉) chỉ nghĩa + 求 qiú chỉ âm → viên ngọc tròn, rồi chỉ mọi vật hình cầu → quả bóng: 打球, 踢球."},{"char":"得","pinyin":"de","hanviet":"Đắc","chars":["得"],"story":"得 = 彳 (bước đi) + 旦 + 寸 (bàn tay): ra đường nhặt được vật quý cầm trong tay → \"được\" (dé). Làm trợ từ đọc nhẹ de, nối động từ với bổ ngữ: 跑得快. Ba chữ cùng đọc de: 的 (+ danh từ) · 地 (+ động từ) · 得 (sau động từ)."},{"char":"跑步","pinyin":"pǎobù","hanviet":"Bào bộ","chars":["跑","步"],"story":"跑 = chạy (⻊ + 包). 步 vẽ hai bàn chân 止 nối nhau → \"bước chân\". 跑步 = chạy từng bước → chạy bộ."},{"char":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","chars":["游","泳"],"story":"游 = 氵 (nước) + 斿 yóu chỉ âm → bơi. 泳 = 氵 + 永 yǒng chỉ âm (永 vẽ dòng nước chảy dài). Hai chữ đều có bộ nước → bơi lội."},{"char":"游","pinyin":"yóu","hanviet":"Du","chars":["游"],"story":"游 = bộ Thuỷ 氵 (nước) chỉ nghĩa + 斿 yóu (lá cờ phấp phới) chỉ âm → bơi trong nước. Còn gặp trong 旅游 (du lịch, bài 1)."},{"char":"爱好","pinyin":"àihào","hanviet":"Ái hảo","chars":["爱","好"],"story":"爱 = 爫 (bàn tay) + 冖 (che) + 友 (bạn) → nâng niu, yêu thương. 好 = 女 + 子, ở đây đọc hào = thích. 爱好 = điều mình yêu thích — sở thích."},{"char":"开始","pinyin":"kāishǐ","hanviet":"Khai thuỷ","chars":["开","始"],"story":"开 = mở (bài 6: 打开). 始 = bộ Nữ 女 + 台 tái chỉ âm → lúc khởi đầu (Hán Việt: thuỷ, như 始终). 开始 = mở đầu → bắt đầu."}],"grammar":[{"title":"Câu phức rút gọn 一……就……","formula":"<div class=\"fx-lbl\">Cùng chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span></div><div class=\"fx-ex zh\">你怎么一下课就往外跑？</div><div class=\"fx-lbl\">Khác chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span></div><div class=\"fx-ex zh\">他一来，我就走。</div>","summary":"<p class=\"gr-lead\">Vừa… là…</p><ul><li>Việc sau xảy ra <b>ngay sau</b> việc trước: <span class=\"zh\">一下课就往外跑</span>; hoặc vế trước là <b>điều kiện</b>: <span class=\"zh\">一到星期六就去打篮球</span>.</li></ul>","note":"<b>Lưu ý:</b> <span class=\"zh\">就</span> đứng <b>sau chủ ngữ thứ hai</b>, trước động từ: <span class=\"zh\">妈妈就打来电话</span> — ✗ <span class=\"zh\">就妈妈打来电话</span>.","examples":[{"zh":"你怎么一下课就往外跑？","py":"Nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","vi":"Sao cậu vừa tan học đã chạy ra ngoài thế?"},{"zh":"我一到家，妈妈就打来电话了。","py":"Wǒ yí dào jiā, māma jiù dǎlái diànhuà le.","vi":"Mình vừa về đến nhà thì mẹ gọi điện tới."},{"zh":"一到星期六，陈天中就跟同学去打篮球。","py":"Yí dào Xīngqīliù, Chén Tiānzhōng jiù gēn tóngxué qù dǎ lánqiú.","vi":"Cứ đến thứ Bảy là Thiên Trung đi chơi bóng rổ với bạn."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你今天早点儿回来。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，我____就回来。</span></span></span><span class=\"qz-hint\">Hôm nay con về sớm một chút nhé. — Vâng, con tan học là về ngay.</span>","answer":["一下课","一下班","一放学"],"explain":"好的，我一下课就回来。 (Hǎo de, wǒ yí xiàkè jiù huílái.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我一下飞机，____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">因为我给她打电话了，让她去接你。</span></span></span><span class=\"qz-hint\">Mình vừa xuống máy bay là cô ấy đã đến đón rồi. — Vì mình gọi điện bảo cô ấy đi đón bạn đấy.</span>","answer":["她就来接我了","她就来接我","她就来机场接我了","她就来接我了啊"],"explain":"我一下飞机，她就来接我了。 (Wǒ yí xià fēijī, tā jiù lái jiē wǒ le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你看，小猫____就过来了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，因为它爱吃鱼。</span></span></span><span class=\"qz-hint\">Bạn xem, mèo con vừa thấy cá là chạy lại ngay. — Đúng thế, vì nó thích ăn cá mà.</span>","answer":["一看见鱼","一看到鱼"],"explain":"你看，小猫一看见鱼就过来了。 (Nǐ kàn, xiǎo māo yí kànjiàn yú jiù guòlái le.)"}]},{"title":"Bổ ngữ trạng thái (1): Động từ + 得 + tính từ","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b><small>trợ từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(很 / 不) 形容词</b><small>tính từ — làm thế nào</small></span></div>","summary":"<p class=\"gr-lead\">Động từ + 得 + Tính từ</p><ul><li>Bổ ngữ trạng thái đứng <b>sau động từ</b>, nhận xét động tác diễn ra <b>thế nào</b>: chạy nhanh, chơi vui, đá tạm được.</li><li>Trước tính từ thường có <span class=\"zh\">很、还、不、太</span>: <span class=\"zh\">踢得还可以</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">状态补语 (1)</span> · Ba dạng câu</h4><p>KĐ · PĐ · Câu hỏi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(很) 形容词</b></span></div><div class=\"fx-ex zh\">他们玩得很高兴。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b></span></div><div class=\"fx-ex zh\">白家月跑得不快。</div><div class=\"fx-lbl\">Câu hỏi</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 + 不 + 形容词</b></span></div><div class=\"fx-ex zh\">他来得早不早？</div></div><p class=\"gr-key\">Hỏi còn có: <span class=\"zh\">……吗？</span> · <span class=\"zh\">动词 + 得 + 怎么样？</span>　<span class=\"zh\">他们玩得怎么样？</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他们玩得很高兴。</span>　·　<span class=\"zh\">白家月跑得不快。</span></p>","note":"<b>Lưu ý:</b> Phủ định đặt <span class=\"zh\">不</span> <b>sau</b> <span class=\"zh\">得</span>: <span class=\"zh\">跑得不快</span> — ✗ <span class=\"zh\">不跑得快</span>.","examples":[{"zh":"我踢得还可以。","py":"Wǒ tī de hái kěyǐ.","vi":"Mình đá cũng tạm được."},{"zh":"他们玩得很高兴。","py":"Tāmen wán de hěn gāoxìng.","vi":"Họ chơi rất vui."},{"zh":"白家月跑得不快。","py":"Bái Jiāyuè pǎo de bú kuài.","vi":"Gia Nguyệt chạy không nhanh."},{"zh":"你跑得快吗？","py":"Nǐ pǎo de kuài ma?","vi":"Bạn chạy có nhanh không?"},{"zh":"他来得早不早？","py":"Tā lái de zǎo bu zǎo?","vi":"Anh ấy đến có sớm không?"},{"zh":"他们玩得怎么样？","py":"Tāmen wán de zěnmeyàng?","vi":"Họ chơi thế nào?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">妹妹喜欢吃这个菜吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">不太喜欢，她____。</span></span></span><span class=\"qz-hint\">Em gái có thích món này không? — Không thích lắm, em ấy ăn không nhiều.</span>","answer":["吃得不多","吃得很少","吃得少","吃得不太多"],"explain":"不太喜欢，她吃得不多。 (Bú tài xǐhuan, tā chī de bù duō.)"}]},{"title":"Bổ ngữ trạng thái (2): động từ có tân ngữ","formula":"<div class=\"fx-lbl\">Lặp động từ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>(动词)</b><small>có thể bỏ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>lặp lại</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b></span></div><div class=\"fx-ex zh\">我游泳游得不快。</div><div class=\"fx-lbl\">Tân ngữ lên trước</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>宾语</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b></span></div><div class=\"fx-ex zh\">你篮球打得怎么样？</div>","summary":"<p class=\"gr-lead\">Có tân ngữ</p><ul><li>Động từ có <b>tân ngữ</b> (hoặc là từ ly hợp <span class=\"zh\">游泳、跑步、唱歌</span>) → <b>lặp lại động từ</b> hoặc <b>đưa tân ngữ lên trước</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> Từ ly hợp lặp phần động từ: <span class=\"zh\">游泳 → 游泳游得不快</span>　·　<span class=\"zh\">跑步 → 跑步跑得很快</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">得</span> không đứng ngay sau tân ngữ: <span class=\"zh\">我游泳游得不快</span> — ✗ <span class=\"zh\">我游泳得不快</span>.","examples":[{"zh":"我游泳游得不快。","py":"Wǒ yóuyǒng yóu de bú kuài.","vi":"Mình bơi không nhanh."},{"zh":"你篮球打得怎么样？","py":"Nǐ lánqiú dǎ de zěnmeyàng?","vi":"Bạn chơi bóng rổ thế nào?"},{"zh":"白家月写汉字写得很好看。","py":"Bái Jiāyuè xiě Hànzì xiě de hěn hǎokàn.","vi":"Gia Nguyệt viết chữ Hán rất đẹp."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Lớp học — Annie và Thiên Trung","lines":[{"speaker":"中","name":"Thiên Trung","zh":"安妮，你是什么时候从北京回来的？","py":"Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?","vi":"Annie, cậu từ Bắc Kinh về lúc nào thế?"},{"speaker":"妮","name":"Annie","zh":"昨天下午。天中，你怎么一下课就往外跑？","py":"Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","vi":"Chiều hôm qua. Thiên Trung, sao cậu vừa tan học đã chạy ra ngoài thế?"},{"speaker":"中","name":"Thiên Trung","zh":"我跟同学说好了，一起去打篮球。","py":"Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú.","vi":"Mình hẹn với bạn cùng lớp rồi, cùng đi chơi bóng rổ."},{"speaker":"妮","name":"Annie","zh":"我也想跟你们一起玩。","py":"Wǒ yě xiǎng gēn nǐmen yìqǐ wán.","vi":"Mình cũng muốn chơi cùng các cậu."},{"speaker":"中","name":"Thiên Trung","zh":"没问题，走吧。","py":"Méi wèntí, zǒu ba.","vi":"Không vấn đề, đi thôi."}]},{"titleZh":"课文二 · 在校园","titleVi":"Sân trường — vừa đi vừa trò chuyện","lines":[{"speaker":"妮","name":"Annie","zh":"天中，你是不是很喜欢打篮球？","py":"Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?","vi":"Thiên Trung, có phải cậu rất thích chơi bóng rổ không?"},{"speaker":"中","name":"Thiên Trung","zh":"没错。","py":"Méi cuò.","vi":"Đúng rồi."},{"speaker":"妮","name":"Annie","zh":"你还喜欢什么运动？","py":"Nǐ hái xǐhuan shénme yùndòng?","vi":"Cậu còn thích môn thể thao nào nữa?"},{"speaker":"中","name":"Thiên Trung","zh":"我还喜欢踢足球，一到星期天就跟朋友们去踢球。","py":"Wǒ hái xǐhuan tī zúqiú, yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","vi":"Mình còn thích đá bóng, cứ Chủ nhật là đi đá bóng với các bạn."},{"speaker":"妮","name":"Annie","zh":"你踢得怎么样？","py":"Nǐ tī de zěnmeyàng?","vi":"Cậu đá thế nào?"},{"speaker":"中","name":"Thiên Trung","zh":"我踢得还可以。","py":"Wǒ tī de hái kěyǐ.","vi":"Mình đá cũng tạm được."}]},{"titleZh":"课文三 · 在校园","titleVi":"Sân trường — chơi thể thao thế nào?","lines":[{"speaker":"中","name":"Thiên Trung","zh":"你篮球打得怎么样？","py":"Nǐ lánqiú dǎ de zěnmeyàng?","vi":"Cậu chơi bóng rổ thế nào?"},{"speaker":"妮","name":"Annie","zh":"打得还可以。","py":"Dǎ de hái kěyǐ.","vi":"Chơi cũng tạm được."},{"speaker":"中","name":"Thiên Trung","zh":"跑步呢？你跑得快不快？","py":"Pǎobù ne? Nǐ pǎo de kuài bu kuài?","vi":"Còn chạy bộ? Cậu chạy có nhanh không?"},{"speaker":"妮","name":"Annie","zh":"我跑得不快，也不太喜欢跑步。","py":"Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù.","vi":"Mình chạy không nhanh, cũng không thích chạy bộ lắm."},{"speaker":"中","name":"Thiên Trung","zh":"那你喜欢游泳吗？","py":"Nà nǐ xǐhuan yóuyǒng ma?","vi":"Thế cậu có thích bơi không?"},{"speaker":"妮","name":"Annie","zh":"喜欢，但我游泳游得不快。","py":"Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài.","vi":"Thích, nhưng mình bơi không nhanh."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Thiên Trung","para":true,"speaker":"中","lines":[{"zh":"我的爱好是运动。","py":"Wǒ de àihào shì yùndòng.","vi":"Sở thích của tôi là thể thao."},{"zh":"从上小学开始，我每天都跟爸爸去运动。","py":"Cóng shàng xiǎoxué kāishǐ, wǒ měi tiān dōu gēn bàba qù yùndòng.","vi":"Từ hồi học tiểu học, ngày nào tôi cũng đi tập thể thao với bố."},{"zh":"现在我篮球打得很好，足球踢得不错，游泳游得也很快。","py":"Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài.","vi":"Bây giờ tôi chơi bóng rổ rất giỏi, đá bóng khá tốt, bơi cũng rất nhanh."},{"zh":"我一有时间就去运动。","py":"Wǒ yì yǒu shíjiān jiù qù yùndòng.","vi":"Hễ có thời gian là tôi đi tập thể thao."}]}]},"extra":[],"activity":{"act":[{"zh":"小组调查","py":"xiǎozǔ diàochá","tag":"Khảo sát nhóm","mean":"Nhóm 3 · Môn thể thao","q":{"zh":"三人一组，互相问问：喜欢什么运动？星期天做什么？做得怎么样？","py":"Sān rén yì zǔ, hùxiāng wènwen: xǐhuan shénme yùndòng? Xīngqītiān zuò shénme? Zuò de zěnmeyàng?","vi":"Nhóm 3, hỏi nhau: thích môn thể thao nào? Chủ nhật làm gì? Làm thế nào?"},"items":[{"lines":[{"who":"A","zh":"天中，你有什么爱好？","py":"Tiānzhōng, nǐ yǒu shénme àihào?","vi":"Thiên Trung, cậu có sở thích gì?"},{"who":"B","zh":"我喜欢打篮球。","py":"Wǒ xǐhuan dǎ lánqiú.","vi":"Mình thích chơi bóng rổ."}]},{"zh":"你篮球打得怎么样？—— 我打得还可以。","py":"Nǐ lánqiú dǎ de zěnmeyàng? —— Wǒ dǎ de hái kěyǐ.","vi":"Cậu chơi bóng rổ thế nào? — Mình chơi tạm được."},{"zh":"天中一到星期天就去打篮球，他打得很好。","py":"Tiānzhōng yí dào Xīngqītiān jiù qù dǎ lánqiú, tā dǎ de hěn hǎo.","vi":"Cứ Chủ nhật là Thiên Trung đi chơi bóng rổ, cậu ấy chơi rất giỏi."}]}],"speak":[]}},{"id":"k2v3-b08","courseId":"k2v3","order":8,"title":"Tuy em quên, nhưng anh vẫn nhớ","titleZh":"虽然你忘了，但是我记得","titlePy":"suīrán nǐ wàng le, dànshì wǒ jìde","vocab":[{"stt":1,"hanzi":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ biểu","pos":"Danh từ","meaning":"đồng hồ đeo tay","comps":"一块手表 (một chiếc đồng hồ), 买手表 (mua đồng hồ)","example":{"zh":"这块手表很漂亮。","py":"Zhè kuài shǒubiǎo hěn piàoliang.","vi":"Chiếc đồng hồ này rất đẹp."}},{"stt":2,"hanzi":"左边","pinyin":"zuǒbian","hanviet":"Tả biên","pos":"Danh từ","meaning":"bên trái","comps":"在左边 (ở bên trái), 左边的 (cái bên trái)","example":{"zh":"书店在超市左边。","py":"Shūdiàn zài chāoshì zuǒbian.","vi":"Hiệu sách ở bên trái siêu thị."}},{"stt":3,"hanzi":"左","pinyin":"zuǒ","hanviet":"Tả","pos":"Danh từ","meaning":"trái","comps":"左手 (tay trái), 往左走 (đi về bên trái)","example":{"zh":"你往左走。","py":"Nǐ wǎng zuǒ zǒu.","vi":"Bạn đi về phía bên trái."}},{"stt":4,"hanzi":"比","pinyin":"bǐ","hanviet":"Tỷ","pos":"Giới từ / Động từ","meaning":"hơn, so với; so sánh","comps":"比我大 (lớn hơn tôi), 比一比 (so thử)","example":{"zh":"哥哥比我高。","py":"Gēge bǐ wǒ gāo.","vi":"Anh trai cao hơn mình."}},{"stt":5,"hanzi":"右边","pinyin":"yòubian","hanviet":"Hữu biên","pos":"Danh từ","meaning":"bên phải","comps":"在右边 (ở bên phải), 右边的 (cái bên phải)","example":{"zh":"右边的比左边的贵。","py":"Yòubian de bǐ zuǒbian de guì.","vi":"Cái bên phải đắt hơn cái bên trái."}},{"stt":6,"hanzi":"右","pinyin":"yòu","hanviet":"Hữu","pos":"Danh từ","meaning":"phải","comps":"右手 (tay phải), 往右走 (đi về bên phải)","example":{"zh":"往右走就是饭馆。","py":"Wǎng yòu zǒu jiù shì fànguǎn.","vi":"Đi về bên phải là đến quán ăn."}},{"stt":7,"hanzi":"记得","pinyin":"jìde","hanviet":"Ký đắc","pos":"Động từ","meaning":"nhớ","comps":"我记得 (tôi nhớ là), 不记得 (không nhớ)","example":{"zh":"你还记得我吗？","py":"Nǐ hái jìde wǒ ma?","vi":"Bạn còn nhớ mình không?"}},{"stt":8,"hanzi":"爱情片","pinyin":"àiqíngpiàn","hanviet":"Ái tình phiến","pos":"Danh từ","meaning":"phim tình cảm","comps":"看爱情片 (xem phim tình cảm), 喜欢爱情片 (thích phim tình cảm)","example":{"zh":"她很喜欢看爱情片。","py":"Tā hěn xǐhuan kàn àiqíngpiàn.","vi":"Cô ấy rất thích xem phim tình cảm."}},{"stt":9,"hanzi":"有意思","pinyin":"yǒu yìsi","hanviet":"Hữu ý tứ","pos":"Cụm từ","meaning":"thú vị, hay","comps":"很有意思 (rất thú vị), 没有意思 (chán, không hay)","example":{"zh":"这个电影很有意思。","py":"Zhège diànyǐng hěn yǒu yìsi.","vi":"Bộ phim này rất hay."}},{"stt":10,"hanzi":"点","pinyin":"diǎn","hanviet":"Điểm","pos":"Động từ","meaning":"gọi (món)","comps":"点菜 (gọi món), 点了很多菜 (gọi nhiều món)","example":{"zh":"你想点什么菜？","py":"Nǐ xiǎng diǎn shénme cài?","vi":"Bạn muốn gọi món gì?"}},{"stt":11,"hanzi":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","pos":"Liên từ","meaning":"tuy, mặc dù","comps":"虽然……但是…… (tuy… nhưng…), 虽然很累 (tuy rất mệt)","example":{"zh":"虽然很累，但是很快乐。","py":"Suīrán hěn lèi, dànshì hěn kuàilè.","vi":"Tuy rất mệt nhưng rất vui."}},{"stt":12,"hanzi":"但是","pinyin":"dànshì","hanviet":"Đãn thị","pos":"Liên từ","meaning":"nhưng","comps":"但是我记得 (nhưng tôi nhớ), 但是不太冷 (nhưng không lạnh lắm)","example":{"zh":"这家饭馆很小，但是菜很好吃。","py":"Zhè jiā fànguǎn hěn xiǎo, dànshì cài hěn hǎochī.","vi":"Quán này nhỏ nhưng đồ ăn rất ngon."}},{"stt":13,"hanzi":"花","pinyin":"huā","hanviet":"Hoa","pos":"Động từ","meaning":"tiêu, tốn (tiền, thời gian)","comps":"花钱 (tiêu tiền), 花时间 (tốn thời gian)","example":{"zh":"今天我花了不少钱。","py":"Jīntiān wǒ huāle bù shǎo qián.","vi":"Hôm nay mình tiêu khá nhiều tiền."}},{"stt":14,"hanzi":"妻子","pinyin":"qīzi","hanviet":"Thê tử","pos":"Danh từ","meaning":"vợ","comps":"他的妻子 (vợ anh ấy), 妻子和丈夫 (vợ và chồng)","example":{"zh":"他的妻子是老师。","py":"Tā de qīzi shì lǎoshī.","vi":"Vợ anh ấy là giáo viên."}},{"stt":15,"hanzi":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng phu","pos":"Danh từ","meaning":"chồng","comps":"我丈夫 (chồng tôi), 她的丈夫 (chồng cô ấy)","example":{"zh":"她丈夫在医院工作。","py":"Tā zhàngfu zài yīyuàn gōngzuò.","vi":"Chồng cô ấy làm ở bệnh viện."}},{"stt":16,"hanzi":"饭馆","pinyin":"fànguǎn","hanviet":"Phạn quán","pos":"Danh từ","meaning":"quán ăn, nhà hàng","comps":"去饭馆 (đi quán ăn), 这家饭馆 (quán ăn này)","example":{"zh":"我们去饭馆吃饭吧。","py":"Wǒmen qù fànguǎn chī fàn ba.","vi":"Mình ra quán ăn cơm nhé."}}],"hanzi":[{"char":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ biểu","chars":["手","表"],"story":"手 vẽ bàn tay xoè năm ngón. 表 = 衣 (áo) + 毛 (lông): áo lông khoác ngoài → \"bề ngoài\", rồi chỉ đồng hồ (biểu). 手表 = đồng hồ đeo tay."},{"char":"左边","pinyin":"zuǒbian","hanviet":"Tả biên","chars":["左","边"],"story":"左 = 𠂇 (bàn tay) + 工 (thước thợ): tay trái cầm thước phụ tay phải → \"trái\". 边 = 辶 + 力 → mép, phía. 左边 = phía bên trái."},{"char":"左","pinyin":"zuǒ","hanviet":"Tả","chars":["左"],"story":"左 = 𠂇 (bàn tay) + 工 (thước thợ) → tay trái. Mẹo phân biệt: 左 bên dưới là 工, 右 bên dưới là 口."},{"char":"比","pinyin":"bǐ","hanviet":"Tỷ","chars":["比"],"story":"比 vẽ hai người đứng sát cạnh nhau, cùng quay về một hướng → đặt cạnh nhau để \"so sánh\". Làm giới từ \"hơn\": 哥哥比我高."},{"char":"右边","pinyin":"yòubian","hanviet":"Hữu biên","chars":["右","边"],"story":"右 = 𠂇 (bàn tay) + 口 (miệng): bàn tay đưa thức ăn lên miệng → tay phải. 边 = phía. 右边 = phía bên phải."},{"char":"右","pinyin":"yòu","hanviet":"Hữu","chars":["右"],"story":"右 = 𠂇 (bàn tay) + 口 (miệng): tay đưa cơm lên miệng là tay phải. Mẹo: 右 dưới là 口 (ăn bằng tay phải), 左 dưới là 工."},{"char":"记得","pinyin":"jìde","hanviet":"Ký đắc","chars":["记","得"],"story":"记 = 讠 (lời nói) chỉ nghĩa + 己 jǐ chỉ âm → ghi lại, ghi nhớ. 得 = được (bài 7). 记得 = ghi được trong đầu → nhớ."},{"char":"爱情片","pinyin":"àiqíngpiàn","hanviet":"Ái tình phiến","chars":["爱","情","片"],"story":"爱 = yêu (爱好, bài 7). 情 = 忄 (lòng) + 青 qīng chỉ âm → tình cảm. 片 vẽ nửa khúc gỗ xẻ đôi → tấm mỏng → cuộn phim. 爱情片 = phim về tình yêu."},{"char":"有意思","pinyin":"yǒu yìsi","hanviet":"Hữu ý tứ","chars":["有","意","思"],"story":"有 = bàn tay 𠂇 cầm miếng thịt 月 → \"có\". 意思 = ý nghĩa (bài 1). 有意思 = có ý vị → thú vị, hay. Ngược lại: 没有意思 = chán."},{"char":"点","pinyin":"diǎn","hanviet":"Điểm","chars":["点"],"story":"点 = 占 zhān chỉ âm + 灬 (lửa) → vết chấm đen do lửa → \"chấm, điểm\". Chấm ngón tay vào thực đơn → 点菜 = gọi món. Còn gặp trong 几点 (mấy giờ)."},{"char":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","chars":["虽","然"],"story":"虽 = 口 + 虫 — chữ mượn âm để nói \"tuy\". 然 = thịt 肰 + 灬 (lửa), nghĩa gốc \"đốt\", mượn làm \"như thế\". 虽然 = tuy rằng."},{"char":"但是","pinyin":"dànshì","hanviet":"Đãn thị","chars":["但","是"],"story":"但 = 亻 (người) + 旦 dàn chỉ âm, mượn làm \"nhưng\" (đã gặp ở bài 2). 是 = là. 但是 = nhưng — đứng đầu vế sau."},{"char":"花","pinyin":"huā","hanviet":"Hoa","chars":["花"],"story":"花 = 艹 (cỏ cây) + 化 huà (biến hoá) chỉ âm → bông hoa. Làm động từ = tiêu, tốn: 花钱, 花时间 — hoa nở rồi tàn, tiền cũng \"tiêu\" đi như thế."},{"char":"妻子","pinyin":"qīzi","hanviet":"Thê tử","chars":["妻","子"],"story":"妻 vẽ bàn tay 彐 cài trâm, chải tóc cho người phụ nữ 女 → người vợ đã búi tóc. 子 là hậu tố, đọc nhẹ: qīzi."},{"char":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng phu","chars":["丈","夫"],"story":"丈 vẽ bàn tay cầm thước đo (một trượng = 10 thước). 夫 = 大 (người lớn) + vạch ngang là cây trâm cài tóc → đàn ông trưởng thành. 丈夫 = người chồng."},{"char":"饭馆","pinyin":"fànguǎn","hanviet":"Phạn quán","chars":["饭","馆"],"story":"饭 = 饣 (ăn) + 反 fǎn chỉ âm → cơm. 馆 = 饣 + 官 guān chỉ âm → nơi tiếp khách ăn ở. 饭馆 = quán cơm, nhà hàng."}],"grammar":[{"title":"Câu so sánh (1): A 比 B + tính từ","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>người / vật 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b><small>so với</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>người / vật 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">A 比 B + Tính từ</p><ul><li>Trật tự <b>ngược</b> tiếng Việt: \"đẹp hơn B\" → <span class=\"zh\">比B好看</span> — <span class=\"zh\">比 + B</span> đứng <b>trước</b> tính từ.</li><li>A, B có thể là danh từ, cụm <span class=\"zh\">的</span>, cụm động từ: <span class=\"zh\">踢足球比打篮球有意思</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">今天比昨天冷。</span> = Hôm nay lạnh <b>hơn</b> hôm qua.</p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">左边的好看比右边的</span> → ✓ <span class=\"zh\">左边的比右边的好看</span>.","examples":[{"zh":"我也觉得左边的比右边的好看。","py":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","vi":"Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải."},{"zh":"今天比昨天冷。","py":"Jīntiān bǐ zuótiān lěng.","vi":"Hôm nay lạnh hơn hôm qua."},{"zh":"他觉得踢足球比打篮球有意思。","py":"Tā juéde tī zúqiú bǐ dǎ lánqiú yǒu yìsi.","vi":"Cậu ấy thấy đá bóng thú vị hơn chơi bóng rổ."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这家饭店有包子、饺子和面条儿。你想吃什么？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">饺子吧，我觉得____。</span></span></span><span class=\"qz-hint\">Quán này có bánh bao, sủi cảo và mì. Bạn muốn ăn gì? — Sủi cảo đi, mình thấy sủi cảo ngon hơn bánh bao.</span>","answer":["饺子比包子好吃","饺子比包子更好吃"],"explain":"饺子吧，我觉得饺子比包子好吃。 (Jiǎozi ba, wǒ juéde jiǎozi bǐ bāozi hǎochī.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这家书店____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对，前边那家书店太小了。</span></span></span><span class=\"qz-hint\">Hiệu sách này to hơn hiệu phía trước. — Đúng, hiệu sách phía trước nhỏ quá.</span>","answer":["比前边那家大","比前边那家书店大","比前边那家更大"],"explain":"这家书店比前边那家大。 (Zhè jiā shūdiàn bǐ qiánbian nà jiā dà.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这条黑色的裤子____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是，我也觉得有点儿长，还是买那条白色的吧。</span></span></span><span class=\"qz-hint\">Cái quần đen này dài hơn cái trắng. — Ừ, mình cũng thấy hơi dài, hay mua cái trắng đi.</span>","answer":["比白色的长","比白色的更长","比那条白色的长"],"explain":"这条黑色的裤子比白色的长。 (Zhè tiáo hēisè de kùzi bǐ báisè de cháng.)"}]},{"title":"Câu so sánh (2): A 比 B 更 / 还 + tính từ","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>更 / 还</b><small>còn … hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">比 … 更 / 还 + Tính từ</p><ul><li><span class=\"zh\">更 / 还</span> = \"<b>còn … hơn</b>\": B vốn đã (tính từ), A còn hơn nữa.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">昨天很热，今天更热</span> → <span class=\"zh\">今天比昨天更热。</span></p>","note":"<b>Lưu ý:</b> Câu <span class=\"zh\">比</span> <b>không</b> dùng <span class=\"zh\">很、非常、太</span>: ✗ <span class=\"zh\">今天比昨天很热</span> → ✓ <span class=\"zh\">今天比昨天更热</span>.","examples":[{"zh":"我看网上说这个电影比那个爱情片更有意思。","py":"Wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","vi":"Em thấy trên mạng nói phim này còn hay hơn phim tình cảm kia."},{"zh":"今天比昨天更热。","py":"Jīntiān bǐ zuótiān gèng rè.","vi":"Hôm nay còn nóng hơn hôm qua."},{"zh":"我觉得奶茶比牛奶还好喝。","py":"Wǒ juéde nǎichá bǐ niúnǎi hái hǎohē.","vi":"Mình thấy trà sữa còn ngon hơn sữa."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你想不想喝红茶？我家的红茶很好喝。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我喜欢绿茶，____。</span></span></span><span class=\"qz-hint\">Bạn có muốn uống hồng trà không? Hồng trà nhà mình ngon lắm. — Mình thích trà xanh, mình thấy trà xanh còn ngon hơn hồng trà.</span>","answer":["我觉得绿茶比红茶更好喝","绿茶比红茶更好喝","我觉得绿茶比红茶还好喝"],"explain":"我喜欢绿茶，我觉得绿茶比红茶更好喝。 (Wǒ xǐhuan lǜchá, wǒ juéde lǜchá bǐ hóngchá gèng hǎohē.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今天晚上真冷啊！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，你明天早上起床后多穿点儿。</span></span></span><span class=\"qz-hint\">Tối nay lạnh thật! — Mai còn lạnh hơn hôm nay, sáng mai dậy con mặc thêm áo nhé.</span>","answer":["明天比今天还冷","明天比今天更冷"],"explain":"明天比今天还冷，你明天早上起床后多穿点儿。 (Míngtiān bǐ jīntiān hái lěng, nǐ míngtiān zǎoshang qǐchuáng hòu duō chuān diǎnr.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">妈妈，您的床____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">你觉得我的床更舒服，那你就在这儿睡吧。</span></span></span><span class=\"qz-hint\">Mẹ ơi, giường của mẹ còn êm hơn giường con. — Con thấy giường mẹ êm hơn thì ngủ ở đây đi.</span>","answer":["比我的床更舒服","比我的床还舒服","比我的更舒服"],"explain":"妈妈，您的床比我的床更舒服。 (Māma, nín de chuáng bǐ wǒ de chuáng gèng shūfu.)"}]},{"title":"Câu phức chuyển ngoặt 虽然……，但是……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>虽然</b><small>tuy</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>情况 A</b><small>sự việc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，但是</b><small>nhưng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>情况 B</b><small>trái ý vế trước</small></span></div>","summary":"<p class=\"gr-lead\">Tuy… nhưng…</p><ul><li>Vế sau <b>trái</b> với điều vế trước khiến ta nghĩ — giống \"tuy… nhưng…\".</li><li>Dùng <b>cả cặp</b> hoặc <b>chỉ một</b>; vế sau còn gặp <span class=\"zh\">还是</span>: <span class=\"zh\">虽然有点儿累，我还是走回家了</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> Chỉ dùng một từ: <span class=\"zh\">外边下雪了，但是不太冷。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">但是</span> đứng <b>đầu vế sau</b>, trước chủ ngữ: <span class=\"zh\">但是我记得</span> — ✗ <span class=\"zh\">我但是记得</span>.","examples":[{"zh":"虽然你忘了，但是我记得。","py":"Suīrán nǐ wàng le, dànshì wǒ jìde.","vi":"Tuy em quên nhưng anh nhớ."},{"zh":"外边下雪了，但是不太冷。","py":"Wàibian xià xuě le, dànshì bú tài lěng.","vi":"Bên ngoài tuyết rơi rồi nhưng không lạnh lắm."},{"zh":"虽然觉得有点儿累，我还是走回家了。","py":"Suīrán juéde yǒudiǎnr lèi, wǒ háishi zǒuhuí jiā le.","vi":"Tuy thấy hơi mệt nhưng mình vẫn đi bộ về nhà."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你喜欢打篮球吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，但是打得不太好。</span></span></span><span class=\"qz-hint\">Bạn có thích chơi bóng rổ không? — Tuy mình rất thích chơi bóng rổ nhưng chơi không giỏi lắm.</span>","answer":["虽然我很喜欢打篮球","虽然我喜欢打篮球","虽然很喜欢打篮球","虽然我很喜欢"],"explain":"虽然我很喜欢打篮球，但是打得不太好。 (Suīrán wǒ hěn xǐhuan dǎ lánqiú, dànshì dǎ de bú tài hǎo.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在商场","titleVi":"Trung tâm thương mại — xem đồng hồ","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"你看，这两块手表怎么样？","py":"Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","vi":"Anh xem, hai chiếc đồng hồ này thế nào?"},{"speaker":"明","name":"Lưu Minh","zh":"都不错！","py":"Dōu búcuò!","vi":"Đều đẹp cả!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我喜欢左边这个。","py":"Wǒ xǐhuan zuǒbian zhège.","vi":"Em thích chiếc bên trái này."},{"speaker":"明","name":"Lưu Minh","zh":"我也觉得左边的比右边的好看。","py":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","vi":"Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你看看要多少钱！","py":"Nǐ kànkan yào duōshao qián!","vi":"Anh xem giá bao nhiêu kìa!"},{"speaker":"明","name":"Lưu Minh","zh":"真不便宜！八千八！","py":"Zhēn bù piányi! Bā qiān bā!","vi":"Không rẻ chút nào! Tám nghìn tám!"}]},{"titleZh":"课文二 · 在电影院外面","titleVi":"Ngoài rạp chiếu phim — xem phim gì?","lines":[{"speaker":"明","name":"Lưu Minh","zh":"今天有不少电影，我们看个电影吧。","py":"Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn ge diànyǐng ba.","vi":"Hôm nay có khá nhiều phim, mình xem một bộ đi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好啊！我们看哪个？","py":"Hǎo a! Wǒmen kàn nǎge?","vi":"Được thôi! Mình xem phim nào?"},{"speaker":"明","name":"Lưu Minh","zh":"我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","py":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","vi":"Anh nhớ em thích phim tình cảm, mình xem phim tình cảm kia nhé?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","py":"Háishi kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","vi":"Thôi xem phim này đi, em thấy trên mạng nói phim này còn hay hơn phim tình cảm kia."},{"speaker":"明","name":"Lưu Minh","zh":"好。我去买票。","py":"Hǎo. Wǒ qù mǎi piào.","vi":"Được. Anh đi mua vé."},{"speaker":"雪","name":"Nhất Tuyết","zh":"到网上买吧，网上买比在这里买便宜。","py":"Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi.","vi":"Mua trên mạng đi, mua trên mạng rẻ hơn mua ở đây."}]},{"titleZh":"课文三 · 在饭馆","titleVi":"Nhà hàng — gọi món, bất ngờ","lines":[{"speaker":"明","name":"Lưu Minh","zh":"您好！就要这几个菜吧，谢谢！","py":"Nín hǎo! Jiù yào zhè jǐ ge cài ba, xièxie!","vi":"Chào chị! Lấy mấy món này nhé, cảm ơn!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"怎么点这么多菜？","py":"Zěnme diǎn zhème duō cài?","vi":"Sao gọi nhiều món thế?"},{"speaker":"明","name":"Lưu Minh","zh":"你想想，今天是几月几号？","py":"Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?","vi":"Em nghĩ xem, hôm nay là ngày mấy tháng mấy?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"8月27号。啊！我的生日！","py":"Bā yuè èrshíqī hào. À! Wǒ de shēngrì!","vi":"Ngày 27 tháng 8. A! Sinh nhật em!"},{"speaker":"明","name":"Lưu Minh","zh":"生日快乐！虽然你忘了，但是我记得。看看这是什么？","py":"Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?","vi":"Chúc mừng sinh nhật! Tuy em quên nhưng anh nhớ. Xem đây là gì nào?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"手表！吃饭、看电影、买手表，今天花了不少钱吧？","py":"Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huāle bù shǎo qián ba?","vi":"Đồng hồ! Ăn cơm, xem phim, mua đồng hồ, hôm nay tốn không ít tiền nhỉ?"},{"speaker":"明","name":"Lưu Minh","zh":"虽然花了一些钱，但是我们过了一个快乐的生日。","py":"Suīrán huāle yìxiē qián, dànshì wǒmen guòle yí ge kuàilè de shēngrì.","vi":"Tuy tốn chút tiền nhưng mình đã có một sinh nhật vui vẻ."}]},{"titleZh":"课文四 · 小语在讲述","titleVi":"Tiểu Ngữ kể chuyện hai vợ chồng","para":true,"speaker":"语","lines":[{"zh":"虽然妻子忘了今天是自己的生日，但是丈夫记得。","py":"Suīrán qīzi wàngle jīntiān shì zìjǐ de shēngrì, dànshì zhàngfu jìde.","vi":"Tuy người vợ quên hôm nay là sinh nhật mình, nhưng người chồng lại nhớ."},{"zh":"丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。","py":"Zhàngfu qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎile yí kuài fēicháng piàoliang de shǒubiǎo.","vi":"Chồng mời vợ đi nhà hàng ăn cơm, đi rạp xem phim, còn mua cho vợ một chiếc đồng hồ rất đẹp."},{"zh":"妻子觉得今天很快乐。","py":"Qīzi juéde jīntiān hěn kuàilè.","vi":"Người vợ thấy hôm nay rất vui."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Nhóm 3 · Gọi món ở quán","q":{"zh":"三人一组：一人是服务员，两人是客人。客人点菜，问问多少钱、好吃不好吃。","py":"Sān rén yì zǔ: yì rén shì fúwùyuán, liǎng rén shì kèrén. Kèrén diǎn cài, wènwen duōshao qián, hǎochī bu hǎochī.","vi":"Nhóm 3: 1 người là phục vụ, 2 người là khách. Khách gọi món, hỏi giá, hỏi món có ngon không."},"items":[{"lines":[{"who":"A","zh":"你好！我们点菜。","py":"Nǐ hǎo! Wǒmen diǎn cài.","vi":"Chào bạn! Chúng tôi gọi món."},{"who":"B","zh":"好的。你们想吃点儿什么？","py":"Hǎo de. Nǐmen xiǎng chī diǎnr shénme?","vi":"Vâng. Anh chị muốn ăn gì ạ?"}]},{"zh":"这个菜多少钱？—— 三十八块，比那个菜便宜。","py":"Zhège cài duōshao qián? —— Sānshíbā kuài, bǐ nàge cài piányi.","vi":"Món này bao nhiêu tiền? — 38 tệ, rẻ hơn món kia."},{"zh":"虽然饭馆的菜很好吃，但是我觉得妈妈做的更好吃。","py":"Suīrán fànguǎn de cài hěn hǎochī, dànshì wǒ juéde māma zuò de gèng hǎochī.","vi":"Tuy món ở quán rất ngon nhưng mình thấy mẹ nấu còn ngon hơn."}]}],"speak":[]}},{"id":"k2v3-b09","courseId":"k2v3","order":9,"title":"Em đi mua cốc trà sữa","titleZh":"我去买杯奶茶","titlePy":"wǒ qù mǎi bēi nǎichá","vocab":[{"stt":1,"hanzi":"坏","pinyin":"huài","hanviet":"Hoại","pos":"Tính từ","meaning":"hỏng, xấu","comps":"坏了 (hỏng rồi), 手表坏了 (đồng hồ hỏng rồi)","example":{"zh":"我的手表坏了。","py":"Wǒ de shǒubiǎo huài le.","vi":"Đồng hồ của mình hỏng rồi."}},{"stt":2,"hanzi":"旁边","pinyin":"pángbiān","hanviet":"Bàng biên","pos":"Danh từ","meaning":"bên cạnh","comps":"在旁边 (ở bên cạnh), 学校旁边 (cạnh trường)","example":{"zh":"超市就在学校旁边。","py":"Chāoshì jiù zài xuéxiào pángbiān.","vi":"Siêu thị ở ngay cạnh trường."}},{"stt":3,"hanzi":"男孩儿","pinyin":"nánháir","hanviet":"Nam hài nhi","pos":"Danh từ","meaning":"cậu bé, bé trai","comps":"一个男孩儿 (một cậu bé), 那个男孩儿 (cậu bé kia)","example":{"zh":"那个男孩儿是我弟弟。","py":"Nàge nánháir shì wǒ dìdi.","vi":"Cậu bé kia là em trai mình."}},{"stt":4,"hanzi":"这样","pinyin":"zhèyàng","hanviet":"Giá dạng","pos":"Đại từ","meaning":"như thế này, thế này","comps":"这样的裤子 (cái quần như thế này), 这样做 (làm thế này)","example":{"zh":"我也想买这样的书包。","py":"Wǒ yě xiǎng mǎi zhèyàng de shūbāo.","vi":"Mình cũng muốn mua cái cặp như thế này."}},{"stt":5,"hanzi":"个子","pinyin":"gèzi","hanviet":"Cá tử","pos":"Danh từ","meaning":"vóc dáng, chiều cao","comps":"个子高 (dáng cao), 个子不高 (người không cao)","example":{"zh":"他个子很高。","py":"Tā gèzi hěn gāo.","vi":"Anh ấy dáng người rất cao."}},{"stt":6,"hanzi":"那么","pinyin":"nàme","hanviet":"Na ma","pos":"Đại từ","meaning":"như thế, như vậy (đến thế)","comps":"那么高 (cao đến thế), 那么好看 (đẹp thế)","example":{"zh":"我没有他那么高。","py":"Wǒ méiyǒu tā nàme gāo.","vi":"Mình không cao bằng anh ấy."}},{"stt":7,"hanzi":"高","pinyin":"gāo","hanviet":"Cao","pos":"Tính từ","meaning":"cao","comps":"很高 (rất cao), 个子高 (dáng cao)","example":{"zh":"这个男孩儿真高！","py":"Zhège nánháir zhēn gāo!","vi":"Cậu bé này cao thật!"}},{"stt":8,"hanzi":"门口","pinyin":"ménkǒu","hanviet":"Môn khẩu","pos":"Danh từ","meaning":"cửa, cổng (lối ra vào)","comps":"学校门口 (cổng trường), 在门口等 (đợi ở cửa)","example":{"zh":"我在门口等你。","py":"Wǒ zài ménkǒu děng nǐ.","vi":"Mình đợi bạn ở cửa."}},{"stt":9,"hanzi":"咖啡","pinyin":"kāfēi","hanviet":"Ca phê","pos":"Danh từ","meaning":"cà phê","comps":"喝咖啡 (uống cà phê), 咖啡店 (quán cà phê)","example":{"zh":"我想喝杯咖啡。","py":"Wǒ xiǎng hē bēi kāfēi.","vi":"Mình muốn uống một cốc cà phê."}},{"stt":10,"hanzi":"离","pinyin":"lí","hanviet":"Ly","pos":"Động từ","meaning":"cách (xa)","comps":"离这儿 (cách đây), 离家很近 (cách nhà rất gần)","example":{"zh":"学校离我家不远。","py":"Xuéxiào lí wǒ jiā bù yuǎn.","vi":"Trường cách nhà mình không xa."}},{"stt":11,"hanzi":"近","pinyin":"jìn","hanviet":"Cận","pos":"Tính từ","meaning":"gần","comps":"很近 (rất gần), 离家近 (gần nhà)","example":{"zh":"超市离这儿很近。","py":"Chāoshì lí zhèr hěn jìn.","vi":"Siêu thị cách đây rất gần."}},{"stt":12,"hanzi":"走路","pinyin":"zǒulù","hanviet":"Tẩu lộ","pos":"Động từ","meaning":"đi bộ","comps":"走路去 (đi bộ đến), 走路回家 (đi bộ về nhà)","example":{"zh":"我们走路回家吧。","py":"Wǒmen zǒulù huí jiā ba.","vi":"Mình đi bộ về nhà đi."}},{"stt":13,"hanzi":"周","pinyin":"zhōu","hanviet":"Chu","pos":"Danh từ","meaning":"tuần","comps":"这周 (tuần này), 下周 (tuần sau)","example":{"zh":"这周我很忙。","py":"Zhè zhōu wǒ hěn máng.","vi":"Tuần này mình rất bận."}}],"hanzi":[{"char":"坏","pinyin":"huài","hanviet":"Hoại","chars":["坏"],"story":"坏 = bộ Thổ 土 (đất) + 不 (không): bức tường đất không còn nguyên → đổ nát, \"hỏng\". (Phồn thể 壞: 土 + 褱 huái chỉ âm.)"},{"char":"旁边","pinyin":"pángbiān","hanviet":"Bàng biên","chars":["旁","边"],"story":"旁 là chữ hình thanh, phần dưới 方 fāng chỉ âm, nghĩa \"bên, cạnh\". 边 = 辶 + 力 → mép, phía. 旁边 = phía bên cạnh."},{"char":"男孩儿","pinyin":"nánháir","hanviet":"Nam hài nhi","chars":["男","孩","儿"],"story":"男 = 田 (ruộng) + 力 (sức): người dùng sức cày ruộng → đàn ông, con trai. 孩 = 子 (trẻ con) + 亥 hài chỉ âm → đứa trẻ. 儿 là hậu tố er. 男孩儿 = bé trai."},{"char":"这样","pinyin":"zhèyàng","hanviet":"Giá dạng","chars":["这","样"],"story":"这 = này. 样 = bộ Mộc 木 (gỗ) + 羊 yáng chỉ âm → khuôn gỗ làm mẫu → \"kiểu, dạng\". 这样 = kiểu này, như thế này."},{"char":"个子","pinyin":"gèzi","hanviet":"Cá tử","chars":["个","子"],"story":"个 = cái (lượng từ chung). 子 là hậu tố, đọc nhẹ. 个子 = cái thân người → vóc dáng, chiều cao: 个子很高."},{"char":"那么","pinyin":"nàme","hanviet":"Na ma","chars":["那","么"],"story":"那 = kia. 么 là hậu tố đã gặp trong 什么, 怎么, 这么. 那么 = như thế kia, đến thế: 没有他那么高."},{"char":"高","pinyin":"gāo","hanviet":"Cao","chars":["高"],"story":"高 là chữ tượng hình vẽ toà lầu nhiều tầng: mái nhọn trên cùng, các tầng ở giữa, cổng 口 bên dưới → \"cao\"."},{"char":"门口","pinyin":"ménkǒu","hanviet":"Môn khẩu","chars":["门","口"],"story":"门 (門) vẽ hai cánh cửa → \"cửa\". 口 = miệng → chỗ mở ra vào. 门口 = cửa ra vào, cổng."},{"char":"咖啡","pinyin":"kāfēi","hanviet":"Ca phê","chars":["咖","啡"],"story":"咖啡 là từ phiên âm \"coffee\". Cả hai chữ đều có bộ Khẩu 口 — dấu hiệu chữ phiên âm; 加 jiā, 非 fēi chỉ âm."},{"char":"离","pinyin":"lí","hanviet":"Ly","chars":["离"],"story":"离 (phồn thể 離 có bộ 隹 = chim): chim rời tổ bay đi → \"rời xa\", rồi thành \"cách\": 学校离家很近."},{"char":"近","pinyin":"jìn","hanviet":"Cận","chars":["近"],"story":"近 = bộ Sước 辶 (bước đi) + 斤 jīn chỉ âm → chỉ đi vài bước là tới → \"gần\". Từ trái nghĩa 远 (bài 2) cũng có bộ 辶."},{"char":"走路","pinyin":"zǒulù","hanviet":"Tẩu lộ","chars":["走","路"],"story":"走 = đi (bài 5). 路 = bộ Túc ⻊ (chân) + 各 gè chỉ âm → con đường chân đi qua. 走路 = đi đường → đi bộ."},{"char":"周","pinyin":"zhōu","hanviet":"Chu","chars":["周"],"story":"周 = khung 冂 bao quanh 土 và 口 → \"bao quanh, một vòng\" (chu). Một vòng bảy ngày → \"tuần\": 这周, 下周."}],"grammar":[{"title":"Câu so sánh (3): A 没有 B + tính từ","formula":"<div class=\"fx-lbl\">Không bằng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(那么) 形容词</b></span></div><div class=\"fx-ex zh\">这块手表没有那块好看。</div><div class=\"fx-lbl\">Câu hỏi</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(那么) 形容词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吗？</b></span></div><div class=\"fx-ex zh\">妹妹有姐姐高吗？</div>","summary":"<p class=\"gr-lead\">A 没有 B + Tính từ</p><ul><li><span class=\"zh\">A 没有 B + 形容词</span> = A <b>không</b> (tính từ) <b>bằng</b> B. Thêm <span class=\"zh\">这么 / 那么</span> để nhấn B ở mức cao.</li></ul>","note":"<b>Lưu ý:</b> Trước tính từ <b>không</b> thêm <span class=\"zh\">很</span>: ✗ <span class=\"zh\">昨天没有今天很冷</span>.","examples":[{"zh":"儿子的个子没有他那么高。","py":"Érzi de gèzi méiyǒu tā nàme gāo.","vi":"Con mình không cao bằng cậu bé đó."},{"zh":"昨天没有今天这么冷。","py":"Zuótiān méiyǒu jīntiān zhème lěng.","vi":"Hôm qua không lạnh bằng hôm nay."},{"zh":"这块手表没有那块好看。","py":"Zhè kuài shǒubiǎo méiyǒu nà kuài hǎokàn.","vi":"Chiếc đồng hồ này không đẹp bằng chiếc kia."},{"zh":"妹妹有姐姐高吗？","py":"Mèimei yǒu jiějie gāo ma?","vi":"Em gái có cao bằng chị không?"},{"zh":"那件衣服有这件好看吗？","py":"Nà jiàn yīfu yǒu zhè jiàn hǎokàn ma?","vi":"Cái áo kia có đẹp bằng cái này không?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我女儿今年六岁多了，你儿子几岁了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">四岁多，没有____。</span></span></span><span class=\"qz-hint\">Con gái mình năm nay hơn sáu tuổi rồi, con trai bạn mấy tuổi? — Hơn bốn tuổi, không lớn bằng con gái bạn.</span>","answer":["你女儿大","你的女儿大"],"explain":"四岁多，没有你女儿大。 (Sì suì duō, méiyǒu nǐ nǚ'ér dà.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这件黑色的衣服好看吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好看，但____，还是买那件白色的吧。</span></span></span><span class=\"qz-hint\">Cái áo đen này đẹp không? — Đẹp, nhưng không đẹp bằng cái trắng kia, mua cái trắng đi.</span>","answer":["没有那件白色的好看","没有白色的好看","没有那件白色的衣服好看"],"explain":"好看，但没有那件白色的好看，还是买那件白色的吧。 (Hǎokàn, dàn méiyǒu nà jiàn báisè de hǎokàn, háishi mǎi nà jiàn báisè de ba.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今天{{0}}昨天那么{{1}}吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没有，我觉得昨天更热。</span></span></span><span class=\"qz-hint\">Hôm nay có nóng bằng hôm qua không? — Không, mình thấy hôm qua nóng hơn.</span>","blanks":[["有"],["热"]],"explain":"今天有昨天那么热吗？ (Jīntiān yǒu zuótiān nàme rè ma?)"}]},{"title":"Động từ 离: khoảng cách","formula":"<div class=\"fx-lbl\">Nơi chốn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>nơi 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>离</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>nơi 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(很 / 有点儿) 远 / 近</b></span></div><div class=\"fx-ex zh\">学校离医院不远。</div><div class=\"fx-lbl\">Thời gian</div><div class=\"fx-row\"><span class=\"fx-p\"><b>现在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>离</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>时间点</b><small>mốc thời gian</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>还有 + 时间段</b><small>còn … nữa</small></span></div><div class=\"fx-ex zh\">现在离考试还有三天。</div>","summary":"<p class=\"gr-lead\">A cách B…</p><ul><li><span class=\"zh\">离</span> = \"cách\": nói khoảng cách <b>nơi chốn</b> (xa, gần) hoặc <b>thời gian</b> (còn bao lâu nữa).</li></ul>","note":"<b>Lưu ý:</b> Nói khoảng cách dùng <span class=\"zh\">离</span>, không dùng <span class=\"zh\">从</span>: ✗ <span class=\"zh\">我家从学校很近</span> → ✓ <span class=\"zh\">我家离学校很近</span>.","examples":[{"zh":"咖啡店离这儿有点儿远。","py":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","vi":"Quán cà phê cách đây hơi xa."},{"zh":"学校离医院不远。","py":"Xuéxiào lí yīyuàn bù yuǎn.","vi":"Trường cách bệnh viện không xa."},{"zh":"现在离我的生日还有三天。","py":"Xiànzài lí wǒ de shēngrì hái yǒu sān tiān.","vi":"Từ giờ đến sinh nhật mình còn ba ngày."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你每天都开车去上班吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，公司____。</span></span></span><span class=\"qz-hint\">Ngày nào bạn cũng lái xe đi làm à? — Ừ, công ty cách nhà rất xa.</span>","answer":["离家很远","离家远","离我家很远","离家太远"],"explain":"是啊，公司离家很远。 (Shì a, gōngsī lí jiā hěn yuǎn.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们酒店____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">太好了，我很想去商场看看。</span></span></span><span class=\"qz-hint\">Khách sạn mình cách trung tâm thương mại rất gần. — Tốt quá, mình rất muốn đi trung tâm thương mại xem.</span>","answer":["离商场很近","离商场近","离商场不远"],"explain":"我们酒店离商场很近。 (Wǒmen jiǔdiàn lí shāngchǎng hěn jìn.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">现在____还有一个小时。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">那想想下班后我们去哪儿吃饭吧。</span></span></span><span class=\"qz-hint\">Bây giờ còn một tiếng nữa là tan làm. — Vậy nghĩ xem tan làm mình đi đâu ăn nhé.</span>","answer":["离下班"],"explain":"现在离下班还有一个小时。 (Xiànzài lí xiàbān hái yǒu yí ge xiǎoshí.)"}]},{"title":"Bổ ngữ thời lượng (1)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b><small>bao lâu: 十分钟、两年…</small></span></div>","summary":"<p class=\"gr-lead\">Làm bao lâu</p><ul><li><b>Khoảng thời gian</b> (十分钟、两年、一个下午) đứng <b>sau</b> động từ, cho biết làm <b>bao lâu</b>.</li><li>Khác <b>mốc thời gian</b> đứng trước động từ: <span class=\"zh\">我八点学习</span> · <span class=\"zh\">我学习两个小时</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">时量补语 (1)</span> · Có tân ngữ</h4><p>Vị trí tân ngữ</p><div class=\"gr-formula\"><div class=\"fx-lbl\">TN sự vật</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>sự vật</small></span></div><div class=\"fx-ex zh\">我看了一个晚上电视。</div><div class=\"fx-lbl\">TN người</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>người, đại từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b></span></div><div class=\"fx-ex zh\">李文等了她一个小时。</div><div class=\"fx-lbl\">Lặp động từ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b></span></div><div class=\"fx-ex zh\">他们学中文学了两年。</div><div class=\"fx-lbl\">Vẫn đang làm</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>cuối câu</small></span></div><div class=\"fx-ex zh\">他写了半个小时汉字了。</div></div><p class=\"gr-key\">Từ ly hợp lặp phần động từ: <span class=\"zh\">安妮游泳游了一个下午。</span>　·　<span class=\"zh\">陈天中跑步跑了两个小时。</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他们学了两年。</span>　·　<span class=\"zh\">走半个多小时就到了。</span></p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">我两个小时学习了</span> → ✓ <span class=\"zh\">我学习了两个小时</span>.","examples":[{"zh":"走半个多小时就到了。","py":"Zǒu bàn ge duō xiǎoshí jiù dào le.","vi":"Đi hơn nửa tiếng là tới."},{"zh":"他们学了两年。","py":"Tāmen xuéle liǎng nián.","vi":"Họ học hai năm rồi."},{"zh":"我们休息十分钟。","py":"Wǒmen xiūxi shí fēnzhōng.","vi":"Chúng ta nghỉ mười phút."},{"zh":"我看了一个晚上电视。","py":"Wǒ kànle yí ge wǎnshang diànshì.","vi":"Mình xem ti vi cả buổi tối."},{"zh":"李文等了她一个小时。","py":"Lǐ Wén děngle tā yí ge xiǎoshí.","vi":"Lý Văn đợi cô ấy một tiếng."},{"zh":"我找了陈天中二十多分钟。","py":"Wǒ zhǎole Chén Tiānzhōng èrshí duō fēnzhōng.","vi":"Mình tìm Thiên Trung hơn hai mươi phút."},{"zh":"他们学中文学了两年。","py":"Tāmen xué Zhōngwén xuéle liǎng nián.","vi":"Họ học tiếng Trung hai năm rồi."},{"zh":"李文等她等了一个小时。","py":"Lǐ Wén děng tā děngle yí ge xiǎoshí.","vi":"Lý Văn đợi cô ấy những một tiếng."},{"zh":"安妮游泳游了一个下午。","py":"Ānnī yóuyǒng yóule yí ge xiàwǔ.","vi":"Annie bơi cả buổi chiều."},{"zh":"陈天中跑步跑了两个小时。","py":"Chén Tiānzhōng pǎobù pǎole liǎng ge xiǎoshí.","vi":"Thiên Trung chạy bộ hai tiếng."},{"zh":"他写了半个小时汉字了。","py":"Tā xiěle bàn ge xiǎoshí Hànzì le.","vi":"Cậu ấy viết chữ Hán được nửa tiếng rồi (vẫn đang viết)."},{"zh":"陈天中跑步跑了两个小时了。","py":"Chén Tiānzhōng pǎobù pǎole liǎng ge xiǎoshí le.","vi":"Thiên Trung chạy bộ được hai tiếng rồi (vẫn đang chạy)."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你____，我去给你拿杯水来。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">你别忙了，我说完话就回去了。</span></span></span><span class=\"qz-hint\">Bạn ngồi một lát, mình đi lấy cho bạn cốc nước. — Bạn đừng bận tâm, mình nói xong là về.</span>","answer":["坐一会儿","坐一下"],"explain":"你坐一会儿，我去给你拿杯水来。 (Nǐ zuò yíhuìr, wǒ qù gěi nǐ ná bēi shuǐ lái.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在商店","titleVi":"Trong cửa hàng — chọn quần cho con","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"儿子的裤子坏了，我们给他买条新的吧。","py":"Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","vi":"Quần của con trai rách rồi, mình mua cho con chiếc mới đi."},{"speaker":"明","name":"Lưu Minh","zh":"好啊。","py":"Hǎo a.","vi":"Được."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你看这条黑色的怎么样？","py":"Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","vi":"Anh xem chiếc màu đen này thế nào?"},{"speaker":"明","name":"Lưu Minh","zh":"没有你上次买的那条好看。","py":"Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn.","vi":"Không đẹp bằng chiếc em mua lần trước."},{"speaker":"雪","name":"Nhất Tuyết","zh":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","py":"Pángbiān nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","vi":"Cậu bé bên cạnh kia mặc đúng loại quần này, em thấy đẹp lắm mà!"},{"speaker":"明","name":"Lưu Minh","zh":"儿子的个子没有他那么高，穿上就不会太好看。","py":"Érzi de gèzi méiyǒu tā nàme gāo, chuānshang jiù bú huì tài hǎokàn.","vi":"Con mình không cao bằng cậu bé đó, mặc vào sẽ không đẹp lắm đâu."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好吧，我们再去那边看看。","py":"Hǎo ba, wǒmen zài qù nàbiān kànkan.","vi":"Thôi được, mình sang bên kia xem tiếp."}]},{"titleZh":"课文二 · 在商店门口","titleVi":"Cửa hàng — trà sữa hay cà phê?","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"门口有家奶茶店。你想喝杯奶茶吗？","py":"Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?","vi":"Ở cửa có một quán trà sữa. Anh muốn uống một cốc không?"},{"speaker":"明","name":"Lưu Minh","zh":"我想喝咖啡，还是去咖啡店吧。","py":"Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba.","vi":"Anh muốn uống cà phê, hay là đi quán cà phê đi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"咖啡店离这儿有点儿远。","py":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","vi":"Quán cà phê cách đây hơi xa."},{"speaker":"明","name":"Lưu Minh","zh":"没关系，那家店的咖啡很好喝。","py":"Méi guānxi, nà jiā diàn de kāfēi hěn hǎohē.","vi":"Không sao, cà phê quán đó rất ngon."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那你等一下，我去买杯奶茶。","py":"Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá.","vi":"Vậy anh đợi chút, em đi mua cốc trà sữa."},{"speaker":"明","name":"Lưu Minh","zh":"你不想喝咖啡吗？","py":"Nǐ bù xiǎng hē kāfēi ma?","vi":"Em không muốn uống cà phê à?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"喝了咖啡，晚上就别想睡觉了。","py":"Hēle kāfēi, wǎnshang jiù bié xiǎng shuìjiào le.","vi":"Uống cà phê vào thì tối đừng mong ngủ được."}]},{"titleZh":"课文三 · 在咖啡店门口","titleVi":"Trước quán cà phê — về nhà thế nào?","lines":[{"speaker":"明","name":"Lưu Minh","zh":"我们打车回去吧。","py":"Wǒmen dǎchē huíqù ba.","vi":"Mình bắt taxi về đi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"这里离家很近，还是走路吧。","py":"Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","vi":"Chỗ này cách nhà rất gần, đi bộ đi."},{"speaker":"明","name":"Lưu Minh","zh":"要走多长时间？","py":"Yào zǒu duō cháng shíjiān?","vi":"Phải đi mất bao lâu?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"走半个多小时就到了。","py":"Zǒu bàn ge duō xiǎoshí jiù dào le.","vi":"Đi hơn nửa tiếng là tới."},{"speaker":"明","name":"Lưu Minh","zh":"好的。每天上下班都坐车，今天运动运动吧。","py":"Hǎo de. Měi tiān shàng xià bān dōu zuò chē, jīntiān yùndòng yùndòng ba.","vi":"Được. Ngày nào đi làm cũng ngồi xe, hôm nay vận động chút vậy."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Nhất Tuyết","para":true,"speaker":"雪","lines":[{"zh":"这周刘明休息，我下班后跟他去了一家商店。","py":"Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qùle yì jiā shāngdiàn.","vi":"Tuần này Lưu Minh được nghỉ, tan làm tôi cùng anh ấy đi một cửa hàng."},{"zh":"商店里边的衣服没有大商场里的好看。","py":"Shāngdiàn lǐbian de yīfu méiyǒu dà shāngchǎng li de hǎokàn.","vi":"Quần áo trong cửa hàng không đẹp bằng ở trung tâm thương mại lớn."},{"zh":"我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。","py":"Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuòle zuò.","vi":"Chúng tôi không mua được bộ nào ưng ý, ra khỏi cửa hàng liền vào quán cà phê ngồi một lát."},{"zh":"因为想运动运动，所以喝完东西，我们就走回家了。","py":"Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le.","vi":"Vì muốn vận động một chút nên uống xong chúng tôi đi bộ về nhà."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Đi du lịch bằng gì?","q":{"zh":"两人一组，商量一起去旅游怎么去，比一比坐飞机、坐火车和开车。","py":"Liǎng rén yì zǔ, shāngliang yìqǐ qù lǚyóu zěnme qù, bǐ yi bǐ zuò fēijī, zuò huǒchē hé kāichē.","vi":"Theo cặp: bàn nhau đi du lịch bằng gì, so sánh máy bay, tàu hoả và lái xe."},"items":[{"lines":[{"who":"A","zh":"你想怎么去上海？","py":"Nǐ xiǎng zěnme qù Shànghǎi?","vi":"Bạn muốn đi Thượng Hải bằng gì?"},{"who":"B","zh":"我们都会开车，开车去吧。","py":"Wǒmen dōu huì kāichē, kāichē qù ba.","vi":"Bọn mình đều biết lái xe, lái xe đi."}]},{"zh":"上海离这儿很远，开车要开十多个小时。","py":"Shànghǎi lí zhèr hěn yuǎn, kāichē yào kāi shí duō ge xiǎoshí.","vi":"Thượng Hải cách đây rất xa, lái xe mất hơn mười tiếng."},{"zh":"坐火车没有坐飞机快，但是比坐飞机便宜。","py":"Zuò huǒchē méiyǒu zuò fēijī kuài, dànshì bǐ zuò fēijī piányi.","vi":"Đi tàu không nhanh bằng máy bay, nhưng rẻ hơn."}]}],"speak":[]},"review":{"range":"7–9","rows":[{"l":7,"zh":"紧缩复句 \"一……就……\"","vi":"Câu phức rút gọn 一……就……","ex":{"zh":"我一下飞机就给妈妈打电话。","py":"Wǒ yí xià fēijī jiù gěi māma dǎ diànhuà.","vi":"Vừa xuống máy bay là mình gọi điện cho mẹ."}},{"l":7,"zh":"状态补语 (1)","vi":"Bổ ngữ trạng thái (1)","ex":{"zh":"他跑得很快。","py":"Tā pǎo de hěn kuài.","vi":"Cậu ấy chạy rất nhanh."}},{"l":7,"zh":"状态补语 (2)","vi":"Bổ ngữ trạng thái (2)","ex":{"zh":"他打篮球打得很好。","py":"Tā dǎ lánqiú dǎ de hěn hǎo.","vi":"Cậu ấy chơi bóng rổ rất giỏi."}},{"l":8,"zh":"比较句 (1)","vi":"Câu so sánh (1) A 比 B","ex":{"zh":"今天比昨天冷。","py":"Jīntiān bǐ zuótiān lěng.","vi":"Hôm nay lạnh hơn hôm qua."}},{"l":8,"zh":"比较句 (2)","vi":"Câu so sánh (2) 更 / 还","ex":{"zh":"今天比昨天更冷。","py":"Jīntiān bǐ zuótiān gèng lěng.","vi":"Hôm nay còn lạnh hơn hôm qua."}},{"l":8,"zh":"转折复句 \"虽然……，但是……\"","vi":"Câu phức chuyển ngoặt 虽然……但是……","ex":{"zh":"外边虽然下雪了，但是不冷。","py":"Wàibian suīrán xià xuě le, dànshì bù lěng.","vi":"Bên ngoài tuy có tuyết nhưng không lạnh."}},{"l":9,"zh":"比较句 (3)","vi":"Câu so sánh (3) 没有","ex":{"zh":"姐姐没有哥哥高。","py":"Jiějie méiyǒu gēge gāo.","vi":"Chị không cao bằng anh."}},{"l":9,"zh":"动词 \"离\"","vi":"Động từ 离","ex":{"zh":"我家离学校很近。","py":"Wǒ jiā lí xuéxiào hěn jìn.","vi":"Nhà mình cách trường rất gần."}},{"l":9,"zh":"时量补语 (1)","vi":"Bổ ngữ thời lượng (1)","ex":{"zh":"我们休息十分钟。","py":"Wǒmen xiūxi shí fēnzhōng.","vi":"Chúng ta nghỉ mười phút."}}]}},{"id":"k2v3-b10","courseId":"k2v3","order":10,"title":"Sắp thi rồi","titleZh":"就要考试了","titlePy":"jiù yào kǎoshì le","vocab":[{"stt":1,"hanzi":"开学","pinyin":"kāixué","hanviet":"Khai học","pos":"Động từ","meaning":"khai giảng, vào năm học","comps":"明天开学 (mai khai giảng), 快要开学了 (sắp khai giảng)","example":{"zh":"我们九月一号开学。","py":"Wǒmen jiǔ yuè yī hào kāixué.","vi":"Chúng mình khai giảng ngày 1 tháng 9."}},{"stt":2,"hanzi":"门","pinyin":"mén","hanviet":"Môn","pos":"Danh từ","meaning":"cửa","comps":"开门 (mở cửa), 门后面 (sau cửa)","example":{"zh":"请你开一下门。","py":"Qǐng nǐ kāi yíxià mén.","vi":"Bạn mở cửa giúp mình nhé."}},{"stt":3,"hanzi":"后面","pinyin":"hòumiàn","hanviet":"Hậu diện","pos":"Danh từ","meaning":"phía sau","comps":"门后面 (sau cửa), 在后面 (ở phía sau)","example":{"zh":"超市在学校后面。","py":"Chāoshì zài xuéxiào hòumiàn.","vi":"Siêu thị ở phía sau trường."}},{"stt":4,"hanzi":"笔","pinyin":"bǐ","hanviet":"Bút","pos":"Danh từ","meaning":"bút","comps":"画笔 (bút vẽ), 我的笔 (bút của tôi)","example":{"zh":"你的笔在桌子上。","py":"Nǐ de bǐ zài zhuōzi shang.","vi":"Bút của bạn ở trên bàn."}},{"stt":5,"hanzi":"帮","pinyin":"bāng","hanviet":"Bang","pos":"Động từ","meaning":"giúp","comps":"帮你 (giúp bạn), 帮忙 (giúp đỡ)","example":{"zh":"我帮你拿吧。","py":"Wǒ bāng nǐ ná ba.","vi":"Để mình cầm giúp bạn."}},{"stt":6,"hanzi":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","pos":"Động từ / Danh từ","meaning":"thi; kỳ thi","comps":"明天考试 (mai thi), 准备考试 (ôn thi)","example":{"zh":"明天我们考试。","py":"Míngtiān wǒmen kǎoshì.","vi":"Ngày mai chúng mình thi."}},{"stt":7,"hanzi":"词","pinyin":"cí","hanviet":"Từ","pos":"Danh từ","meaning":"từ (ngữ)","comps":"生词 (từ mới), 这个词 (từ này)","example":{"zh":"这个词是什么意思？","py":"Zhège cí shì shénme yìsi?","vi":"Từ này nghĩa là gì?"}},{"stt":8,"hanzi":"本子","pinyin":"běnzi","hanviet":"Bản tử","pos":"Danh từ","meaning":"quyển vở","comps":"一个本子 (một quyển vở), 本子上 (trong vở)","example":{"zh":"我的本子在书包里。","py":"Wǒ de běnzi zài shūbāo li.","vi":"Vở của mình ở trong cặp."}},{"stt":9,"hanzi":"错","pinyin":"cuò","hanviet":"Thác","pos":"Tính từ","meaning":"sai","comps":"做错 (làm sai), 没错 (đúng rồi)","example":{"zh":"这个字你写错了。","py":"Zhège zì nǐ xiěcuò le.","vi":"Chữ này bạn viết sai rồi."}},{"stt":10,"hanzi":"题","pinyin":"tí","hanviet":"Đề","pos":"Danh từ","meaning":"đề, câu hỏi, bài tập","comps":"做题 (làm bài), 做错的题 (câu làm sai)","example":{"zh":"这个题我不会做。","py":"Zhège tí wǒ bú huì zuò.","vi":"Câu này mình không biết làm."}},{"stt":11,"hanzi":"还是","pinyin":"háishi","hanviet":"Hoàn thị","pos":"Liên từ","meaning":"hay là (trong câu hỏi lựa chọn)","comps":"A 还是 B (A hay B), 今天还是明天 (hôm nay hay mai)","example":{"zh":"你喝茶还是喝咖啡？","py":"Nǐ hē chá háishi hē kāfēi?","vi":"Bạn uống trà hay uống cà phê?"}},{"stt":12,"hanzi":"考","pinyin":"kǎo","hanviet":"Khảo","pos":"Động từ","meaning":"thi","comps":"考得很好 (thi rất tốt), 考完 (thi xong)","example":{"zh":"你考得怎么样？","py":"Nǐ kǎo de zěnmeyàng?","vi":"Bạn thi thế nào?"}},{"stt":13,"hanzi":"快要","pinyin":"kuàiyào","hanviet":"Khoái yếu","pos":"Phó từ","meaning":"sắp","comps":"快要……了 (sắp… rồi), 快要开学了 (sắp khai giảng)","example":{"zh":"火车快要开了。","py":"Huǒchē kuàiyào kāi le.","vi":"Tàu sắp chạy rồi."}},{"stt":14,"hanzi":"笑","pinyin":"xiào","hanviet":"Tiếu","pos":"Động từ","meaning":"cười","comps":"笑了 (cười rồi), 别笑 (đừng cười)","example":{"zh":"听完，大家都笑了。","py":"Tīngwán, dàjiā dōu xiào le.","vi":"Nghe xong, mọi người đều cười."}}],"hanzi":[{"char":"开学","pinyin":"kāixué","hanviet":"Khai học","chars":["开","学"],"story":"开 = mở (bài 6). 学 vẽ mái nhà, bên dưới là đứa trẻ 子, phía trên là hai tay cầm thẻ đếm → \"học\". 开学 = mở đầu việc học → khai giảng."},{"char":"门","pinyin":"mén","hanviet":"Môn","chars":["门"],"story":"门 (門) vẽ hai cánh cửa đứng đối nhau; giản thể chỉ còn khung cửa. Đã gặp trong 门口 (bài 9)."},{"char":"后面","pinyin":"hòumiàn","hanviet":"Hậu diện","chars":["后","面"],"story":"后 (phồn thể 後 = 彳 bước đi + 幺 sợi dây + 夊 bước chậm): bị dây vướng chân nên đi chậm, tụt lại → \"sau\". 面 = phía (bài 5). 后面 = phía sau."},{"char":"笔","pinyin":"bǐ","hanviet":"Bút","chars":["笔"],"story":"笔 = bộ Trúc ⺮ (tre) + 毛 (lông): bút lông cán tre → \"bút\". Đã gặp trong 画笔 (bài 6)."},{"char":"帮","pinyin":"bāng","hanviet":"Bang","chars":["帮"],"story":"帮 = 邦 bāng chỉ âm + 巾 (mảnh vải). Nghĩa gốc là phần vải đắp quanh giày, rồi thành \"đỡ, giúp\". Đã gặp trong 帮忙 (bài 1)."},{"char":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","chars":["考","试"],"story":"考 vẽ ông già lưng còng chống gậy → nghĩa gốc \"già\", sau mượn làm \"khảo xét\". 试 = 讠 (lời nói) + 式 shì chỉ âm → thử. 考试 = khảo thí = thi."},{"char":"词","pinyin":"cí","hanviet":"Từ","chars":["词"],"story":"词 là chữ hình thanh: bộ Ngôn 讠 (lời nói) chỉ nghĩa, 司 sī chỉ âm → đơn vị của lời nói → \"từ\": 生词."},{"char":"本子","pinyin":"běnzi","hanviet":"Bản tử","chars":["本","子"],"story":"本 = 木 (cây) + một vạch ngang đánh dấu chỗ gốc → \"gốc\", rồi chỉ quyển sách (一本书). 子 là hậu tố, đọc nhẹ. 本子 = quyển vở."},{"char":"错","pinyin":"cuò","hanviet":"Thác","chars":["错"],"story":"错 = bộ Kim 钅 (kim loại) chỉ nghĩa + 昔 xī chỉ âm. Nghĩa gốc là khảm vàng đan xen → \"lẫn lộn\", rồi thành \"sai\": 做错, 写错."},{"char":"题","pinyin":"tí","hanviet":"Đề","chars":["题"],"story":"题 = 是 shì chỉ âm + 页 (cái đầu) → nghĩa gốc là \"trán\", phần đầu → đầu đề, đề bài, câu hỏi: 做题."},{"char":"还是","pinyin":"háishi","hanviet":"Hoàn thị","chars":["还","是"],"story":"还 = 辶 (bước đi) + 不 → còn, vẫn. 是 = là. Trong câu hỏi, 还是 = \"hay là\": 你喝茶还是喝咖啡？ Khác 还是……吧 bài 2 (đề nghị: hay là… đi)."},{"char":"考","pinyin":"kǎo","hanviet":"Khảo","chars":["考"],"story":"考 vẽ người già lưng còng chống gậy (cùng họ với 老). Nghĩa \"già\" nhường cho 老, còn 考 mượn làm \"thi, kiểm tra\": 考得很好."},{"char":"快要","pinyin":"kuàiyào","hanviet":"Khoái yếu","chars":["快","要"],"story":"快 = nhanh, mau (bài 5). 要 = sẽ, sắp. 快要 = sắp sửa — luôn đi với 了 cuối câu: 快要开学了."},{"char":"笑","pinyin":"xiào","hanviet":"Tiếu","chars":["笑"],"story":"笑 = bộ Trúc ⺮ (tre) + 夭 (người nghiêng đầu): người cười ngả nghiêng như ngọn tre trước gió → \"cười\"."}],"grammar":[{"title":"Câu vị ngữ chủ-vị (主谓谓语句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ lớn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>小主语</b><small>chủ ngữ nhỏ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>谓语</b><small>vị ngữ</small></span></div>","summary":"<p class=\"gr-lead\">弟弟 + 手很小</p><ul><li>Chủ ngữ nhỏ thường là <b>một phần</b> của chủ ngữ lớn: <span class=\"zh\">他个子很高</span> · <span class=\"zh\">刘明工作很忙</span> — giống \"Anh ấy dáng cao\".</li><li>Tân ngữ đưa lên đầu câu làm <b>chủ đề</b>: <span class=\"zh\">我的书包你看见了吗？</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">弟弟</span> + [<span class=\"zh\">手很小</span>]　·　<span class=\"zh\">这件事</span> + [<span class=\"zh\">他知道</span>]</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">很</span> đứng trước tính từ, sau chủ ngữ nhỏ: ✗ <span class=\"zh\">他很个子高</span> → ✓ <span class=\"zh\">他个子很高</span>.","examples":[{"zh":"我的书包你看见了吗？","py":"Wǒ de shūbāo nǐ kànjiànle ma?","vi":"Cặp của con bố có thấy không?"},{"zh":"弟弟手很小。","py":"Dìdi shǒu hěn xiǎo.","vi":"Em trai tay rất nhỏ."},{"zh":"这件事他知道。","py":"Zhè jiàn shì tā zhīdào.","vi":"Chuyện này anh ấy biết."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你知道哪个电影好看吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">这个电影____，很好看。</span></span></span><span class=\"qz-hint\">Bạn có biết phim nào hay không? — Phim này mình xem rồi, hay lắm.</span>","answer":["我看过","我看过了"],"explain":"这个电影我看过，很好看。 (Zhège diànyǐng wǒ kànguo, hěn hǎokàn.)"}]},{"title":"Câu hỏi lựa chọn (是) A 还是 B？","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(是)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>lựa chọn 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还是</b><small>hay (là)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>B</b><small>lựa chọn 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b></span></div>","summary":"<p class=\"gr-lead\">(是) A 还是 B？</p><ul><li><span class=\"zh\">还是</span> nối các lựa chọn trong <b>câu hỏi</b> = \"hay (là)\". Khác <span class=\"zh\">还是……吧</span> (bài 2) = \"hay là… đi\" để <b>đề nghị</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> Nhiều lựa chọn: <span class=\"zh\">你更喜欢打篮球、踢足球还是游泳？</span></p>","note":"<b>Lưu ý:</b> Câu hỏi lựa chọn <b>không</b> thêm <span class=\"zh\">吗</span>: ✗ <span class=\"zh\">你喝茶还是喝咖啡吗？</span>","examples":[{"zh":"妈妈，是您准备考试还是我准备考试？","py":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","vi":"Mẹ ơi, mẹ ôn thi hay con ôn thi ạ?"},{"zh":"你更喜欢打篮球、踢足球还是游泳？","py":"Nǐ gèng xǐhuan dǎ lánqiú, tī zúqiú háishi yóuyǒng?","vi":"Bạn thích chơi bóng rổ, đá bóng hay bơi hơn?"},{"zh":"我们什么时候去看电影？今天还是明天？","py":"Wǒmen shénme shíhou qù kàn diànyǐng? Jīntiān háishi míngtiān?","vi":"Khi nào mình đi xem phim? Hôm nay hay ngày mai?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你吃____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">饺子，我觉得饺子比包子更好吃。</span></span></span><span class=\"qz-hint\">Bạn ăn sủi cảo hay bánh bao? — Sủi cảo, mình thấy sủi cảo ngon hơn bánh bao.</span>","answer":["饺子还是包子","饺子还是吃包子"],"explain":"你吃饺子还是包子？ (Nǐ chī jiǎozi háishi bāozi?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你想____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">打车吧，坐公交车没有打车快。</span></span></span><span class=\"qz-hint\">Bạn muốn đi xe buýt hay bắt taxi? — Bắt taxi đi, xe buýt không nhanh bằng taxi.</span>","answer":["坐公交车还是打车","坐公交车去还是打车去"],"explain":"你想坐公交车还是打车？ (Nǐ xiǎng zuò gōngjiāochē háishi dǎchē?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你喝____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">奶茶吧，我觉得奶茶比茶和咖啡好喝。</span></span></span><span class=\"qz-hint\">Bạn uống trà, cà phê hay trà sữa? — Trà sữa đi, mình thấy trà sữa ngon hơn trà và cà phê.</span>","answer":["茶、咖啡还是奶茶","茶咖啡还是奶茶"],"explain":"你喝茶、咖啡还是奶茶？ (Nǐ hē chá, kāfēi háishi nǎichá?)"}]},{"title":"Cấu trúc cố định 要 / 快 / 快要 / 就要……了","formula":"<div class=\"fx-lbl\">快 / 快要</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>快 / 快要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词 / 形容词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">饭菜快要做好了。</div><div class=\"fx-lbl\">要</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">要下雨了。</div><div class=\"fx-lbl\">Có thời gian</div><div class=\"fx-row\"><span class=\"fx-p\"><b>时间</b><small>下星期、明天…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">我们下星期就要考试了。</div>","summary":"<p class=\"gr-lead\">Sắp… rồi</p><ul><li>Cả bốn dạng đều = \"<b>sắp</b> … rồi\"; cuối câu <b>bắt buộc</b> có <span class=\"zh\">了</span>.</li></ul>","note":"<b>Lưu ý:</b> Có <b>trạng ngữ thời gian</b> → dùng <span class=\"zh\">就要</span>: ✗ <span class=\"zh\">明天快要考试了</span> → ✓ <span class=\"zh\">明天就要考试了</span>.","examples":[{"zh":"饭菜快要做好了。","py":"Fàncài kuàiyào zuòhǎo le.","vi":"Cơm nước sắp nấu xong rồi."},{"zh":"火车快开了。","py":"Huǒchē kuài kāi le.","vi":"Tàu sắp chạy rồi."},{"zh":"我们下星期就要考试了。","py":"Wǒmen xià xīngqī jiù yào kǎoshì le.","vi":"Tuần sau chúng mình thi rồi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____，你别出去吃了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">那不好，小王还在饭馆等我呢。</span></span></span><span class=\"qz-hint\">Cơm sắp nấu xong rồi, con đừng ra ngoài ăn nữa. — Thế không được, Tiểu Vương còn đang đợi con ở quán.</span>","answer":["饭菜快要做好了","饭菜快做好了","饭菜就要做好了","饭快要做好了"],"explain":"饭菜快要做好了，你别出去吃了。 (Fàncài kuàiyào zuòhǎo le, nǐ bié chūqù chī le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____，陈天中怎么还没来？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">他说今天不舒服，不来上课了。</span></span></span><span class=\"qz-hint\">Sắp vào học rồi, sao Thiên Trung vẫn chưa đến? — Cậu ấy nói hôm nay không khoẻ, không đến học.</span>","answer":["快要上课了","快上课了","就要上课了","要上课了"],"explain":"快要上课了，陈天中怎么还没来？ (Kuàiyào shàngkè le, Chén Tiānzhōng zěnme hái méi lái?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">儿子10号过生日，今天都7号了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，____。</span></span></span><span class=\"qz-hint\">Con trai sinh nhật ngày 10, hôm nay đã mùng 7 rồi. — Ừ, còn ba ngày nữa là sinh nhật rồi.</span>","answer":["还有三天就要过生日了","还有三天就过生日了","还有三天就要过生日"],"explain":"是啊，还有三天就要过生日了。 (Shì a, hái yǒu sān tiān jiù yào guò shēngrì le.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在房间","titleVi":"Trong phòng — chuẩn bị khai giảng","lines":[{"speaker":"明","name":"Lưu Minh","zh":"小明，你们明天开学，你准备好了吗？","py":"Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","vi":"Tiểu Minh, mai các con khai giảng, con chuẩn bị xong chưa?"},{"speaker":"弟","name":"Tiểu Minh","zh":"明天就开学啊？爸爸，我的书包你看见了吗？","py":"Míngtiān jiù kāixué a? Bàba, wǒ de shūbāo nǐ kànjiànle ma?","vi":"Mai khai giảng rồi ạ? Bố ơi, bố có thấy cặp của con không?"},{"speaker":"明","name":"Lưu Minh","zh":"书包在门后面。","py":"Shūbāo zài mén hòumiàn.","vi":"Cặp ở sau cửa."},{"speaker":"弟","name":"Tiểu Minh","zh":"书在哪儿呢？笔呢？","py":"Shū zài nǎr ne? Bǐ ne?","vi":"Sách ở đâu nhỉ? Còn bút?"},{"speaker":"明","name":"Lưu Minh","zh":"书在床上，笔在桌子上。","py":"Shū zài chuáng shang, bǐ zài zhuōzi shang.","vi":"Sách ở trên giường, bút ở trên bàn."},{"speaker":"弟","name":"Tiểu Minh","zh":"太好了！现在都准备好了。","py":"Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le.","vi":"Tuyệt quá! Giờ chuẩn bị xong hết rồi."},{"speaker":"明","name":"Lưu Minh","zh":"这次爸爸帮你，下次你自己准备，好不好？","py":"Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","vi":"Lần này bố giúp con, lần sau con tự chuẩn bị nhé, được không?"},{"speaker":"弟","name":"Tiểu Minh","zh":"好！","py":"Hǎo!","vi":"Vâng ạ!"}]},{"titleZh":"课文二 · 在房间","titleVi":"Trong phòng — Tiểu Tuyết ôn thi","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"小雪，你在做什么呢？","py":"Xiǎoxuě, nǐ zài zuò shénme ne?","vi":"Tiểu Tuyết, con đang làm gì đấy?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"明天考试，我在看书呢。","py":"Míngtiān kǎoshì, wǒ zài kàn shū ne.","vi":"Mai thi, con đang đọc sách ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"这些词要好好看看。","py":"Zhèxiē cí yào hǎohǎo kànkan.","vi":"Những từ này phải xem kỹ vào."},{"speaker":"小","name":"Tiểu Tuyết","zh":"我看过了，意思也都懂了。","py":"Wǒ kànguo le, yìsi yě dōu dǒng le.","vi":"Con xem rồi, nghĩa cũng hiểu hết rồi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你的本子呢？本子上做错的题也要看一看。","py":"Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào kàn yi kàn.","vi":"Vở của con đâu? Những câu làm sai trong vở cũng phải xem lại."},{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，是您准备考试还是我准备考试？","py":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","vi":"Mẹ ơi, mẹ ôn thi hay con ôn thi ạ?"}]},{"titleZh":"课文三 · 在客厅","titleVi":"Phòng khách — thi xong về nhà","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，我回来了！","py":"Māma, wǒ huílái le!","vi":"Mẹ ơi, con về rồi!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我买了奶茶，就在桌子上，自己去拿吧。","py":"Wǒ mǎile nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba.","vi":"Mẹ mua trà sữa rồi, ở ngay trên bàn, con tự ra lấy nhé."},{"speaker":"小","name":"Tiểu Tuyết","zh":"谢谢妈妈！","py":"Xièxie māma!","vi":"Con cảm ơn mẹ!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"今天考试考得怎么样？","py":"Jīntiān kǎoshì kǎo de zěnmeyàng?","vi":"Hôm nay thi thế nào?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"我觉得比上次好。","py":"Wǒ juéde bǐ shàng cì hǎo.","vi":"Con thấy tốt hơn lần trước."},{"speaker":"雪","name":"Nhất Tuyết","zh":"真不错！饭菜快要做好了，你叫弟弟一起去洗手吧。","py":"Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba.","vi":"Giỏi lắm! Cơm sắp nấu xong rồi, con gọi em cùng đi rửa tay đi."},{"gap":true,"zh":"……"},{"speaker":"弟","name":"Tiểu Minh","zh":"妈妈，我是第一名，姐姐还没洗完呢。","py":"Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne.","vi":"Mẹ ơi, con về nhất, chị vẫn chưa rửa xong."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你洗得真快啊！","py":"Nǐ xǐ de zhēn kuài a!","vi":"Con rửa nhanh thật đấy!"}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Tiểu Tuyết","para":true,"speaker":"小","lines":[{"zh":"快要开学了，爸爸帮弟弟准备书包、本子和笔。","py":"Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ.","vi":"Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp, vở và bút."},{"zh":"我就要考试了，妈妈让我看书、看做错的题。","py":"Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí.","vi":"Mình sắp thi rồi, mẹ bảo mình đọc sách, xem lại những câu làm sai."},{"zh":"我们上学，爸爸、妈妈比我们还忙。","py":"Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng.","vi":"Bọn mình đi học mà bố mẹ còn bận hơn cả bọn mình."},{"zh":"我问他们：\"是我和弟弟上学还是你们上学？\"","py":"Wǒ wèn tāmen: \"Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?\"","vi":"Mình hỏi bố mẹ: \"Là con với em đi học hay bố mẹ đi học ạ?\""},{"zh":"我问完，他们都笑了。","py":"Wǒ wènwán, tāmen dōu xiào le.","vi":"Hỏi xong, bố mẹ đều bật cười."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hỏi · Đáp · Học thế nào?","q":{"zh":"两人一组，互相问问：学会了什么？学得怎么样？有没有做错的题？","py":"Liǎng rén yì zǔ, hùxiāng wènwen: xuéhuìle shénme? Xué de zěnmeyàng? Yǒu méiyǒu zuòcuò de tí?","vi":"Theo cặp, hỏi nhau: đã học được gì? Học thế nào? Có câu nào làm sai không?"},"items":[{"lines":[{"who":"A","zh":"开学快一个月了，你学会什么了？","py":"Kāixué kuài yí ge yuè le, nǐ xuéhuì shénme le?","vi":"Khai giảng sắp được một tháng rồi, bạn học được gì rồi?"},{"who":"B","zh":"学会了60多个词，还写了20多个汉字。","py":"Xuéhuìle liùshí duō ge cí, hái xiěle èrshí duō ge Hànzì.","vi":"Học được hơn 60 từ, còn viết được hơn 20 chữ Hán."}]},{"zh":"你考试考得怎么样？—— 我觉得比上次好。","py":"Nǐ kǎoshì kǎo de zěnmeyàng? —— Wǒ juéde bǐ shàng cì hǎo.","vi":"Bạn thi thế nào? — Mình thấy tốt hơn lần trước."},{"zh":"这些题你做对了还是做错了？","py":"Zhèxiē tí nǐ zuòduìle háishi zuòcuò le?","vi":"Mấy câu này bạn làm đúng hay làm sai?"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 6–10 · Bạn thân của tôi","prep":3,"talk":2,"q":{"zh":"请你说说你的一个好朋友。","py":"Qǐng nǐ shuōshuo nǐ de yí ge hǎo péngyou.","vi":"Hãy kể về một người bạn thân của bạn."},"frame":[{"lbl":"开头","zh":"我有一个好朋友，他叫……，他个子……。","py":"Wǒ yǒu yí ge hǎo péngyou, tā jiào ……, tā gèzi …….","vi":"Mình có một người bạn thân tên là …, dáng người …","ex":{"zh":"我有一个好朋友，他叫天中，他个子很高。","py":"Wǒ yǒu yí ge hǎo péngyou, tā jiào Tiānzhōng, tā gèzi hěn gāo.","vi":"Mình có một người bạn thân tên là Thiên Trung, dáng người rất cao."}},{"lbl":"中间","zh":"他的爱好是……，他……得很……。","py":"Tā de àihào shì ……, tā …… de hěn …….","vi":"Sở thích của cậu ấy là …, cậu ấy … rất …","ex":{"zh":"他的爱好是运动，他篮球打得很好，游泳也游得很快。","py":"Tā de àihào shì yùndòng, tā lánqiú dǎ de hěn hǎo, yóuyǒng yě yóu de hěn kuài.","vi":"Sở thích của cậu ấy là thể thao, chơi bóng rổ rất giỏi, bơi cũng rất nhanh."}},{"lbl":"中间","zh":"他一有时间就……，有时候……了……个小时。","py":"Tā yì yǒu shíjiān jiù ……, yǒushíhou …… le …… ge xiǎoshí.","vi":"Hễ có thời gian là cậu ấy …, có khi … mấy tiếng liền.","ex":{"zh":"他一有时间就去运动，有时候打了三个小时篮球。","py":"Tā yì yǒu shíjiān jiù qù yùndòng, yǒushíhou dǎle sān ge xiǎoshí lánqiú.","vi":"Hễ có thời gian là cậu ấy đi tập thể thao, có khi chơi bóng rổ ba tiếng liền."}},{"lbl":"中间","zh":"他比我……，但是没有我……。","py":"Tā bǐ wǒ ……, dànshì méiyǒu wǒ …….","vi":"Cậu ấy … hơn mình, nhưng không … bằng mình.","ex":{"zh":"他比我高，但是没有我大。","py":"Tā bǐ wǒ gāo, dànshì méiyǒu wǒ dà.","vi":"Cậu ấy cao hơn mình, nhưng không lớn tuổi bằng mình."}},{"lbl":"结尾","zh":"虽然……，但是我们……，玩得很高兴。","py":"Suīrán ……, dànshì wǒmen ……, wán de hěn gāoxìng.","vi":"Tuy …, nhưng bọn mình …, chơi rất vui.","ex":{"zh":"虽然他家离我家很远，但是我们星期天一起玩，玩得很高兴。","py":"Suīrán tā jiā lí wǒ jiā hěn yuǎn, dànshì wǒmen Xīngqītiān yìqǐ wán, wán de hěn gāoxìng.","vi":"Tuy nhà cậu ấy xa nhà mình, nhưng Chủ nhật bọn mình chơi cùng nhau, rất vui."}}]}]}},{"id":"k2v3-b11","courseId":"k2v3","order":11,"title":"Tôi thích ăn món Trung Quốc nhất","titleZh":"我最喜欢吃中国菜","titlePy":"wǒ zuì xǐhuan chī Zhōngguó cài","vocab":[{"stt":1,"hanzi":"头","pinyin":"tóu","hanviet":"Đầu","pos":"Danh từ","meaning":"đầu","comps":"头疼 (đau đầu), 我的头 (đầu tôi)","example":{"zh":"我头有点儿疼。","py":"Wǒ tóu yǒudiǎnr téng.","vi":"Mình hơi đau đầu."}},{"stt":2,"hanzi":"疼","pinyin":"téng","hanviet":"Đông","pos":"Tính từ","meaning":"đau","comps":"头疼 (đau đầu), 很疼 (rất đau)","example":{"zh":"你哪儿疼？","py":"Nǐ nǎr téng?","vi":"Bạn đau ở đâu?"}},{"stt":3,"hanzi":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","pos":"Phó từ","meaning":"thường xuyên, hay","comps":"经常去 (hay đi), 经常头疼 (hay đau đầu)","example":{"zh":"我经常跟朋友去跑步。","py":"Wǒ jīngcháng gēn péngyou qù pǎobù.","vi":"Mình hay đi chạy bộ với bạn."}},{"stt":4,"hanzi":"动","pinyin":"dòng","hanviet":"Động","pos":"Động từ","meaning":"cử động, động đậy","comps":"别动 (đừng động đậy), 不能动 (không cử động được)","example":{"zh":"你别动，我看看。","py":"Nǐ bié dòng, wǒ kànkan.","vi":"Bạn đừng cử động, để mình xem."}},{"stt":5,"hanzi":"着","pinyin":"zhe","hanviet":"Trứ","pos":"Trợ từ","meaning":"(sau ĐT) đang …, chỉ trạng thái duy trì","comps":"坐着 (đang ngồi), 开着 (đang mở)","example":{"zh":"门开着呢。","py":"Mén kāizhe ne.","vi":"Cửa đang mở đấy."}},{"stt":6,"hanzi":"路上","pinyin":"lùshang","hanviet":"Lộ thượng","pos":"Danh từ","meaning":"trên đường","comps":"在路上 (đang trên đường), 路上车多 (đường đông xe)","example":{"zh":"我在路上，十分钟就到。","py":"Wǒ zài lùshang, shí fēnzhōng jiù dào.","vi":"Mình đang trên đường, mười phút nữa là tới."}},{"stt":7,"hanzi":"慢","pinyin":"màn","hanviet":"Mạn","pos":"Tính từ","meaning":"chậm","comps":"慢一点儿 (chậm một chút), 开得很慢 (lái rất chậm)","example":{"zh":"请你说慢一点儿。","py":"Qǐng nǐ shuō màn yìdiǎnr.","vi":"Bạn nói chậm một chút nhé."}},{"stt":8,"hanzi":"进","pinyin":"jìn","hanviet":"Tiến","pos":"Động từ","meaning":"vào","comps":"请进 (mời vào), 进教室 (vào lớp)","example":{"zh":"快请进！","py":"Kuài qǐng jìn!","vi":"Mời vào đi!"}},{"stt":9,"hanzi":"药","pinyin":"yào","hanviet":"Dược","pos":"Danh từ","meaning":"thuốc","comps":"吃药 (uống thuốc), 买药 (mua thuốc)","example":{"zh":"你吃药了吗？","py":"Nǐ chī yào le ma?","vi":"Bạn uống thuốc chưa?"}},{"stt":10,"hanzi":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","pos":"Danh từ","meaning":"cơ thể, sức khoẻ","comps":"身体很好 (sức khoẻ tốt), 身体不舒服 (người không khoẻ)","example":{"zh":"我爷爷身体很好。","py":"Wǒ yéye shēntǐ hěn hǎo.","vi":"Ông nội mình sức khoẻ rất tốt."}},{"stt":11,"hanzi":"时","pinyin":"shí","hanviet":"Thời","pos":"Danh từ","meaning":"lúc, khi","comps":"……时 (khi …), 吃饭时 (lúc ăn cơm)","example":{"zh":"吃饭时别看手机。","py":"Chī fàn shí bié kàn shǒujī.","vi":"Lúc ăn cơm đừng xem điện thoại."}},{"stt":12,"hanzi":"最","pinyin":"zuì","hanviet":"Tối","pos":"Phó từ","meaning":"nhất","comps":"最好 (tốt nhất), 最喜欢 (thích nhất)","example":{"zh":"我最喜欢红色。","py":"Wǒ zuì xǐhuan hóngsè.","vi":"Mình thích màu đỏ nhất."}},{"stt":13,"hanzi":"药店","pinyin":"yàodiàn","hanviet":"Dược điếm","pos":"Danh từ","meaning":"hiệu thuốc","comps":"去药店 (đi hiệu thuốc), 药店买药 (mua thuốc ở hiệu thuốc)","example":{"zh":"学校旁边有一个药店。","py":"Xuéxiào pángbiān yǒu yí ge yàodiàn.","vi":"Cạnh trường có một hiệu thuốc."}}],"hanzi":[{"char":"头","pinyin":"tóu","hanviet":"Đầu","chars":["头"],"story":"Phồn thể 頭 = 豆 dòu chỉ âm + 页 (cái đầu) → \"đầu\". Giản thể 头 viết thảo lại, chỉ giữ dáng người với hai chấm."},{"char":"疼","pinyin":"téng","hanviet":"Đông","chars":["疼"],"story":"疼 = bộ Nạch 疒 (người nằm giường bệnh) + 冬 dōng chỉ âm. Mẹo: mùa đông 冬 lạnh, nằm giường bệnh 疒 → đau nhức."},{"char":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","chars":["经","常"],"story":"经 = 纟 (sợi tơ) + 巠: sợi dọc căng trên khung cửi, luôn ở đó → \"kinh\" (thường, đi qua). 常 = 尚 chỉ âm + 巾 (vải) → thường. 经常 = thường xuyên."},{"char":"动","pinyin":"dòng","hanviet":"Động","chars":["动"],"story":"动 = 云 + 力 (sức). Phồn thể 動 = 重 (nặng) + 力: dùng sức đẩy vật nặng → chuyển động, cử động."},{"char":"着","pinyin":"zhe","hanviet":"Trứ","chars":["着"],"story":"着 là dạng giản của 著: trên là 羊 (bỏ nét dưới), dưới là 目 (mắt). Mẹo: mắt 目 dán chặt vào chú cừu 羊 → bám giữ, duy trì → 坐着, 开着."},{"char":"路上","pinyin":"lùshang","hanviet":"Lộ thượng","chars":["路","上"],"story":"路 = 足 (chân) + 各 gè (ai nấy) → con đường ai cũng đi. 上 = trên. 路上 = trên đường."},{"char":"慢","pinyin":"màn","hanviet":"Mạn","chars":["慢"],"story":"慢 = bộ Tâm 忄 (lòng) + 曼 màn chỉ âm → lòng thong thả, chẳng vội → chậm."},{"char":"进","pinyin":"jìn","hanviet":"Tiến","chars":["进"],"story":"进 = 辶 (bước đi) + 井 jǐng chỉ âm. Phồn thể 進 = 辶 + 隹 (chim): chim chỉ bay về phía trước → tiến, vào."},{"char":"药","pinyin":"yào","hanviet":"Dược","chars":["药"],"story":"药 = bộ Thảo 艹 (cỏ cây) + 约 yuē chỉ âm → thuốc làm từ cây cỏ (thuốc Bắc)."},{"char":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","chars":["身","体"],"story":"身 vẽ người bụng to nhìn nghiêng → thân mình. 体 = 亻 (người) + 本 (gốc): con người lấy thân làm gốc. 身体 = thân thể, sức khoẻ."},{"char":"时","pinyin":"shí","hanviet":"Thời","chars":["时"],"story":"时 = 日 (mặt trời) + 寸 (tấc): đo bóng mặt trời theo từng tấc để biết giờ → thời gian, lúc. Đã gặp trong 小时, 时候."},{"char":"最","pinyin":"zuì","hanviet":"Tối","chars":["最"],"story":"最 = 曰 (mũ che, biến thể) + 取 (lấy): xông lên giành lấy cái đứng đầu → nhất."},{"char":"药店","pinyin":"yàodiàn","hanviet":"Dược điếm","chars":["药","店"],"story":"药 = thuốc. 店 = 广 (mái nhà) + 占 zhàn chỉ âm → cửa hàng (đã gặp 酒店 bài 5). 药店 = hiệu thuốc."}],"grammar":[{"title":"Trợ từ động thái 着 (1)","formula":"<div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(呢)</b></span></div><div class=\"fx-ex zh\">那你在这儿坐着。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没(有)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span></div><div class=\"fx-ex zh\">教室的门没开着。</div>","summary":"<p class=\"gr-lead\">Động tác / trạng thái đang duy trì</p><ul><li><span class=\"zh\">着</span> sau động từ = động tác / trạng thái <b>đang duy trì</b>: <span class=\"zh\">坐着</span> (đang ngồi), <span class=\"zh\">开着</span> (đang mở).</li></ul>","note":"<b>Lưu ý:</b> Phủ định dùng <span class=\"zh\">没(有)</span>, không dùng <span class=\"zh\">不</span>: ✗ <span class=\"zh\">门不开着</span> → ✓ <span class=\"zh\">门没开着</span>.","examples":[{"zh":"那你在这儿坐着。","py":"Nà nǐ zài zhèr zuòzhe.","vi":"Vậy em cứ ngồi đây nhé."},{"zh":"教室的门开着。","py":"Jiàoshì de mén kāizhe.","vi":"Cửa lớp học đang mở."},{"zh":"教室的门没开着。","py":"Jiàoshì de mén méi kāizhe.","vi":"Cửa lớp học không mở."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你看见我的手机了吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">别找了，我____呢。</span></span></span><span class=\"qz-hint\">Bạn có thấy điện thoại của mình không? — Đừng tìm nữa, mình đang cầm đây.</span>","answer":["拿着"],"explain":"别找了，我拿着呢。 (Bié zhǎo le, wǒ názhe ne.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">房间的门____，但是刘爷爷没在里边。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">他出去了吧？我给他打个电话。</span></span></span><span class=\"qz-hint\">Cửa phòng đang mở, nhưng ông Lưu không ở trong. — Chắc ông ra ngoài rồi? Để mình gọi điện cho ông.</span>","answer":["开着"],"explain":"房间的门开着，但是刘爷爷没在里边。 (Fángjiān de mén kāizhe, dànshì Liú yéye méi zài lǐbian.)"}]},{"title":"Trợ từ động thái 着 (2)","formula":"<div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div><div class=\"fx-ex zh\">她穿着白色的裤子。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b></span></div><div class=\"fx-ex zh\">陈天中没拿着咖啡。</div>","summary":"<p class=\"gr-lead\">ĐT + 着 + tân ngữ · câu hỏi</p><div class=\"gr-sub\"><h4><span class=\"zh\">动态助词 \"着\" (2)</span> · Câu hỏi</h4><p>3 cách hỏi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Thêm 吗</div><div class=\"fx-row\"><span class=\"fx-p\"><b>……着……</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b></span></div><div class=\"fx-ex zh\">教室的门开着吗？</div><div class=\"fx-lbl\">Thêm 没有</div><div class=\"fx-row\"><span class=\"fx-p\"><b>……着……</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b></span></div><div class=\"fx-ex zh\">白家月坐着没有？</div><div class=\"fx-lbl\">ĐT 没 ĐT 着</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b></span></div><div class=\"fx-ex zh\">她拿没拿着手机？</div></div><p class=\"gr-key\">Trả lời phủ định: <span class=\"zh\">没有。</span> / <span class=\"zh\">没开着。</span></p></div>","note":"<b>Lưu ý:</b> Tân ngữ đứng <b>sau</b> <span class=\"zh\">着</span>: ✗ <span class=\"zh\">她穿白色的裤子着</span> → ✓ <span class=\"zh\">她穿着白色的裤子</span>.","examples":[{"zh":"现在路上车多，还下着雪，我开慢一点儿。","py":"Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr.","vi":"Giờ đường đông xe, lại đang có tuyết, cô lái chậm một chút."},{"zh":"她穿着白色的裤子。","py":"Tā chuānzhe báisè de kùzi.","vi":"Cô ấy đang mặc quần màu trắng."},{"zh":"陈天中没拿着咖啡。","py":"Chén Tiānzhōng méi názhe kāfēi.","vi":"Thiên Trung không cầm cà phê."},{"zh":"教室的门开着吗？","py":"Jiàoshì de mén kāizhe ma?","vi":"Cửa lớp học có đang mở không?"},{"zh":"白家月坐着没有？","py":"Bái Jiāyuè zuòzhe méiyǒu?","vi":"Gia Nguyệt có đang ngồi không?"},{"zh":"她拿没拿着手机？","py":"Tā ná méi názhe shǒujī?","vi":"Cô ấy có cầm điện thoại không?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">外边____，你别出去跑步了。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好吧，那就在家运动运动。</span></span></span><span class=\"qz-hint\">Bên ngoài đang mưa, bạn đừng ra ngoài chạy bộ nữa. — Thôi được, vậy ở nhà vận động chút vậy.</span>","answer":["下着雨呢","下着雨","正下着雨呢","正在下雨呢"],"explain":"外边下着雨呢，你别出去跑步了。 (Wàibian xiàzhe yǔ ne, nǐ bié chūqù pǎobù le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小明，电视____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没有，我们都没看电视。</span></span></span><span class=\"qz-hint\">Tiểu Minh, ti vi có đang bật không? — Không ạ, bọn con đều không xem ti vi.</span>","answer":["开着没有","开着吗","是不是开着"],"explain":"小明，电视开着没有？ (Xiǎomíng, diànshì kāizhe méiyǒu?)"}]},{"title":"Phó từ mức độ 最","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(范围)</b><small>phạm vi so sánh</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>最</b><small>nhất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 心理动词</b><small>高、好、喜欢、想…</small></span></div>","summary":"<p class=\"gr-lead\">最 + Tính từ / ĐT tâm lý</p><ul><li>Phạm vi so sánh thường đặt ở đầu câu: <span class=\"zh\">在我们家，</span><span class=\"zh\">爸爸最高</span>.</li><li>Đi với bổ ngữ trạng thái: <span class=\"zh\">谁说中文说得最好？</span></li></ul>","note":"<b>Lưu ý:</b> <span class=\"zh\">最</span> đứng <b>trước</b> tính từ, không đặt cuối như tiếng Việt: ✗ <span class=\"zh\">爸爸高最</span> → ✓ <span class=\"zh\">爸爸最高</span>.","examples":[{"zh":"你最喜欢吃中国菜。","py":"Nǐ zuì xǐhuan chī Zhōngguó cài.","vi":"Em thích ăn món Trung Quốc nhất."},{"zh":"在我们家，爸爸最高。","py":"Zài wǒmen jiā, bàba zuì gāo.","vi":"Nhà mình thì bố cao nhất."},{"zh":"你们班谁说中文说得最好？","py":"Nǐmen bān shéi shuō Zhōngwén shuō de zuì hǎo?","vi":"Lớp các bạn ai nói tiếng Trung giỏi nhất?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你来过这家饭馆吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">来过，这里的鱼做得____。</span></span></span><span class=\"qz-hint\">Bạn đến quán này bao giờ chưa? — Đến rồi, cá ở đây làm ngon nhất.</span>","answer":["最好吃","最好"],"explain":"来过，这里的鱼做得最好吃。 (Láiguo, zhèlǐ de yú zuò de zuì hǎochī.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp học — Gia Nguyệt bị đau đầu","lines":[{"speaker":"飞","name":"Cô Nhất Phi","zh":"家月，都下课了，你怎么还不回家？","py":"Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?","vi":"Gia Nguyệt, tan học rồi, sao em vẫn chưa về nhà?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我头疼，不太舒服。","py":"Wǒ tóu téng, bú tài shūfu.","vi":"Em đau đầu, không được khoẻ lắm."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"你这几天经常头疼，去医院看看吧。","py":"Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","vi":"Mấy hôm nay em hay đau đầu, đi bệnh viện khám xem."},{"speaker":"月","name":"Gia Nguyệt","zh":"我想休息一下，现在不能动，一动就疼。","py":"Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng.","vi":"Em muốn nghỉ một chút, giờ không cử động được, cử động là đau."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"那你在这儿坐着，我去开车，一会儿送你去医院。","py":"Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yíhuìr sòng nǐ qù yīyuàn.","vi":"Vậy em ngồi đây nhé, cô đi lấy xe, lát nữa đưa em đi bệnh viện."},{"speaker":"月","name":"Gia Nguyệt","zh":"谢谢王老师。","py":"Xièxie Wáng lǎoshī.","vi":"Em cảm ơn cô Vương."}]},{"titleZh":"课文二 · 在王一飞车里","titleVi":"Trong xe cô Nhất Phi — Lý Văn gọi đến","lines":[{"speaker":"飞","name":"Cô Nhất Phi","zh":"现在路上车多，还下着雪，我开慢一点儿。","py":"Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr.","vi":"Giờ trên đường đông xe, lại đang có tuyết, cô lái chậm một chút."},{"speaker":"月","name":"Gia Nguyệt","zh":"没问题，现在头没那么疼了。","py":"Méi wèntí, xiànzài tóu méi nàme téng le.","vi":"Không sao ạ, giờ đầu em không đau như lúc nãy nữa."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"好。李文来电话了，你帮我接一下。","py":"Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià.","vi":"Được. Lý Văn gọi đến, em nghe giúp cô nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"喂，李文，王老师开着车呢，你找她有事吗？","py":"Wèi, Lǐ Wén, Wáng lǎoshī kāizhe chē ne, nǐ zhǎo tā yǒu shì ma?","vi":"A lô, Lý Văn, cô Vương đang lái xe, cậu tìm cô có việc gì không?"},{"speaker":"文","name":"Lý Văn","zh":"没什么事。今天雪这么大，你们开车去哪儿啊？","py":"Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?","vi":"Không có việc gì đâu. Hôm nay tuyết to thế, các cậu lái xe đi đâu thế?"},{"speaker":"月","name":"Gia Nguyệt","zh":"去医院，我头有点儿疼。","py":"Qù yīyuàn, wǒ tóu yǒudiǎnr téng.","vi":"Đi bệnh viện, mình hơi đau đầu."},{"speaker":"文","name":"Lý Văn","zh":"那我一会儿去看看你。","py":"Nà wǒ yíhuìr qù kànkan nǐ.","vi":"Vậy lát nữa mình đến thăm cậu."}]},{"titleZh":"课文三 · 在房间","titleVi":"Trong phòng — Lý Văn đến thăm","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"李文，快请进！","py":"Lǐ Wén, kuài qǐng jìn!","vi":"Lý Văn, mời vào đi!"},{"speaker":"文","name":"Lý Văn","zh":"家月，你怎么样了？头还疼吗？","py":"Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?","vi":"Gia Nguyệt, cậu thấy sao rồi? Đầu còn đau không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"不那么疼了。医生开了一些药，吃完就好多了。","py":"Bú nàme téng le. Yīshēng kāile yìxiē yào, chīwán jiù hǎoduō le.","vi":"Không đau lắm nữa. Bác sĩ kê ít thuốc, uống xong thấy đỡ nhiều rồi."},{"speaker":"文","name":"Lý Văn","zh":"那就好！","py":"Nà jiù hǎo!","vi":"Thế thì tốt quá!"},{"speaker":"飞","name":"Cô Nhất Phi","zh":"家月，你想不想吃点儿东西？","py":"Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?","vi":"Gia Nguyệt, em có muốn ăn chút gì không?"},{"speaker":"文","name":"Lý Văn","zh":"吃点儿吧，身体不舒服时更要好好吃饭。","py":"Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohǎo chī fàn.","vi":"Ăn chút đi, lúc người không khoẻ càng phải ăn uống đầy đủ."},{"speaker":"月","name":"Gia Nguyệt","zh":"吃点儿什么呢？","py":"Chī diǎnr shénme ne?","vi":"Ăn gì bây giờ nhỉ?"},{"speaker":"飞","name":"Cô Nhất Phi","zh":"你最喜欢吃中国菜，我做几个中国菜吧。","py":"Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba.","vi":"Em thích món Trung Quốc nhất, cô nấu vài món Trung Quốc nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"好的，谢谢王老师。","py":"Hǎo de, xièxie Wáng lǎoshī.","vi":"Vâng ạ, em cảm ơn cô Vương."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Gia Nguyệt","para":true,"speaker":"月","lines":[{"zh":"我这几天经常头疼，从药店买了点儿药，没去医院。","py":"Wǒ zhè jǐ tiān jīngcháng tóu téng, cóng yàodiàn mǎile diǎnr yào, méi qù yīyuàn.","vi":"Mấy hôm nay mình hay đau đầu, mua ít thuốc ở hiệu thuốc, không đi bệnh viện."},{"zh":"今天下课后，王老师看我不舒服，就送我去医院了。","py":"Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le.","vi":"Hôm nay tan học, cô Vương thấy mình không khoẻ nên đưa mình đi bệnh viện."},{"zh":"从医院回来，李文也来看我了。","py":"Cóng yīyuàn huílái, Lǐ Wén yě lái kàn wǒ le.","vi":"Từ bệnh viện về, Lý Văn cũng đến thăm mình."},{"zh":"现在他们都回去了，我也要睡觉了。","py":"Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le.","vi":"Giờ mọi người về cả rồi, mình cũng sắp đi ngủ."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Theo cặp · Bác sĩ & bệnh nhân","q":{"zh":"两人一组：一人是医生，一人是病人。病人头疼，来医院看病。","py":"Liǎng rén yì zǔ: yì rén shì yīshēng, yì rén shì bìngrén. Bìngrén tóu téng, lái yīyuàn kànbìng.","vi":"Theo cặp: 1 bác sĩ, 1 bệnh nhân. Bệnh nhân đau đầu, đến bệnh viện khám."},"items":[{"lines":[{"who":"A","zh":"你哪里不舒服？","py":"Nǐ nǎlǐ bù shūfu?","vi":"Bạn thấy khó chịu ở đâu?"},{"who":"B","zh":"头疼，不能动，一动就疼。","py":"Tóu téng, bù néng dòng, yí dòng jiù téng.","vi":"Đau đầu, không cử động được, cử động là đau."}]},{"zh":"什么时候开始疼的？—— 昨天晚上开始的。","py":"Shénme shíhou kāishǐ téng de? —— Zuótiān wǎnshang kāishǐ de.","vi":"Bắt đầu đau từ lúc nào? — Từ tối qua."},{"zh":"你吃过药没有？—— 吃过，是从药店买的。","py":"Nǐ chīguo yào méiyǒu? —— Chīguo, shì cóng yàodiàn mǎi de.","vi":"Bạn uống thuốc chưa? — Uống rồi, mua ở hiệu thuốc."}]}],"speak":[]}},{"id":"k2v3-b12","courseId":"k2v3","order":12,"title":"Ở đây lạnh hơn Bắc Kinh nhiều","titleZh":"这里比北京冷多了","titlePy":"zhèlǐ bǐ Běijīng lěngduō le","vocab":[{"stt":1,"hanzi":"事情","pinyin":"shìqing","hanviet":"Sự tình","pos":"Danh từ","meaning":"sự việc, chuyện","comps":"有事情 (có việc), 什么事情 (chuyện gì)","example":{"zh":"你找我有什么事情？","py":"Nǐ zhǎo wǒ yǒu shénme shìqing?","vi":"Bạn tìm mình có chuyện gì thế?"}},{"stt":2,"hanzi":"晴","pinyin":"qíng","hanviet":"Tình","pos":"Tính từ","meaning":"nắng, quang đãng","comps":"晴天 (ngày nắng), 天晴了 (trời tạnh nắng rồi)","example":{"zh":"今天是晴天。","py":"Jīntiān shì qíngtiān.","vi":"Hôm nay trời nắng."}},{"stt":3,"hanzi":"正","pinyin":"zhèng","hanviet":"Chính","pos":"Phó từ","meaning":"đang (động tác đang diễn ra)","comps":"正下雪 (đang có tuyết), 正……呢 (đang … đấy)","example":{"zh":"我正吃饭呢。","py":"Wǒ zhèng chī fàn ne.","vi":"Mình đang ăn cơm đây."}},{"stt":4,"hanzi":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","pos":"Danh từ","meaning":"bên ngoài","comps":"在外面 (ở bên ngoài), 外面很冷 (bên ngoài rất lạnh)","example":{"zh":"外面下雨了。","py":"Wàimiàn xià yǔ le.","vi":"Bên ngoài mưa rồi."}},{"stt":5,"hanzi":"阴","pinyin":"yīn","hanviet":"Âm","pos":"Tính từ","meaning":"âm u, nhiều mây","comps":"阴天 (trời âm u), 天阴了 (trời u ám rồi)","example":{"zh":"今天阴天，可能要下雨。","py":"Jīntiān yīn tiān, kěnéng yào xià yǔ.","vi":"Hôm nay trời âm u, có lẽ sắp mưa."}},{"stt":6,"hanzi":"从小","pinyin":"cóngxiǎo","hanviet":"Tòng tiểu","pos":"Phó từ","meaning":"từ nhỏ","comps":"从小就喜欢 (từ nhỏ đã thích), 从小学中文 (học tiếng Trung từ nhỏ)","example":{"zh":"我从小就喜欢唱歌。","py":"Wǒ cóngxiǎo jiù xǐhuan chànggē.","vi":"Từ nhỏ mình đã thích hát."}},{"stt":7,"hanzi":"地铁","pinyin":"dìtiě","hanviet":"Địa thiết","pos":"Danh từ","meaning":"tàu điện ngầm","comps":"坐地铁 (đi tàu điện ngầm), 地铁站 (ga tàu điện ngầm)","example":{"zh":"我每天坐地铁上班。","py":"Wǒ měi tiān zuò dìtiě shàngbān.","vi":"Ngày nào mình cũng đi tàu điện ngầm đi làm."}},{"stt":8,"hanzi":"楼","pinyin":"lóu","hanviet":"Lâu","pos":"Danh từ","meaning":"toà nhà; tầng","comps":"楼下 (dưới nhà), 三楼 (tầng 3)","example":{"zh":"我家在三楼。","py":"Wǒ jiā zài sān lóu.","vi":"Nhà mình ở tầng ba."}},{"stt":9,"hanzi":"站","pinyin":"zhàn","hanviet":"Trạm","pos":"Danh từ","meaning":"trạm, ga, bến","comps":"车站 (bến xe), 两站地铁 (hai bến tàu điện)","example":{"zh":"再坐两站就到了。","py":"Zài zuò liǎng zhàn jiù dào le.","vi":"Đi thêm hai bến nữa là tới."}},{"stt":10,"hanzi":"小时候","pinyin":"xiǎoshíhou","hanviet":"Tiểu thời hậu","pos":"Danh từ","meaning":"hồi nhỏ","comps":"我小时候 (hồi nhỏ tôi), 小时候的朋友 (bạn hồi nhỏ)","example":{"zh":"我小时候住在北京。","py":"Wǒ xiǎoshíhou zhù zài Běijīng.","vi":"Hồi nhỏ mình sống ở Bắc Kinh."}},{"stt":11,"hanzi":"好","pinyin":"hǎo","hanviet":"Hảo","pos":"Phó từ","meaning":"rất, thật là (cảm thán)","comps":"好高兴 (vui quá), 好冷啊 (lạnh quá)","example":{"zh":"今天好冷啊！","py":"Jīntiān hǎo lěng a!","vi":"Hôm nay lạnh quá!"}}],"hanzi":[{"char":"事情","pinyin":"shìqing","hanviet":"Sự tình","chars":["事","情"],"story":"事 vẽ bàn tay cầm thẻ ghi chép / cờ hiệu → làm việc → sự việc. 情 = 忄 (lòng) + 青 qīng chỉ âm → tình cảm, tình hình. 事情 = chuyện, việc."},{"char":"晴","pinyin":"qíng","hanviet":"Tình","chars":["晴"],"story":"晴 = 日 (mặt trời) + 青 qīng (xanh, chỉ âm): mặt trời rạng, bầu trời xanh → nắng. Nhóm 青 đọc giống nhau: 清 · 情 · 请 · 晴."},{"char":"正","pinyin":"zhèng","hanviet":"Chính","chars":["正"],"story":"正 = 一 (vạch đích) + 止 (bàn chân): bước thẳng tới đích → ngay, chính. Làm phó từ = \"đang\": 正下着雪."},{"char":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","chars":["外","面"],"story":"外 = 夕 (buổi tối) + 卜 (bói): bói buổi tối là ngoài lệ → ngoài (bài 2). 面 = phía (bài 5). 外面 = bên ngoài."},{"char":"阴","pinyin":"yīn","hanviet":"Âm","chars":["阴"],"story":"阴 = 阝 (sườn đồi) + 月 (mặt trăng): sườn đồi khuất nắng, chỉ có trăng → râm, âm u. Cặp đối: 阳 = 阝 + 日 (dương, nắng)."},{"char":"从小","pinyin":"cóngxiǎo","hanviet":"Tòng tiểu","chars":["从","小"],"story":"从 = hai người 人 nối gót nhau → đi theo, từ (bài 7). 小 = nhỏ. 从小 = từ lúc nhỏ."},{"char":"地铁","pinyin":"dìtiě","hanviet":"Địa thiết","chars":["地","铁"],"story":"地 = 土 (đất) + 也 → đất. 铁 = 钅 (kim loại) + 失 shī chỉ âm → sắt. 地铁 = đường sắt chạy dưới lòng đất → tàu điện ngầm."},{"char":"楼","pinyin":"lóu","hanviet":"Lâu","chars":["楼"],"story":"楼 = 木 (gỗ) + 娄 lóu chỉ âm → nhà gỗ nhiều tầng → lầu, toà nhà, tầng."},{"char":"站","pinyin":"zhàn","hanviet":"Trạm","chars":["站"],"story":"站 = 立 (người đứng) + 占 zhàn chỉ âm → đứng; chỗ đứng đợi xe → trạm, bến. Bài này là danh từ (车站); bài 14 gặp lại là động từ \"đứng\"."},{"char":"小时候","pinyin":"xiǎoshíhou","hanviet":"Tiểu thời hậu","chars":["小","时","候"],"story":"小 = nhỏ. 时候 = lúc (时 = 日 + 寸, 候 = chờ đợi). 小时候 = lúc còn nhỏ, hồi bé."},{"char":"好","pinyin":"hǎo","hanviet":"Hảo","chars":["好"],"story":"好 = 女 (người mẹ) + 子 (đứa con): mẹ ôm con → tốt. Đứng trước tính từ trong câu cảm thán = \"thật là, … quá\": 好高兴啊！"}],"grammar":[{"title":"Câu so sánh (4): A 比 B + tính từ + 多了 / 得多","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多了 / 得多</b><small>… hơn nhiều</small></span></div>","summary":"<p class=\"gr-lead\">A 比 B + TT + 多了 / 得多</p><ul><li><span class=\"zh\">多了</span> / <span class=\"zh\">得多</span> đặt <b>sau</b> tính từ = hơn <b>nhiều</b>, chênh lệch rất lớn.</li></ul>","note":"<b>Lưu ý:</b> Câu <span class=\"zh\">比</span> không dùng <span class=\"zh\">很、非常</span>: ✗ <span class=\"zh\">这里比北京很冷</span> → ✓ <span class=\"zh\">这里比北京冷多了</span>.","examples":[{"zh":"我这里比北京冷多了。","py":"Wǒ zhèlǐ bǐ Běijīng lěngduō le.","vi":"Chỗ em lạnh hơn Bắc Kinh nhiều."},{"zh":"坐飞机比坐火车快得多。","py":"Zuò fēijī bǐ zuò huǒchē kuài de duō.","vi":"Đi máy bay nhanh hơn đi tàu hoả nhiều."},{"zh":"他觉得红茶比绿茶好喝得多。","py":"Tā juéde hóngchá bǐ lǜchá hǎohē de duō.","vi":"Anh ấy thấy hồng trà ngon hơn trà xanh nhiều."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">左边这块手表好看还是右边那块好看？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">左边这块，但是它____。</span></span></span><span class=\"qz-hint\">Chiếc đồng hồ bên trái đẹp hay chiếc bên phải đẹp? — Chiếc bên trái, nhưng nó đắt hơn chiếc bên phải nhiều.</span>","answer":["比右边那块贵多了","比右边那块贵得多","比右边的贵多了","比右边的贵得多"],"explain":"左边这块，但是它比右边那块贵多了。 (Zuǒbian zhè kuài, dànshì tā bǐ yòubian nà kuài guìduō le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">走，我请你喝咖啡。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">喝奶茶吧，奶茶店____。我有点儿累，不想走太远。</span></span></span><span class=\"qz-hint\">Đi, mình mời bạn uống cà phê. — Uống trà sữa đi, tiệm trà sữa gần hơn quán cà phê nhiều. Mình hơi mệt, không muốn đi xa.</span>","answer":["比咖啡店近得多","比咖啡店近多了"],"explain":"喝奶茶吧，奶茶店比咖啡店近得多。我有点儿累，不想走太远。 (Hē nǎichá ba, nǎichádiàn bǐ kāfēidiàn jìn de duō. Wǒ yǒudiǎnr lèi, bù xiǎng zǒu tài yuǎn.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">几年没见你女儿了，她个子很高了吧？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，个子____。</span></span></span><span class=\"qz-hint\">Mấy năm không gặp con gái chị, chắc cháu cao lắm rồi nhỉ? — Đúng thế, cao hơn tôi nhiều rồi.</span>","answer":["比我高多了","比我高得多"],"explain":"是啊，个子比我高多了。 (Shì a, gèzi bǐ wǒ gāoduō le.)"}]},{"title":"Câu so sánh (5): 比 + bổ ngữ trạng thái","formula":"<div class=\"fx-lbl\">比 trước ĐT</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b></span></div><div class=\"fx-ex zh\">妈妈比我睡得晚。</div><div class=\"fx-lbl\">比 sau ĐT</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b></span></div><div class=\"fx-ex zh\">李文跑得比白家月快。</div>","summary":"<p class=\"gr-lead\">比 + bổ ngữ trạng thái</p><ul><li>Động từ có <b>bổ ngữ trạng thái</b> → <span class=\"zh\">比</span> đặt <b>trước</b> hoặc <b>sau</b> động từ đều được, nghĩa không đổi.</li></ul>","note":"<b>Lưu ý:</b> <span class=\"zh\">比 B</span> không đặt cuối câu: ✗ <span class=\"zh\">李文跑得快比白家月</span>.","examples":[{"zh":"昨天比今天下得大。","py":"Zuótiān bǐ jīntiān xià de dà.","vi":"Hôm qua (tuyết) rơi to hơn hôm nay."},{"zh":"妈妈比我睡得晚。","py":"Māma bǐ wǒ shuì de wǎn.","vi":"Mẹ ngủ muộn hơn mình."},{"zh":"李文跑得比白家月快。","py":"Lǐ Wén pǎo de bǐ Bái Jiāyuè kuài.","vi":"Lý Văn chạy nhanh hơn Gia Nguyệt."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">家月，你今天来得真早！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">老师，天中____，他去外面跑步了。</span></span></span><span class=\"qz-hint\">Gia Nguyệt, hôm nay em đến sớm thật! — Thưa cô, Thiên Trung còn đến sớm hơn em, bạn ấy ra ngoài chạy bộ rồi.</span>","answer":["比我来得更早","比我来得还早","比我来得早","来得比我还早","来得比我早","来得比我更早"],"explain":"老师，天中比我来得更早，他去外面跑步了。 (Lǎoshī, Tiānzhōng bǐ wǒ lái de gèng zǎo, tā qù wàimiàn pǎobù le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小明，你中午没吃饭吧？晚上吃得这么多！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">多吗？您看看姐姐，她____。</span></span></span><span class=\"qz-hint\">Tiểu Minh, trưa con chưa ăn à? Tối ăn nhiều thế! — Nhiều ạ? Mẹ xem chị kìa, chị ăn còn nhiều hơn con.</span>","answer":["吃得比我还多","吃得比我多","比我吃得还多","比我吃得多"],"explain":"多吗？您看看姐姐，她吃得比我还多。 (Duō ma? Nín kànkan jiějie, tā chī de bǐ wǒ hái duō.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">一飞，这些汉字是外国人写的吗？真好看！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊！我觉得____。</span></span></span><span class=\"qz-hint\">Nhất Phi, mấy chữ Hán này người nước ngoài viết à? Đẹp thật! — Đúng thế! Em thấy họ viết đẹp hơn em.</span>","answer":["他们写得比我好","他们写得比我还好","他们比我写得好","他们写得比我更好"],"explain":"是啊！我觉得他们写得比我好。 (Shì a! Wǒ juéde tāmen xiě de bǐ wǒ hǎo.)"}]},{"title":"Câu so sánh (6): có tân ngữ + bổ ngữ trạng thái","formula":"<div class=\"fx-lbl\">TN lên trước</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>动词 + 得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b></span></div><div class=\"fx-ex zh\">白家月汉字写得比陈天中好。</div><div class=\"fx-lbl\">Lặp ĐT ①</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词 + 宾语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>动词 + 得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b></span></div><div class=\"fx-ex zh\">你跑步跑得比我快。</div><div class=\"fx-lbl\">Lặp ĐT ②</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词 + 宾语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>动词 + 得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b></span></div><div class=\"fx-ex zh\">他踢足球比我踢得好。</div>","summary":"<p class=\"gr-lead\">Có tân ngữ + bổ ngữ trạng thái</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">得</span> đi liền sau động từ, không sau tân ngữ: ✗ <span class=\"zh\">他踢足球得比我好</span>.","examples":[{"zh":"你跑步跑得比我快。","py":"Nǐ pǎobù pǎo de bǐ wǒ kuài.","vi":"Cậu chạy bộ nhanh hơn mình."},{"zh":"白家月汉字写得比陈天中好。","py":"Bái Jiāyuè Hànzì xiě de bǐ Chén Tiānzhōng hǎo.","vi":"Gia Nguyệt viết chữ Hán đẹp hơn Thiên Trung."},{"zh":"他踢足球比我踢得好。","py":"Tā tī zúqiú bǐ wǒ tī de hǎo.","vi":"Cậu ấy đá bóng giỏi hơn mình."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你们几个谁打篮球打得好？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">李文，他____。</span></span></span><span class=\"qz-hint\">Mấy bạn ai chơi bóng rổ giỏi? — Lý Văn, cậu ấy chơi bóng rổ giỏi hơn bọn mình.</span>","answer":["打篮球打得比我们好","打篮球比我们打得好"],"explain":"李文，他打篮球打得比我们好。 (Lǐ Wén, tā dǎ lánqiú dǎ de bǐ wǒmen hǎo.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你会做菜吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">会，但____，所以我更喜欢吃妈妈做的菜。</span></span></span><span class=\"qz-hint\">Bạn biết nấu ăn không? — Biết, nhưng mẹ nấu ngon hơn mình, nên mình thích ăn món mẹ nấu hơn.</span>","answer":["妈妈做菜做得比我好","妈妈做菜比我做得好"],"explain":"会，但妈妈做菜做得比我好，所以我更喜欢吃妈妈做的菜。 (Huì, dàn māma zuò cài zuò de bǐ wǒ hǎo, suǒyǐ wǒ gèng xǐhuan chī māma zuò de cài.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你唱歌唱得怎么样？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">还可以，但家月____。</span></span></span><span class=\"qz-hint\">Bạn hát thế nào? — Cũng được, nhưng Gia Nguyệt hát hay hơn mình.</span>","answer":["唱歌比我唱得好","唱歌唱得比我好"],"explain":"还可以，但家月唱歌比我唱得好。 (Hái kěyǐ, dàn Jiāyuè chànggē bǐ wǒ chàng de hǎo.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在房间","titleVi":"Trong phòng — Gia Nguyệt gọi chị Nhất Tuyết","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"喂，家月，是你啊！有什么事情吗？","py":"Wèi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?","vi":"A lô, Gia Nguyệt, là em à! Có chuyện gì không em?"},{"speaker":"月","name":"Gia Nguyệt","zh":"没什么事，就想跟您说说话。","py":"Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","vi":"Không có gì ạ, chỉ muốn nói chuyện với chị chút thôi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好啊。你今天没课吗？","py":"Hǎo a. Nǐ jīntiān méi kè ma?","vi":"Được thôi. Hôm nay em không có tiết à?"},{"speaker":"月","name":"Gia Nguyệt","zh":"下午有课。您那里天气怎么样？","py":"Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?","vi":"Chiều em có tiết. Chỗ chị thời tiết thế nào ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"北京这几天虽然是晴天，但是有点儿冷。","py":"Běijīng zhè jǐ tiān suīrán shì qíngtiān, dànshì yǒudiǎnr lěng.","vi":"Mấy hôm nay Bắc Kinh tuy trời nắng nhưng hơi lạnh."},{"speaker":"月","name":"Gia Nguyệt","zh":"我这里比北京冷多了，外边还正下着雪呢！","py":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","vi":"Chỗ em lạnh hơn Bắc Kinh nhiều, bên ngoài còn đang có tuyết rơi kìa!"}]},{"titleZh":"课文二 · 在客厅","titleVi":"Phòng khách — chị Nhất Tuyết gọi Nhất Phi","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"喂，一飞，听家月说你那边下雪了，下得大不大？","py":"Wèi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xià xuě le, xià de dà bu dà?","vi":"A lô, Nhất Phi, nghe Gia Nguyệt nói chỗ em có tuyết, tuyết có to không?"},{"speaker":"飞","name":"Cô Nhất Phi","zh":"今天不大，昨天比今天下得大。","py":"Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà.","vi":"Hôm nay không to, hôm qua rơi to hơn hôm nay."},{"speaker":"雪","name":"Nhất Tuyết","zh":"天气不好，你去外面的时候多穿点儿衣服。","py":"Tiānqì bù hǎo, nǐ qù wàimiàn de shíhou duō chuān diǎnr yīfu.","vi":"Thời tiết xấu, lúc em ra ngoài nhớ mặc thêm áo."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"这几天我在网上上课，没出去过。","py":"Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqùguo.","vi":"Mấy hôm nay em dạy online, chưa ra ngoài lần nào."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那就好，有事记得给我打电话。","py":"Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.","vi":"Thế thì tốt, có việc gì nhớ gọi cho chị."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"好的。现在不下雪了，我出去买点儿吃的。","py":"Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de.","vi":"Vâng. Giờ hết tuyết rồi, em ra ngoài mua chút đồ ăn."},{"speaker":"雪","name":"Nhất Tuyết","zh":"一次多买点儿，阴天下雪什么的就少出去吧。","py":"Yí cì duō mǎi diǎnr, yīn tiān xià xuě shénmede jiù shǎo chūqù ba.","vi":"Mua một lần nhiều chút, trời âm u, có tuyết các kiểu thì ít ra ngoài thôi."}]},{"titleZh":"课文三 · 在房间","titleVi":"Trong phòng — Lý Văn rủ đi chạy bộ","lines":[{"speaker":"文","name":"Lý Văn","zh":"喂，家月，今天天气不错，我们去跑步吧！","py":"Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!","vi":"A lô, Gia Nguyệt, hôm nay trời đẹp, mình đi chạy bộ đi!"},{"speaker":"月","name":"Gia Nguyệt","zh":"你跑步跑得比我快，我们能一起跑吗？","py":"Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","vi":"Cậu chạy nhanh hơn mình, bọn mình chạy cùng được không?"},{"speaker":"文","name":"Lý Văn","zh":"可以的，我慢慢跑，等着你。","py":"Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ.","vi":"Được mà, mình chạy chầm chậm, đợi cậu."},{"speaker":"月","name":"Gia Nguyệt","zh":"好吧。你真爱跑步啊！","py":"Hǎo ba. Nǐ zhēn ài pǎobù a!","vi":"Thôi được. Cậu mê chạy bộ thật đấy!"},{"speaker":"文","name":"Lý Văn","zh":"我从小就经常跟爸爸跑步，跑步能让人快乐！","py":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","vi":"Từ nhỏ mình đã hay chạy bộ với bố, chạy bộ làm người ta vui vẻ mà!"},{"speaker":"月","name":"Gia Nguyệt","zh":"好，那我准备一下。","py":"Hǎo, nà wǒ zhǔnbèi yíxià.","vi":"Được, vậy mình chuẩn bị chút."},{"speaker":"文","name":"Lý Văn","zh":"我现在坐地铁去找你，一会儿楼下见。","py":"Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn.","vi":"Giờ mình đi tàu điện ngầm qua tìm cậu, lát gặp dưới toà nhà nhé."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Gia Nguyệt","para":true,"speaker":"月","lines":[{"zh":"前几天天气不好，我没走路，每天坐两站地铁去学校。","py":"Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měi tiān zuò liǎng zhàn dìtiě qù xuéxiào.","vi":"Mấy hôm trước thời tiết xấu, mình không đi bộ mà ngày nào cũng đi hai bến tàu điện ngầm đến trường."},{"zh":"今天是个大晴天，李文让我跟他去外面跑步。","py":"Jīntiān shì ge dà qíngtiān, Lǐ Wén ràng wǒ gēn tā qù wàimiàn pǎobù.","vi":"Hôm nay trời nắng đẹp, Lý Văn rủ mình ra ngoài chạy bộ cùng."},{"zh":"他小时候经常跑步，跑得比我快，但是他会等我。","py":"Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ.","vi":"Hồi nhỏ cậu ấy hay chạy bộ, chạy nhanh hơn mình, nhưng cậu ấy sẽ đợi mình."},{"zh":"跟李文一起跑步，我好高兴啊！","py":"Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!","vi":"Được chạy bộ cùng Lý Văn, mình vui quá!"}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Gọi điện · So sánh thời tiết","q":{"zh":"两人一组，打电话说说天气，比一比两个地方的天气。","py":"Liǎng rén yì zǔ, dǎ diànhuà shuōshuo tiānqì, bǐ yi bǐ liǎng ge dìfang de tiānqì.","vi":"Theo cặp, gọi điện nói về thời tiết, so sánh thời tiết hai nơi."},"items":[{"lines":[{"who":"A","zh":"喂，家月，你在做什么呢？","py":"Wèi, Jiāyuè, nǐ zài zuò shénme ne?","vi":"A lô, Gia Nguyệt, cậu đang làm gì thế?"},{"who":"B","zh":"我在家休息呢。","py":"Wǒ zài jiā xiūxi ne.","vi":"Mình đang nghỉ ở nhà."}]},{"zh":"你那里天气怎么样？—— 是晴天，比昨天热多了。","py":"Nǐ nàlǐ tiānqì zěnmeyàng? —— Shì qíngtiān, bǐ zuótiān rèduō le.","vi":"Chỗ cậu thời tiết thế nào? — Trời nắng, nóng hơn hôm qua nhiều."},{"zh":"我这里正下着雨呢，比你那里冷得多。","py":"Wǒ zhèlǐ zhèng xiàzhe yǔ ne, bǐ nǐ nàlǐ lěng de duō.","vi":"Chỗ mình đang mưa, lạnh hơn chỗ cậu nhiều."}]}],"speak":[]},"review":{"range":"10–12","rows":[{"l":10,"zh":"主谓谓语句","vi":"Câu vị ngữ chủ-vị","ex":{"zh":"他学习很好。","py":"Tā xuéxí hěn hǎo.","vi":"Cậu ấy học rất giỏi."}},{"l":10,"zh":"选择问句","vi":"Câu hỏi lựa chọn","ex":{"zh":"你喝咖啡还是茶？","py":"Nǐ hē kāfēi háishi chá?","vi":"Bạn uống cà phê hay trà?"}},{"l":10,"zh":"固定格式 \"要/快/快要/就要……了\"","vi":"Cấu trúc 要/快/快要/就要……了","ex":{"zh":"我要回国了。","py":"Wǒ yào huí guó le.","vi":"Mình sắp về nước rồi."}},{"l":11,"zh":"动态助词 \"着\" (1)","vi":"Trợ từ động thái 着 (1)","ex":{"zh":"他在那儿坐着。","py":"Tā zài nàr zuòzhe.","vi":"Anh ấy đang ngồi ở đó."}},{"l":11,"zh":"动态助词 \"着\" (2)","vi":"Trợ từ động thái 着 (2)","ex":{"zh":"她穿着白色的裤子。","py":"Tā chuānzhe báisè de kùzi.","vi":"Cô ấy đang mặc quần màu trắng."}},{"l":11,"zh":"程度副词 \"最\"","vi":"Phó từ mức độ 最","ex":{"zh":"在我们家，爸爸最高。","py":"Zài wǒmen jiā, bàba zuì gāo.","vi":"Nhà mình thì bố cao nhất."}},{"l":12,"zh":"比较句 (4)","vi":"Câu so sánh (4): 多了 / 得多","ex":{"zh":"今天比昨天热多了。","py":"Jīntiān bǐ zuótiān rèduō le.","vi":"Hôm nay nóng hơn hôm qua nhiều."}},{"l":12,"zh":"比较句 (5)","vi":"Câu so sánh (5): 比 + bổ ngữ trạng thái","ex":{"zh":"我写得比他快。","py":"Wǒ xiě de bǐ tā kuài.","vi":"Mình viết nhanh hơn cậu ấy."}},{"l":12,"zh":"比较句 (6)","vi":"Câu so sánh (6): có tân ngữ","ex":{"zh":"他踢足球比我踢得好。","py":"Tā tī zúqiú bǐ wǒ tī de hǎo.","vi":"Cậu ấy đá bóng giỏi hơn mình."}}]}},{"id":"k2v3-b13","courseId":"k2v3","order":13,"title":"Chúng tôi thích học tiếng Trung","titleZh":"我们爱上中文课","titlePy":"wǒmen ài shàng Zhōngwén kè","vocab":[{"stt":1,"hanzi":"新年","pinyin":"xīnnián","hanviet":"Tân niên","pos":"Danh từ","meaning":"năm mới","comps":"新年快乐 (chúc mừng năm mới), 新年礼物 (quà năm mới)","example":{"zh":"新年就要到了。","py":"Xīnnián jiù yào dào le.","vi":"Năm mới sắp đến rồi."}},{"stt":2,"hanzi":"教","pinyin":"jiāo","hanviet":"Giáo","pos":"Động từ","meaning":"dạy","comps":"教中文 (dạy tiếng Trung), 教我 (dạy tôi)","example":{"zh":"妈妈教我做饭。","py":"Māma jiāo wǒ zuò fàn.","vi":"Mẹ dạy mình nấu cơm."}},{"stt":3,"hanzi":"花","pinyin":"huā","hanviet":"Hoa","pos":"Danh từ","meaning":"hoa","comps":"买花 (mua hoa), 花店 (tiệm hoa)","example":{"zh":"这些花真漂亮！","py":"Zhèxiē huā zhēn piàoliang!","vi":"Những bông hoa này đẹp quá!"}},{"stt":4,"hanzi":"希望","pinyin":"xīwàng","hanviet":"Hy vọng","pos":"Động từ","meaning":"hy vọng, mong","comps":"希望你喜欢 (mong bạn thích), 我希望 (tôi mong)","example":{"zh":"希望你喜欢这个礼物。","py":"Xīwàng nǐ xǐhuan zhège lǐwù.","vi":"Mong bạn thích món quà này."}},{"stt":5,"hanzi":"上面","pinyin":"shàngmiàn","hanviet":"Thượng diện","pos":"Danh từ","meaning":"bên trên, mặt trên","comps":"桌子上面 (trên bàn), 本子上面 (trên vở)","example":{"zh":"书在桌子上面。","py":"Shū zài zhuōzi shàngmiàn.","vi":"Sách ở trên bàn."}},{"stt":6,"hanzi":"洗手间","pinyin":"xǐshǒujiān","hanviet":"Tẩy thủ gian","pos":"Danh từ","meaning":"nhà vệ sinh","comps":"去洗手间 (đi vệ sinh), 洗手间在哪儿 (WC ở đâu)","example":{"zh":"请问，洗手间在哪儿？","py":"Qǐngwèn, xǐshǒujiān zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu ạ?"}},{"stt":7,"hanzi":"里面","pinyin":"lǐmiàn","hanviet":"Lý diện","pos":"Danh từ","meaning":"bên trong","comps":"房间里面 (trong phòng), 书包里面 (trong cặp)","example":{"zh":"书包里面有两本书。","py":"Shūbāo lǐmiàn yǒu liǎng běn shū.","vi":"Trong cặp có hai quyển sách."}},{"stt":8,"hanzi":"笔","pinyin":"bǐ","hanviet":"Bút","pos":"Lượng từ","meaning":"nét (lượng từ của nét chữ)","comps":"一笔 (một nét), 多一笔 (thêm một nét)","example":{"zh":"这个字有几笔？","py":"Zhège zì yǒu jǐ bǐ?","vi":"Chữ này có mấy nét?"}},{"stt":9,"hanzi":"可能","pinyin":"kěnéng","hanviet":"Khả năng","pos":"Động từ","meaning":"có thể, có lẽ","comps":"可能会 (có thể sẽ), 不可能 (không thể)","example":{"zh":"他可能不来了。","py":"Tā kěnéng bù lái le.","vi":"Có lẽ anh ấy không đến nữa."}},{"stt":10,"hanzi":"上网","pinyin":"shàngwǎng","hanviet":"Thượng võng","pos":"Động từ","meaning":"lên mạng","comps":"上网买 (mua trên mạng), 上网看电影 (lên mạng xem phim)","example":{"zh":"我经常上网买东西。","py":"Wǒ jīngcháng shàngwǎng mǎi dōngxi.","vi":"Mình hay lên mạng mua đồ."}},{"stt":11,"hanzi":"那样","pinyin":"nàyàng","hanviet":"Na dạng","pos":"Đại từ","meaning":"như thế, như vậy","comps":"那样做 (làm như thế), 那样的人 (người như thế)","example":{"zh":"你别那样说。","py":"Nǐ bié nàyàng shuō.","vi":"Bạn đừng nói như thế."}},{"stt":12,"hanzi":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","pos":"Động từ","meaning":"nói cho biết, bảo","comps":"告诉我 (nói cho tôi biết), 告诉他 (bảo anh ấy)","example":{"zh":"你告诉他明天不上课。","py":"Nǐ gàosu tā míngtiān bú shàngkè.","vi":"Bạn bảo cậu ấy mai không có tiết nhé."}},{"stt":13,"hanzi":"班","pinyin":"bān","hanviet":"Ban","pos":"Danh từ","meaning":"lớp","comps":"我们班 (lớp chúng tôi), 一个班 (một lớp)","example":{"zh":"我们班有二十个学生。","py":"Wǒmen bān yǒu èrshí ge xuésheng.","vi":"Lớp mình có hai mươi học sinh."}}],"hanzi":[{"char":"新年","pinyin":"xīnnián","hanviet":"Tân niên","chars":["新","年"],"story":"新 = 亲 (cây, biến thể) + 斤 (cái rìu): rìu chặt cây lấy gỗ mới → mới. 年 vẽ người vác bó lúa chín → một mùa thu hoạch = một năm."},{"char":"教","pinyin":"jiāo","hanviet":"Giáo","chars":["教"],"story":"教 = 孝 (biến thể: trẻ 子 học điều hay) + 攵 (tay cầm thước): thầy cầm thước dạy trẻ → dạy. Đọc jiāo (dạy ai cái gì); jiào trong 教室."},{"char":"花","pinyin":"huā","hanviet":"Hoa","chars":["花"],"story":"花 = bộ Thảo 艹 + 化 huà (biến hoá) chỉ âm: cây cỏ biến hoá nở ra → hoa. Bài 8 là động từ \"tiêu (tiền)\", bài này là danh từ \"hoa\"."},{"char":"希望","pinyin":"xīwàng","hanviet":"Hy vọng","chars":["希","望"],"story":"希 = 爻 (đan chéo) + 巾 (vải): vải dệt thưa → hiếm, mong. 望 = 亡 + 月 + 王 (người đứng trên đất): đứng ngóng trăng → trông mong. 希望 = hy vọng."},{"char":"上面","pinyin":"shàngmiàn","hanviet":"Thượng diện","chars":["上","面"],"story":"上 vẽ vạch nằm trên đường ngang → trên. 面 = phía, mặt (bài 5). 上面 = bên trên, mặt trên. Cặp với 下面 bài 5."},{"char":"洗手间","pinyin":"xǐshǒujiān","hanviet":"Tẩy thủ gian","chars":["洗","手","间"],"story":"洗 = 氵 + 先 (rửa, bài 3) · 手 = tay · 间 = 门 (cửa) + 日 → gian phòng. Phòng rửa tay = nhà vệ sinh. Bên trong 门 là 日, không phải 口 (问)!"},{"char":"里面","pinyin":"lǐmiàn","hanviet":"Lý diện","chars":["里","面"],"story":"里 = 田 (ruộng) + 土 (đất) → làng xóm; mượn làm \"trong\". 面 = phía. 里面 = bên trong."},{"char":"笔","pinyin":"bǐ","hanviet":"Bút","chars":["笔"],"story":"笔 = ⺮ (tre) + 毛 (lông) → bút lông (bài 10). Bút đưa một lần thành một nét → lượng từ \"nét\": 一笔."},{"char":"可能","pinyin":"kěnéng","hanviet":"Khả năng","chars":["可","能"],"story":"可 = 口 + 丁: miệng nói \"được\" → có thể. 能 vẽ con gấu khoẻ mạnh → có năng lực. 可能 = khả năng, có lẽ."},{"char":"上网","pinyin":"shàngwǎng","hanviet":"Thượng võng","chars":["上","网"],"story":"上 = lên. 网 vẽ tấm lưới đánh cá có mắt lưới chéo → lưới → mạng. 上网 = lên mạng."},{"char":"那样","pinyin":"nàyàng","hanviet":"Na dạng","chars":["那","样"],"story":"那 = kia, đó. 样 = 木 (cây) + 羊 yáng chỉ âm → hình dạng, kiểu. 那样 = kiểu đó, như thế. Cặp với 这样 (bài 9)."},{"char":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","chars":["告","诉"],"story":"告 = 牛 (bò) + 口: dâng bò, cất lời báo với thần → báo. 诉 = 讠 (lời) + 斥 → kể lể. 告诉 = nói cho biết."},{"char":"班","pinyin":"bān","hanviet":"Ban","chars":["班"],"story":"班 = 王 + 刂 (dao) + 王: dùng dao chia ngọc thành hai phần → chia ra → nhóm được chia = lớp, ca."}],"grammar":[{"title":"Câu hai tân ngữ (2): 拿给 / 送给 / 卖给","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>拿给 / 送给 / 卖给</b><small>đưa / tặng / bán cho</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语1</b><small>người</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语2</b><small>vật</small></span></div>","summary":"<p class=\"gr-lead\">送给 + người + vật</p><ul><li>Phần (1) ở HSK1: <span class=\"zh\">给、教、问</span> + người + vật — <span class=\"zh\">王老师教我们中文</span>.</li></ul>","note":"<b>Lưu ý:</b> Người đứng <b>trước</b>, vật đứng <b>sau</b>: ✗ <span class=\"zh\">送给花王老师</span> → ✓ <span class=\"zh\">送给王老师花</span>.","examples":[{"zh":"王老师喜欢花，就送给她花吧。","py":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","vi":"Cô Vương thích hoa, vậy tặng cô hoa đi."},{"zh":"她拿给我一杯水。","py":"Tā ná gěi wǒ yì bēi shuǐ.","vi":"Cô ấy đưa cho mình một cốc nước."},{"zh":"他卖给我一本中文书。","py":"Tā mài gěi wǒ yì běn Zhōngwén shū.","vi":"Anh ấy bán cho mình một quyển sách tiếng Trung."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我想送给____，她会喜欢吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没问题，她的爱好就是读书。</span></span></span><span class=\"qz-hint\">Mình muốn tặng mẹ một quyển sách, mẹ có thích không nhỉ? — Không vấn đề gì, sở thích của mẹ chính là đọc sách mà.</span>","answer":["妈妈一本书","妈妈一本"],"explain":"我想送给妈妈一本书，她会喜欢吗？ (Wǒ xiǎng sòng gěi māma yì běn shū, tā huì xǐhuan ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">昨天过生日，爸爸送____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我看看。这个手机很好啊！</span></span></span><span class=\"qz-hint\">Hôm qua sinh nhật, bố tặng mình một chiếc điện thoại. — Cho mình xem. Điện thoại này tốt đấy!</span>","answer":["给我一个手机"],"explain":"昨天过生日，爸爸送给我一个手机。 (Zuótiān guò shēngrì, bàba sòng gěi wǒ yí ge shǒujī.)"}]},{"title":"Câu so sánh (7): A 比 B + tính từ + cụm số lượng","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数量短语</b><small>hơn bao nhiêu</small></span></div>","summary":"<p class=\"gr-lead\">A 比 B + TT + số lượng</p><ul><li>Cụm số lượng đặt <b>sau</b> tính từ, cho biết hơn <b>cụ thể</b> bao nhiêu: <span class=\"zh\">大三岁</span> · <span class=\"zh\">多了十个</span>.</li></ul>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">姐姐比我三岁大</span> → ✓ <span class=\"zh\">姐姐比我大三岁</span>.","examples":[{"zh":"今天的词比昨天多了十个。","py":"Jīntiān de cí bǐ zuótiān duōle shí ge.","vi":"Từ hôm nay nhiều hơn hôm qua mười từ."},{"zh":"姐姐比我大三岁。","py":"Jiějie bǐ wǒ dà sān suì.","vi":"Chị gái hơn mình ba tuổi."},{"zh":"坐飞机比坐火车快五个多小时。","py":"Zuò fēijī bǐ zuò huǒchē kuài wǔ ge duō xiǎoshí.","vi":"Đi máy bay nhanh hơn đi tàu hoả hơn năm tiếng."}],"exercises":[]},{"title":"Câu so sánh (8): A 比 B + tính từ + 一点儿 / 一些","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一点儿 / 一些</b><small>hơn một chút</small></span></div>","summary":"<p class=\"gr-lead\">A 比 B + TT + 一点儿 / 一些</p><ul><li><span class=\"zh\">一点儿 / 一些</span> sau tính từ = hơn <b>một chút</b>; đối lập với <span class=\"zh\">多了 / 得多</span> (bài 12).</li></ul>","note":"<b>Lưu ý:</b> Không dùng <span class=\"zh\">有点儿</span> trong câu <span class=\"zh\">比</span>: ✗ <span class=\"zh\">姐姐比我有点儿高</span> → ✓ <span class=\"zh\">姐姐比我高一点儿</span>.","examples":[{"zh":"比我们一起买的那个本子贵一点儿。","py":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.","vi":"Đắt hơn quyển bọn mình mua cùng nhau một chút."},{"zh":"姐姐比我高一点儿。","py":"Jiějie bǐ wǒ gāo yìdiǎnr.","vi":"Chị gái cao hơn mình một chút."},{"zh":"那间教室比这间大一些。","py":"Nà jiān jiàoshì bǐ zhè jiān dà yìxiē.","vi":"Phòng học kia rộng hơn phòng này một chút."}],"exercises":[{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你觉得这条白色的裤子长不长？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">{{0}}那条黑色的{{1}}，还是买那条吧。</span></span></span><span class=\"qz-hint\">Bạn thấy chiếc quần trắng này có dài không? — Nó dài hơn chiếc màu đen một chút, hay là mua chiếc kia đi.</span>","blanks":[["它比","这条比","这条裤子比"],["长一点儿","长一些"]],"explain":"它比那条黑色的长一点儿，还是买那条吧。 (Tā bǐ nà tiáo hēisè de cháng yìdiǎnr, háishi mǎi nà tiáo ba.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今天的苹果{{0}}昨天的{{1}}。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">便宜的也很好吃。</span></span></span><span class=\"qz-hint\">Táo hôm nay rẻ hơn hôm qua một chút. — Rẻ cũng ngon lắm.</span>","blanks":[["比"],["便宜一些","便宜一点儿","便宜一点"]],"explain":"今天的苹果比昨天的便宜一些。 (Jīntiān de píngguǒ bǐ zuótiān de piányi yìxiē.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">姐姐的书和本子比我多，所以她的书包____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">也比你的书包贵一点儿。</span></span></span><span class=\"qz-hint\">Chị nhiều sách vở hơn em, nên cặp của chị to hơn của em một chút. — Cũng đắt hơn cặp của em một chút.</span>","answer":["比我的大一些","比我的大一点儿","比我的书包大一些"],"explain":"姐姐的书和本子比我多，所以她的书包比我的大一些。 (Jiějie de shū hé běnzi bǐ wǒ duō, suǒyǐ tā de shūbāo bǐ wǒ de dà yìxiē.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp — chọn quà năm mới cho cô","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"时间过得真快啊！新年就要到了。","py":"Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le.","vi":"Thời gian trôi nhanh thật! Năm mới sắp đến rồi."},{"speaker":"中","name":"Thiên Trung","zh":"这一年王老师教我们中文，每天工作都很累。","py":"Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","vi":"Năm nay cô Vương dạy chúng mình tiếng Trung, ngày nào cũng làm việc rất vất vả."},{"speaker":"月","name":"Gia Nguyệt","zh":"是啊，她教得很好。因为她，我们都非常爱上中文课。","py":"Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè.","vi":"Đúng vậy, cô dạy rất hay. Nhờ cô mà chúng mình đều rất thích học tiếng Trung."},{"speaker":"中","name":"Thiên Trung","zh":"我们给她准备个新年礼物吧。你觉得送给她什么好呢？","py":"Wǒmen gěi tā zhǔnbèi ge xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?","vi":"Chúng mình chuẩn bị quà năm mới cho cô đi. Cậu thấy tặng cô gì thì hay?"},{"speaker":"月","name":"Gia Nguyệt","zh":"王老师喜欢花，就送给她花吧。","py":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","vi":"Cô Vương thích hoa, vậy tặng cô hoa đi."},{"speaker":"中","name":"Thiên Trung","zh":"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","py":"Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā.","vi":"Vậy mình đi tiệm hoa xem, giờ người mua hoa đông, mong là tiệm vẫn còn hoa đẹp."}]},{"titleZh":"课文二 · 在教室","titleVi":"Trong lớp — cô Nhất Phi đang dạy","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"王老师，今天的词比昨天多了十个。","py":"Wáng lǎoshī, jīntiān de cí bǐ zuótiān duōle shí ge.","vi":"Cô Vương ơi, từ hôm nay nhiều hơn hôm qua mười từ."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"是啊！你们都学会了吗？","py":"Shì a! Nǐmen dōu xuéhuìle ma?","vi":"Đúng thế! Các em học thuộc hết chưa?"},{"speaker":"妮","name":"Annie","zh":"学会了，没有问题。","py":"Xuéhuì le, méiyǒu wèntí.","vi":"Học được rồi ạ, không vấn đề gì."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"好。现在我来说，你们在本子上面写。","py":"Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmiàn xiě.","vi":"Tốt. Giờ cô đọc, các em viết vào vở."},{"gap":true,"zh":"……"},{"speaker":"飞","name":"Cô Nhất Phi","zh":"同学们，\"洗手间\"的\"间\"字写错了，它的里面是\"日\"，不是\"口\"。","py":"Tóngxuémen, \"xǐshǒujiān\" de \"jiān\" zì xiěcuò le, tā de lǐmiàn shì \"rì\", bú shì \"kǒu\".","vi":"Các em, chữ \"间\" trong \"洗手间\" viết sai rồi, bên trong là \"日\", không phải \"口\"."},{"speaker":"月","name":"Gia Nguyệt","zh":"\"日\"比\"口\"多一笔，写\"口\"就是\"问题\"的\"问\"了。","py":"\"Rì\" bǐ \"kǒu\" duō yì bǐ, xiě \"kǒu\" jiù shì \"wèntí\" de \"wèn\" le.","vi":"\"日\" nhiều hơn \"口\" một nét, viết \"口\" thì thành chữ \"问\" trong \"问题\" mất."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"没错，你说得很对。","py":"Méi cuò, nǐ shuō de hěn duì.","vi":"Đúng rồi, em nói rất đúng."}]},{"titleZh":"课文三 · 在教室","titleVi":"Trong lớp — quyển vở mới của Annie","lines":[{"speaker":"妮","name":"Annie","zh":"家月，你觉得这个本子怎么样？","py":"Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?","vi":"Gia Nguyệt, cậu thấy quyển vở này thế nào?"},{"speaker":"月","name":"Gia Nguyệt","zh":"很漂亮，多少钱一个？","py":"Hěn piàoliang, duōshao qián yí ge?","vi":"Đẹp lắm, bao nhiêu tiền một quyển?"},{"speaker":"妮","name":"Annie","zh":"比我们一起买的那个本子贵一点儿。","py":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.","vi":"Đắt hơn quyển bọn mình mua cùng nhau một chút."},{"speaker":"月","name":"Gia Nguyệt","zh":"这么漂亮的本子，不可能贵一点儿吧？","py":"Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?","vi":"Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút được nhỉ?"},{"speaker":"妮","name":"Annie","zh":"我是上网买的，真没那么贵。我买了两个，送你一个。","py":"Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎile liǎng ge, sòng nǐ yí ge.","vi":"Mình mua trên mạng, thật sự không đắt thế đâu. Mình mua hai quyển, tặng cậu một quyển."},{"speaker":"月","name":"Gia Nguyệt","zh":"谢谢！那我送给你什么呢？","py":"Xièxie! Nà wǒ sòng gěi nǐ shénme ne?","vi":"Cảm ơn cậu! Vậy mình tặng cậu cái gì đây?"},{"speaker":"妮","name":"Annie","zh":"咖啡杯吧，我最喜欢喝咖啡了。","py":"Kāfēibēi ba, wǒ zuì xǐhuan hē kāfēi le.","vi":"Cốc cà phê đi, mình thích uống cà phê nhất."},{"speaker":"月","name":"Gia Nguyệt","zh":"好，那样我们就都有新年礼物了！","py":"Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","vi":"Được, như vậy cả hai đều có quà năm mới rồi!"}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Gia Nguyệt","para":true,"speaker":"月","lines":[{"zh":"新年就要到了，安妮送给我一个新本子。","py":"Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí ge xīn běnzi.","vi":"Năm mới sắp đến rồi, Annie tặng mình một quyển vở mới."},{"zh":"她告诉我是在网上买的，比我的本子贵一点儿。","py":"Tā gàosu wǒ shì zài wǎngshang mǎi de, bǐ wǒ de běnzi guì yìdiǎnr.","vi":"Cậu ấy bảo mình là mua trên mạng, đắt hơn vở của mình một chút."},{"zh":"我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","py":"Wǒmen bān tóngxué yě sòngle Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò ge xīnnián.","vi":"Các bạn lớp mình cũng tặng cô Vương những bông hoa đẹp, mong cô đón một năm mới thật vui vẻ."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Tặng quà năm mới · Mời đến nhà","q":{"zh":"新年就要到了，两人一组，互相送礼物，再请对方来家里玩。","py":"Xīnnián jiù yào dào le, liǎng rén yì zǔ, hùxiāng sòng lǐwù, zài qǐng duìfāng lái jiā li wán.","vi":"Năm mới sắp đến, theo cặp: tặng quà cho nhau, rồi mời bạn đến nhà chơi."},"items":[{"lines":[{"who":"A","zh":"就要过新年了，我送你一个小礼物。","py":"Jiù yào guò xīnnián le, wǒ sòng nǐ yí ge xiǎo lǐwù.","vi":"Sắp đón năm mới rồi, mình tặng bạn một món quà nhỏ."},{"who":"B","zh":"这么好啊，你还给我准备了礼物。","py":"Zhème hǎo a, nǐ hái gěi wǒ zhǔnbèi le lǐwù.","vi":"Bạn tốt quá, còn chuẩn bị quà cho mình nữa."}]},{"zh":"这是送给你的花，希望你喜欢。—— 真漂亮！","py":"Zhè shì sòng gěi nǐ de huā, xīwàng nǐ xǐhuan. —— Zhēn piàoliang!","vi":"Đây là hoa tặng bạn, mong bạn thích. — Đẹp quá!"},{"zh":"新年那天来我家玩吧！—— 好啊，我几点去？","py":"Xīnnián nà tiān lái wǒ jiā wán ba! —— Hǎo a, wǒ jǐ diǎn qù?","vi":"Hôm năm mới đến nhà mình chơi nhé! — Được, mấy giờ mình đến?"}]}],"speak":[]}},{"id":"k2v3-b14","courseId":"k2v3","order":14,"title":"Một mình đón Tết chán biết bao","titleZh":"一个人过年多没意思啊","titlePy":"yí ge rén guònián duō méi yìsi a","vocab":[{"stt":1,"hanzi":"站","pinyin":"zhàn","hanviet":"Trạm","pos":"Động từ","meaning":"đứng","comps":"站着 (đang đứng), 站起来 (đứng dậy)","example":{"zh":"别站着，坐吧。","py":"Bié zhànzhe, zuò ba.","vi":"Đừng đứng nữa, ngồi đi."}},{"stt":2,"hanzi":"包","pinyin":"bāo","hanviet":"Bao","pos":"Danh từ / Động từ / Lượng từ","meaning":"túi; gói, bọc; (lượng từ) gói","comps":"书包 (cặp sách), 包饺子 (gói sủi cảo), 一包茶 (một gói trà)","example":{"zh":"这个包是新买的。","py":"Zhège bāo shì xīn mǎi de.","vi":"Chiếc túi này mới mua."}},{"stt":3,"hanzi":"过年","pinyin":"guònián","hanviet":"Quá niên","pos":"Động từ","meaning":"ăn Tết, đón năm mới","comps":"回家过年 (về nhà ăn Tết), 过年好 (chúc mừng năm mới)","example":{"zh":"今年我回家过年。","py":"Jīnnián wǒ huí jiā guònián.","vi":"Năm nay mình về nhà ăn Tết."}},{"stt":4,"hanzi":"没意思","pinyin":"méi yìsi","hanviet":"Một ý tứ","pos":"Cụm từ","meaning":"chán, vô vị","comps":"真没意思 (chán thật), 有意思 (thú vị — bài 8)","example":{"zh":"这个电影真没意思。","py":"Zhège diànyǐng zhēn méi yìsi.","vi":"Bộ phim này chán thật."}},{"stt":5,"hanzi":"位","pinyin":"wèi","hanviet":"Vị","pos":"Lượng từ","meaning":"vị (lượng từ kính trọng chỉ người)","comps":"这位老师 (vị thầy này), 几位 (mấy vị)","example":{"zh":"请问，您几位？","py":"Qǐngwèn, nín jǐ wèi?","vi":"Xin hỏi, quý khách đi mấy người ạ?"}},{"stt":6,"hanzi":"前面","pinyin":"qiánmiàn","hanviet":"Tiền diện","pos":"Danh từ","meaning":"phía trước","comps":"在前面 (ở phía trước), 前面那个楼 (toà nhà phía trước)","example":{"zh":"车站就在前面。","py":"Chēzhàn jiù zài qiánmiàn.","vi":"Bến xe ở ngay phía trước."}},{"stt":7,"hanzi":"房子","pinyin":"fángzi","hanviet":"Phòng tử","pos":"Danh từ","meaning":"nhà, căn nhà","comps":"买房子 (mua nhà), 大房子 (nhà to)","example":{"zh":"他们家的房子很大。","py":"Tāmen jiā de fángzi hěn dà.","vi":"Nhà của họ rất rộng."}},{"stt":8,"hanzi":"小孩儿","pinyin":"xiǎoháir","hanviet":"Tiểu hài nhi","pos":"Danh từ","meaning":"trẻ con","comps":"两个小孩儿 (hai đứa trẻ), 小孩儿们 (bọn trẻ)","example":{"zh":"外面有很多小孩儿在玩。","py":"Wàimiàn yǒu hěn duō xiǎoháir zài wán.","vi":"Bên ngoài có nhiều trẻ con đang chơi."}},{"stt":9,"hanzi":"女孩儿","pinyin":"nǚháir","hanviet":"Nữ hài nhi","pos":"Danh từ","meaning":"bé gái, cô gái","comps":"一个女孩儿 (một bé gái), 男孩儿 (bé trai — bài 9)","example":{"zh":"那个女孩儿是我妹妹。","py":"Nàge nǚháir shì wǒ mèimei.","vi":"Cô bé kia là em gái mình."}},{"stt":10,"hanzi":"姓","pinyin":"xìng","hanviet":"Tính","pos":"Động từ","meaning":"họ (là)","comps":"姓王 (họ Vương), 您贵姓 (ông/bà họ gì)","example":{"zh":"我姓李，叫李明。","py":"Wǒ xìng Lǐ, jiào Lǐ Míng.","vi":"Tôi họ Lý, tên là Lý Minh."}},{"stt":11,"hanzi":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn tinh","pos":"Danh từ","meaning":"mắt","comps":"大眼睛 (mắt to), 眼睛很漂亮 (mắt rất đẹp)","example":{"zh":"她的眼睛很大。","py":"Tā de yǎnjing hěn dà.","vi":"Mắt cô ấy rất to."}},{"stt":12,"hanzi":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","pos":"Động từ","meaning":"nhảy, múa","comps":"喜欢跳舞 (thích nhảy), 跳舞跳得好 (nhảy giỏi)","example":{"zh":"我妹妹很喜欢跳舞。","py":"Wǒ mèimei hěn xǐhuan tiàowǔ.","vi":"Em gái mình rất thích nhảy."}}],"hanzi":[{"char":"站","pinyin":"zhàn","hanviet":"Trạm","chars":["站"],"story":"站 = 立 (người dang chân đứng trên mặt đất) + 占 zhàn chỉ âm → đứng. Bài 12 là danh từ \"trạm, bến\" (chỗ đứng đợi xe)."},{"char":"包","pinyin":"bāo","hanviet":"Bao","chars":["包"],"story":"包 = 勹 (vòng tay ôm) + 巳 (bào thai): bào thai được bọc trong bụng mẹ → bọc, gói → túi: 书包, 包饺子."},{"char":"过年","pinyin":"guònián","hanviet":"Quá niên","chars":["过","年"],"story":"过 = 辶 (bước đi) + 寸 → đi qua, trải qua, đón (过生日 bài 6). 年 = năm. 过年 = đón năm mới, ăn Tết."},{"char":"没意思","pinyin":"méi yìsi","hanviet":"Một ý tứ","chars":["没","意","思"],"story":"没 = không có. 意 = 音 (âm) + 心 (lòng): tiếng lòng → ý. 思 = 田 + 心 → nghĩ. 意思 = ý nghĩa, thú vị → 没意思 = chán."},{"char":"位","pinyin":"wèi","hanviet":"Vị","chars":["位"],"story":"位 = 亻 (người) + 立 (đứng): chỗ người đứng → vị trí. Làm lượng từ chỉ người một cách lịch sự: 这位老师."},{"char":"前面","pinyin":"qiánmiàn","hanviet":"Tiền diện","chars":["前","面"],"story":"前 (phồn thể 歬 = 止 bàn chân + 舟 thuyền): chân đứng trên thuyền tiến về phía trước → trước. 面 = phía. 前面 = phía trước."},{"char":"房子","pinyin":"fángzi","hanviet":"Phòng tử","chars":["房","子"],"story":"房 = 户 (cửa một cánh) + 方 fāng chỉ âm → phòng, nhà. 子 là hậu tố, đọc nhẹ. 房子 = căn nhà."},{"char":"小孩儿","pinyin":"xiǎoháir","hanviet":"Tiểu hài nhi","chars":["小","孩","儿"],"story":"孩 = 子 (đứa trẻ) + 亥 hài chỉ âm → trẻ nhỏ. 儿 nhi hoá: xiǎoháir. 小孩儿 = trẻ con."},{"char":"女孩儿","pinyin":"nǚháir","hanviet":"Nữ hài nhi","chars":["女","孩","儿"],"story":"女 vẽ người phụ nữ ngồi khoanh tay. 孩儿 = đứa trẻ. 女孩儿 = bé gái; cặp với 男孩儿 (bài 9)."},{"char":"姓","pinyin":"xìng","hanviet":"Tính","chars":["姓"],"story":"姓 = 女 (người mẹ) + 生 (sinh ra): thời xưa con mang họ mẹ → họ. 您贵姓？ = Ông/bà họ gì ạ?"},{"char":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn tinh","chars":["眼","睛"],"story":"眼 = 目 (mắt) + 艮 gèn chỉ âm → con mắt. 睛 = 目 + 青 qīng chỉ âm → tròng mắt (nhóm 青: 请 · 晴 · 睛). 眼睛 = mắt."},{"char":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","chars":["跳","舞"],"story":"跳 = 足 (chân) + 兆 zhào chỉ âm → nhảy bật lên. 舞 vẽ người cầm đồ vật múa, dưới là 舛 (hai bàn chân) → múa. 跳舞 = nhảy múa."}],"grammar":[{"title":"Câu tồn hiện (2): nơi chốn + ĐT + 着 + người / vật","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>处所</b><small>nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>人 / 事物</b><small>không xác định</small></span></div>","summary":"<p class=\"gr-lead\">Nơi chốn + ĐT 着 + người/vật</p><ul><li>Đầu câu là <b>nơi chốn</b>, cuối câu là người / vật <b>không xác định</b>: <span class=\"zh\">一个人、不少学生</span>.</li></ul>","note":"<b>Lưu ý:</b> Không thêm <span class=\"zh\">在</span> ở đầu câu: ✗ <span class=\"zh\">在楼下站着一个人</span> → ✓ <span class=\"zh\">楼下站着一个人</span>.","examples":[{"zh":"你家楼下站着一个人。","py":"Nǐ jiā lóu xià zhànzhe yí ge rén.","vi":"Dưới nhà cô có một người đang đứng."},{"zh":"爸爸手里拿着一杯咖啡。","py":"Bàba shǒuli názhe yì bēi kāfēi.","vi":"Trên tay bố đang cầm một cốc cà phê."},{"zh":"那间教室里坐着不少学生。","py":"Nà jiān jiàoshì li zuòzhe bù shǎo xuésheng.","vi":"Trong phòng học kia có khá nhiều học sinh đang ngồi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">楼下____，他说他是来找你的。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好，我下去看看。</span></span></span><span class=\"qz-hint\">Dưới nhà có một người đang đứng, anh ấy nói đến tìm bạn. — Được, mình xuống xem.</span>","answer":["站着一个人","站着个人","站着一个男人"],"explain":"楼下站着一个人，他说他是来找你的。 (Lóu xià zhànzhe yí ge rén, tā shuō tā shì lái zhǎo nǐ de.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">天中，你的椅子上____，你认识他吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">不认识，我们过去问问他。</span></span></span><span class=\"qz-hint\">Thiên Trung, trên ghế của cậu có một người đang ngồi, cậu quen không? — Không quen, mình qua hỏi thử xem.</span>","answer":["坐着一个人","坐着个人"],"explain":"天中，你的椅子上坐着一个人，你认识他吗？ (Tiānzhōng, nǐ de yǐzi shang zuòzhe yí ge rén, nǐ rènshi tā ma?)"}]},{"title":"Phó từ mức độ 多 (câu cảm thán)","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>多</b><small>biết bao</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 没意思…</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>啊！</b></span></div>","summary":"<p class=\"gr-lead\">多 + Tính từ + 啊！</p><ul><li><span class=\"zh\">多……啊！</span> dùng trong câu <b>cảm thán</b> = \"… biết bao, … quá!\". Khác <span class=\"zh\">多</span> số ước lượng (bài 2): <span class=\"zh\">二十多个</span>.</li></ul>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">多</span> không thêm <span class=\"zh\">很</span>: ✗ <span class=\"zh\">多很好啊</span> → ✓ <span class=\"zh\">多好啊</span>.","examples":[{"zh":"你一个人在这儿多没意思啊！","py":"Nǐ yí ge rén zài zhèr duō méi yìsi a!","vi":"Em ở đây một mình chán biết bao!"},{"zh":"我们一起去多好啊！","py":"Wǒmen yìqǐ qù duō hǎo a!","vi":"Chúng mình cùng đi thì hay biết bao!"},{"zh":"多好看啊！买这件吧。","py":"Duō hǎokàn a! Mǎi zhè jiàn ba.","vi":"Đẹp quá! Mua chiếc này đi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你这本书____啊！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是很新，可能没人爱看吧。</span></span></span><span class=\"qz-hint\">Quyển sách này của bạn mới quá! — Mới thật, chắc vì chẳng ai thích đọc.</span>","answer":["多新"],"explain":"你这本书多新啊！ (Nǐ zhè běn shū duō xīn a!)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你看，孩子们____啊！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，他们最喜欢在外边玩了。</span></span></span><span class=\"qz-hint\">Bạn xem, bọn trẻ chơi vui biết bao! — Đúng thế, chúng thích chơi ngoài trời nhất.</span>","answer":["玩得多高兴","玩儿得多高兴","玩得多开心"],"explain":"你看，孩子们玩得多高兴啊！ (Nǐ kàn, háizimen wán de duō gāoxìng a!)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">别买了，这块手表____！</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没关系，你喜欢就买。</span></span></span><span class=\"qz-hint\">Đừng mua nữa, chiếc đồng hồ này đắt quá! — Không sao, em thích thì mua.</span>","answer":["多贵啊","多贵"],"explain":"别买了，这块手表多贵啊！ (Bié mǎi le, zhè kuài shǒubiǎo duō guì a!)"}]},{"title":"Bổ ngữ xu hướng kép (复合趋向补语)","formula":"<div class=\"fx-lbl\">Cơ bản</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>上/下/进/出/回/过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span></div><div class=\"fx-ex zh\">楼不高，我们走上去吧。</div><div class=\"fx-lbl\">起来</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起来</b></span></div><div class=\"fx-ex zh\">他就站起来了。</div>","summary":"<p class=\"gr-lead\">ĐT + 上/下/进… + 来/去</p><ul><li><span class=\"zh\">来</span> = về phía người nói, <span class=\"zh\">去</span> = ra xa người nói (như bài 5).</li><li><span class=\"zh\">起来</span> = động tác hướng lên: <span class=\"zh\">站起来</span> (đứng dậy).</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">复合趋向补语</span> · Có tân ngữ</h4><p>Vị trí tân ngữ</p><div class=\"gr-formula\"><div class=\"fx-lbl\">TN nơi chốn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>出/进/回…</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>地点</b><small>nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span></div><div class=\"fx-ex zh\">同学们都走出教室去了。</div><div class=\"fx-lbl\">TN sự vật ①</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>出/回…</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>事物</b><small>sự vật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span></div><div class=\"fx-ex zh\">妈妈让我买回一些菜来。</div><div class=\"fx-lbl\">TN sự vật ②</div><div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>出/回…</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来 / 去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>事物</b><small>sự vật</small></span></div><div class=\"fx-ex zh\">她找出来一个漂亮的本子。</div></div><p class=\"gr-key\">TN nơi chốn luôn đứng <b>trước</b> 来/去: ✗ <span class=\"zh\">走出去教室</span> → ✓ <span class=\"zh\">走出教室去</span></p></div>","note":"","examples":[{"zh":"她经常跑上来找我玩。","py":"Tā jīngcháng pǎo shànglái zhǎo wǒ wán.","vi":"Bé hay chạy lên tìm cô chơi."},{"zh":"楼不高，我们走上去吧。","py":"Lóu bù gāo, wǒmen zǒu shàngqù ba.","vi":"Nhà không cao, mình đi bộ lên đi."},{"zh":"一听到老师叫他的名字，他就站起来了。","py":"Yì tīngdào lǎoshī jiào tā de míngzi, tā jiù zhàn qǐlái le.","vi":"Vừa nghe cô gọi tên, cậu ấy liền đứng dậy."},{"zh":"同学们都走出教室去了。","py":"Tóngxuémen dōu zǒuchū jiàoshì qù le.","vi":"Các bạn đều đi ra khỏi lớp rồi."},{"zh":"妈妈让我买回一些菜来。","py":"Māma ràng wǒ mǎihuí yìxiē cài lái.","vi":"Mẹ bảo mình mua ít rau về."},{"zh":"白家月从书包里找出来一个漂亮的本子。","py":"Bái Jiāyuè cóng shūbāo li zhǎo chūlái yí ge piàoliang de běnzi.","vi":"Gia Nguyệt lấy từ trong cặp ra một quyển vở đẹp."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小雪呢？她不去商场吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">她早都____了，在楼下等我们呢。</span></span></span><span class=\"qz-hint\">Tiểu Tuyết đâu? Con bé không đi trung tâm thương mại à? — Con bé xuống từ lâu rồi, đang đợi mình dưới nhà.</span>","answer":["走下去","下去"],"explain":"她早都走下去了，在楼下等我们呢。 (Tā zǎo dōu zǒu xiàqù le, zài lóu xià děng wǒmen ne.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">包里是什么东西，快____吧。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">就是些吃的、喝的，还能有什么？</span></span></span><span class=\"qz-hint\">Trong túi có gì thế, mau lấy ra đi. — Chỉ là ít đồ ăn đồ uống thôi, còn có gì nữa đâu?</span>","answer":["拿出来"],"explain":"包里是什么东西，快拿出来吧。 (Bāo li shì shénme dōngxi, kuài ná chūlái ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">家月病了，我买了点儿药，现在给她____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">你等我一下，我跟你一起过去。</span></span></span><span class=\"qz-hint\">Gia Nguyệt ốm rồi, mình mua ít thuốc, giờ mang qua cho cậu ấy. — Đợi mình chút, mình qua cùng cậu.</span>","answer":["送过去","送去"],"explain":"家月病了，我买了点儿药，现在给她送过去。 (Jiāyuè bìng le, wǒ mǎile diǎnr yào, xiànzài gěi tā sòng guòqù.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在回家路上","titleVi":"Trên đường về nhà — ai đứng dưới nhà?","lines":[{"speaker":"文","name":"Lý Văn","zh":"王老师，你家楼下站着一个人。","py":"Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí ge rén.","vi":"Cô Vương ơi, dưới nhà cô có một người đang đứng."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"我家楼下？我看看。","py":"Wǒ jiā lóu xià? Wǒ kànkan.","vi":"Dưới nhà cô à? Để cô xem."},{"speaker":"文","name":"Lý Văn","zh":"那个人穿着黑色的裤子，手里还拿着一个黑色的包。","py":"Nàge rén chuānzhe hēisè de kùzi, shǒuli hái názhe yí ge hēisè de bāo.","vi":"Người đó mặc quần đen, tay còn cầm một chiếc túi đen."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"我看见那个人了，他是我男朋友。","py":"Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou.","vi":"Cô thấy người đó rồi, là bạn trai cô đấy."},{"speaker":"文","name":"Lý Văn","zh":"那我们快过去吧。","py":"Nà wǒmen kuài guòqù ba.","vi":"Vậy mình mau qua đó đi ạ."}]},{"titleZh":"课文二 · 在楼下","titleVi":"Dưới toà nhà — gặp Đồng Lạc","lines":[{"speaker":"飞","name":"Cô Nhất Phi","zh":"同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了！","py":"Tónglè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le!","vi":"Đồng Lạc, đúng là anh rồi! Lần trước gọi điện anh nói rảnh sẽ qua thăm em, không ngờ đến nhanh thế!"},{"speaker":"乐","name":"Đồng Lạc","zh":"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。","py":"Jiù yào guònián le, nǐ yí ge rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le.","vi":"Sắp Tết rồi, em ở đây một mình chán biết bao, nên anh qua sớm."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"你能来，我太高兴了！","py":"Nǐ néng lái, wǒ tài gāoxìng le!","vi":"Anh đến được, em vui quá!"},{"speaker":"乐","name":"Đồng Lạc","zh":"一飞，你旁边这位是？","py":"Yīfēi, nǐ pángbiān zhè wèi shì?","vi":"Nhất Phi, vị bên cạnh em đây là…?"},{"speaker":"飞","name":"Cô Nhất Phi","zh":"同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","py":"Tónglè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tónglè.","vi":"Đồng Lạc, đây là Lý Văn, cậu ấy học y ở trường em. Lý Văn, đây là bạn trai cô, Dương Đồng Lạc."},{"speaker":"乐","name":"Đồng Lạc","zh":"李文，很高兴认识你！","py":"Lǐ Wén, hěn gāoxìng rènshi nǐ!","vi":"Lý Văn, rất vui được làm quen với cậu!"},{"speaker":"文","name":"Lý Văn","zh":"认识你我也很高兴！我家就在前面那个楼，有时间来玩。","py":"Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmiàn nàge lóu, yǒu shíjiān lái wán.","vi":"Em cũng rất vui được quen anh! Nhà em ở ngay toà nhà phía trước kia, rảnh anh đến chơi ạ."}]},{"titleZh":"课文三 · 在王一飞家里","titleVi":"Phòng khách nhà cô Nhất Phi","lines":[{"speaker":"乐","name":"Đồng Lạc","zh":"一飞，你住的房子真不错，很大，离学校也不远。","py":"Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn.","vi":"Nhất Phi, nhà em ở đẹp thật đấy, rất rộng, cách trường cũng không xa."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"是啊！我楼下还住着一家中国人，他们人很好。","py":"Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguó rén, tāmen rén hěn hǎo.","vi":"Vâng! Dưới nhà em còn có một gia đình người Trung Quốc, họ rất tốt."},{"speaker":"乐","name":"Đồng Lạc","zh":"这样你有事情就可以找他们帮忙。","py":"Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng.","vi":"Như vậy em có việc gì thì có thể nhờ họ giúp."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"对，我也帮他们家的小孩儿学中文。","py":"Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","vi":"Đúng, em cũng giúp con nhà họ học tiếng Trung."},{"speaker":"乐","name":"Đồng Lạc","zh":"我记得你跟我说过，是个女孩儿，学得也很好。","py":"Wǒ jìde nǐ gēn wǒ shuōguo, shì ge nǚháir, xué de yě hěn hǎo.","vi":"Anh nhớ em từng kể, là một bé gái, học cũng rất giỏi."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"没错，她经常跑上来找我玩。","py":"Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","vi":"Đúng rồi, bé hay chạy lên tìm em chơi."},{"speaker":"乐","name":"Đồng Lạc","zh":"你问问他们什么时候有时间，我请他们吃个饭。","py":"Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī ge fàn.","vi":"Em hỏi xem khi nào họ rảnh, anh mời họ một bữa cơm."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký cô Nhất Phi","para":true,"speaker":"飞","lines":[{"zh":"我男朋友姓杨，叫杨同乐。","py":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","vi":"Bạn trai tôi họ Dương, tên là Dương Đồng Lạc."},{"zh":"他高个子、大眼睛，唱歌唱得很好，跳舞跳得也不错。","py":"Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò.","vi":"Anh ấy cao ráo, mắt to, hát rất hay, nhảy cũng khá."},{"zh":"他和我姐姐一起工作，是姐姐介绍我们认识的。","py":"Tā hé wǒ jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de.","vi":"Anh ấy làm việc cùng chị gái tôi, chính chị giới thiệu chúng tôi quen nhau."},{"zh":"他告诉我，从见到我的第一天开始，他就喜欢上我了。","py":"Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuan shàng wǒ le.","vi":"Anh ấy nói với tôi rằng từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Xem nhà giúp bạn · Ưu & nhược","q":{"zh":"两人一组：帮朋友看房子，说说房子哪里好、哪里不好。","py":"Liǎng rén yì zǔ: bāng péngyou kàn fángzi, shuōshuo fángzi nǎlǐ hǎo, nǎlǐ bù hǎo.","vi":"Theo cặp: xem nhà giúp bạn, nói xem căn nhà tốt ở đâu, chưa tốt ở đâu."},"items":[{"lines":[{"who":"A","zh":"你帮我看看，这个房子怎么样？","py":"Nǐ bāng wǒ kànkan, zhège fángzi zěnmeyàng?","vi":"Bạn xem giúp mình, căn nhà này thế nào?"},{"who":"B","zh":"不错，房子很大，还有两个洗手间。","py":"Búcuò, fángzi hěn dà, hái yǒu liǎng ge xǐshǒujiān.","vi":"Được đấy, nhà rộng, còn có hai nhà vệ sinh."}]},{"zh":"楼下住着一家中国人，他们人很好。","py":"Lóu xià zhùzhe yì jiā Zhōngguó rén, tāmen rén hěn hǎo.","vi":"Dưới nhà có một gia đình người Trung Quốc, họ rất tốt."},{"zh":"离地铁站有点儿远，走过去要二十分钟。","py":"Lí dìtiězhàn yǒudiǎnr yuǎn, zǒu guòqù yào èrshí fēnzhōng.","vi":"Hơi xa ga tàu điện, đi bộ qua mất hai mươi phút."}]}],"speak":[]}},{"id":"k2v3-b15","courseId":"k2v3","order":15,"title":"Tôi muốn đi Trung Quốc thêm một lần nữa","titleZh":"我想再去一次中国","titlePy":"wǒ xiǎng zài qù yí cì Zhōngguó","vocab":[{"stt":1,"hanzi":"姓名","pinyin":"xìngmíng","hanviet":"Tính danh","pos":"Danh từ","meaning":"họ tên","comps":"写姓名 (ghi họ tên), 你的姓名 (họ tên của bạn)","example":{"zh":"请写上你的姓名。","py":"Qǐng xiě shàng nǐ de xìngmíng.","vi":"Mời ghi họ tên của bạn."}},{"stt":2,"hanzi":"出国","pinyin":"chūguó","hanviet":"Xuất quốc","pos":"Động từ","meaning":"ra nước ngoài","comps":"出国旅游 (du lịch nước ngoài), 出国学习 (đi du học)","example":{"zh":"他明年要出国学习。","py":"Tā míngnián yào chūguó xuéxí.","vi":"Sang năm anh ấy sẽ đi du học."}},{"stt":3,"hanzi":"门票","pinyin":"ménpiào","hanviet":"Môn phiếu","pos":"Danh từ","meaning":"vé vào cửa","comps":"买门票 (mua vé vào cửa), 门票多少钱 (vé bao nhiêu tiền)","example":{"zh":"这里的门票多少钱？","py":"Zhèlǐ de ménpiào duōshao qián?","vi":"Vé vào cửa ở đây bao nhiêu tiền?"}},{"stt":4,"hanzi":"高中","pinyin":"gāozhōng","hanviet":"Cao trung","pos":"Danh từ","meaning":"trung học phổ thông, cấp 3","comps":"高中同学 (bạn cấp 3), 上高中 (học cấp 3)","example":{"zh":"我们是高中同学。","py":"Wǒmen shì gāozhōng tóngxué.","vi":"Chúng mình là bạn cấp 3."}},{"stt":5,"hanzi":"出门","pinyin":"chūmén","hanviet":"Xuất môn","pos":"Động từ","meaning":"ra khỏi nhà; đi xa","comps":"出门旅游 (đi du lịch xa), 早上出门 (sáng ra khỏi nhà)","example":{"zh":"我每天早上七点出门。","py":"Wǒ měi tiān zǎoshang qī diǎn chūmén.","vi":"Sáng nào mình cũng ra khỏi nhà lúc bảy giờ."}},{"stt":6,"hanzi":"路","pinyin":"lù","hanviet":"Lộ","pos":"Danh từ","meaning":"đường","comps":"走路 (đi bộ), 这条路 (con đường này)","example":{"zh":"这条路车很多。","py":"Zhè tiáo lù chē hěn duō.","vi":"Con đường này rất đông xe."}},{"stt":7,"hanzi":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","pos":"Danh từ","meaning":"sân bay","comps":"去机场 (ra sân bay), 机场很远 (sân bay rất xa)","example":{"zh":"我送你去机场吧。","py":"Wǒ sòng nǐ qù jīchǎng ba.","vi":"Để mình đưa bạn ra sân bay nhé."}},{"stt":8,"hanzi":"机票","pinyin":"jīpiào","hanviet":"Cơ phiếu","pos":"Danh từ","meaning":"vé máy bay","comps":"买机票 (mua vé máy bay), 机票很便宜 (vé rất rẻ)","example":{"zh":"我在网上买了机票。","py":"Wǒ zài wǎngshang mǎile jīpiào.","vi":"Mình đã mua vé máy bay trên mạng."}},{"stt":9,"hanzi":"飞","pinyin":"fēi","hanviet":"Phi","pos":"Động từ","meaning":"bay","comps":"飞北京 (bay đi Bắc Kinh), 飞回来 (bay về)","example":{"zh":"我们明天飞北京。","py":"Wǒmen míngtiān fēi Běijīng.","vi":"Mai chúng mình bay đi Bắc Kinh."}},{"stt":10,"hanzi":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","pos":"Động từ","meaning":"giống như, hình như","comps":"好像要下雨 (hình như sắp mưa), 好像小鸟 (giống chú chim nhỏ)","example":{"zh":"天阴了，好像要下雨了。","py":"Tiān yīn le, hǎoxiàng yào xià yǔ le.","vi":"Trời âm u rồi, hình như sắp mưa."}},{"stt":11,"hanzi":"鸟","pinyin":"niǎo","hanviet":"Điểu","pos":"Danh từ","meaning":"chim","comps":"小鸟 (chim nhỏ), 一只鸟 (một con chim)","example":{"zh":"那只小鸟多漂亮啊！","py":"Nà zhī xiǎoniǎo duō piàoliang a!","vi":"Con chim nhỏ kia đẹp quá!"}},{"stt":12,"hanzi":"颐和园","pinyin":"Yíhé Yuán","hanviet":"Di Hoà Viên","pos":"Danh từ riêng","meaning":"Di Hoà Viên (Bắc Kinh)","comps":"去颐和园 (đi Di Hoà Viên), 颐和园的门票 (vé Di Hoà Viên)","example":{"zh":"颐和园在北京。","py":"Yíhé Yuán zài Běijīng.","vi":"Di Hoà Viên ở Bắc Kinh."}}],"hanzi":[{"char":"姓名","pinyin":"xìngmíng","hanviet":"Tính danh","chars":["姓","名"],"story":"姓 = 女 + 生: người mẹ sinh ra → họ (bài 14). 名 = 夕 (buổi tối) + 口 (miệng): tối trời không thấy mặt phải gọi tên → tên. 姓名 = họ tên."},{"char":"出国","pinyin":"chūguó","hanviet":"Xuất quốc","chars":["出","国"],"story":"出 vẽ bàn chân bước ra khỏi hố → ra. 国 = 囗 (biên giới) + 玉 (ngọc quý) → đất nước. 出国 = ra nước ngoài."},{"char":"门票","pinyin":"ménpiào","hanviet":"Môn phiếu","chars":["门","票"],"story":"门 = cánh cửa (bài 10). 票 = 覀 + 示 → tấm phiếu, vé (bài 2). 门票 = vé vào cửa."},{"char":"高中","pinyin":"gāozhōng","hanviet":"Cao trung","chars":["高","中"],"story":"高 vẽ toà lầu có mái cao → cao. 中 = giữa. 高中 = trung học bậc cao = cấp 3 (初中 = cấp 2)."},{"char":"出门","pinyin":"chūmén","hanviet":"Xuất môn","chars":["出","门"],"story":"出 = ra. 门 = cửa. Bước ra khỏi cửa → ra ngoài, đi xa: 出门旅游."},{"char":"路","pinyin":"lù","hanviet":"Lộ","chars":["路"],"story":"路 = 足 (chân) + 各 gè (ai nấy): con đường ai cũng bước qua → đường (đã gặp 路上 bài 11, 走路 bài 9)."},{"char":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","chars":["机","场"],"story":"机 = 木 (gỗ) + 几 jī chỉ âm → máy móc (飞机). 场 = 土 (đất) + 昜 → bãi đất rộng. 机场 = bãi cho máy bay = sân bay."},{"char":"机票","pinyin":"jīpiào","hanviet":"Cơ phiếu","chars":["机","票"],"story":"机 = máy bay (飞机). 票 = vé. 机票 = vé máy bay; cùng họ với 门票, 车票."},{"char":"飞","pinyin":"fēi","hanviet":"Phi","chars":["飞"],"story":"飞 vẽ đôi cánh chim đang vỗ trên không (phồn thể 飛 có hai cặp cánh) → bay. Chữ 飞 trong tên cô Nhất Phi 一飞."},{"char":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","chars":["好","像"],"story":"好 = tốt, rất. 像 = 亻 (người) + 象 (con voi): người vẽ con voi cho thật giống → giống. 好像 = giống như, hình như."},{"char":"鸟","pinyin":"niǎo","hanviet":"Điểu","chars":["鸟"],"story":"鸟 vẽ con chim nhìn nghiêng: chấm là con mắt, có mỏ, thân và đuôi (phồn thể 鳥). 小鸟 = chim nhỏ."},{"char":"颐和园","pinyin":"Yíhé Yuán","hanviet":"Di Hoà Viên","chars":["颐","和","园"],"story":"颐 = nuôi dưỡng, an dưỡng. 和 = hoà. 园 = 囗 (tường bao) + 元 yuán chỉ âm → vườn. 颐和园 = vườn \"dưỡng hoà\" — cung điện mùa hè của vua Thanh ở Bắc Kinh."}],"grammar":[{"title":"Bổ ngữ động lượng (1): ĐT + số + 次","formula":"<div class=\"fx-lbl\">Không TN</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(过 / 了)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数词 + 次</b></span></div><div class=\"fx-ex zh\">虽然去过一次，但是很想再去一次。</div><div class=\"fx-lbl\">Tên / địa danh ①</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(过 / 了)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数词 + 次</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>人名 / 地名</b></span></div><div class=\"fx-ex zh\">安妮去过一次北京。</div><div class=\"fx-lbl\">Tên / địa danh ②</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(过 / 了)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>人名 / 地名</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数词 + 次</b></span></div><div class=\"fx-ex zh\">李文见了杨同乐两次。</div>","summary":"<p class=\"gr-lead\">ĐT + số + 次</p><ul><li><span class=\"zh\">数词 + 次</span> sau động từ = làm <b>mấy lần</b>; <span class=\"zh\">过 / 了</span> đứng ngay sau động từ.</li></ul>","note":"<b>Lưu ý:</b> Số lần đứng <b>sau</b> động từ: ✗ <span class=\"zh\">我两次去过北京</span> → ✓ <span class=\"zh\">我去过两次北京</span>.","examples":[{"zh":"我想去中国，虽然去过一次，但是很想再去一次。","py":"Wǒ xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.","vi":"Em muốn đi Trung Quốc, tuy đã đi một lần nhưng rất muốn đi thêm lần nữa."},{"zh":"安妮去过一次北京。","py":"Ānnī qùguo yí cì Běijīng.","vi":"Annie đã đến Bắc Kinh một lần."},{"zh":"李文见了杨同乐两次。","py":"Lǐ Wén jiànle Yáng Tónglè liǎng cì.","vi":"Lý Văn đã gặp Dương Đồng Lạc hai lần."}],"exercises":[]},{"title":"Bổ ngữ động lượng (2): vị trí tân ngữ","formula":"<div class=\"fx-lbl\">TN sự vật</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数词 + 次</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>事物</b><small>sự vật</small></span></div><div class=\"fx-ex zh\">我想再吃一次烤鸭。</div><div class=\"fx-lbl\">TN đại từ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>代词</b><small>đại từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数词 + 次</b></span></div><div class=\"fx-ex zh\">我想找他一次。</div>","summary":"<p class=\"gr-lead\">Vị trí tân ngữ</p><ul><li>TN là <b>danh từ sự vật</b> → đứng <b>sau</b> <span class=\"zh\">次</span>; TN là <b>đại từ</b> (<span class=\"zh\">我、他、这儿</span>) → đứng <b>trước</b> <span class=\"zh\">次</span>.</li></ul>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">我想找一次他</span> → ✓ <span class=\"zh\">我想找他一次</span>.","examples":[{"zh":"因为我想再吃一次烤鸭，再喝一次奶茶。","py":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá.","vi":"Vì mình muốn ăn vịt quay thêm lần nữa, uống trà sữa thêm lần nữa."},{"zh":"我想找他一次。","py":"Wǒ xiǎng zhǎo tā yí cì.","vi":"Mình muốn tìm gặp anh ấy một lần."},{"zh":"安妮来过这儿两次。","py":"Ānnī láiguo zhèr liǎng cì.","vi":"Annie đã đến đây hai lần."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你们去北京的时候见到一雪姐姐了吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我们见了____两次，还去了一次她家。</span></span></span><span class=\"qz-hint\">Lúc đi Bắc Kinh các bạn có gặp chị Nhất Tuyết không? — Bọn mình gặp chị ấy hai lần, còn đến nhà chị một lần.</span>","answer":["她"],"explain":"我们见了她两次，还去了一次她家。 (Wǒmen jiànle tā liǎng cì, hái qùle yí cì tā jiā.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我每个星期给家里打两次电话。</span></span></span><span class=\"qz-hint\">Mỗi tuần bạn gọi điện về nhà mấy lần? — Mỗi tuần mình gọi về nhà hai lần.</span>","answer":["你每个星期给家里打几次电话","你每星期给家里打几次电话"],"explain":"你每个星期给家里打几次电话？ (Nǐ měi ge xīngqī gěi jiā li dǎ jǐ cì diànhuà?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">就下过一次雪。我觉得今年没有去年冷。</span></span></span><span class=\"qz-hint\">Năm nay có tuyết mấy lần rồi? — Mới có một lần. Mình thấy năm nay không lạnh bằng năm ngoái.</span>","answer":["今年下过几次雪","今年下了几次雪"],"explain":"今年下过几次雪？ (Jīnnián xiàguo jǐ cì xuě?)"}]},{"title":"Câu chữ 有 (2): 有 + cụm số lượng","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>有</b><small>được, tới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>数量短语</b><small>cụm số lượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b></span></div>","summary":"<p class=\"gr-lead\">有 + cụm số lượng</p><ul><li><span class=\"zh\">有 + số lượng</span> = <b>đạt tới</b> con số đó (\"được / tới …\"), hay dùng để hỏi, ước đoán: <span class=\"zh\">你女儿今年有10岁了吗？</span></li></ul>","note":"<b>Lưu ý:</b> Phủ định dùng <span class=\"zh\">没有 / 不到</span>: ✗ <span class=\"zh\">不有8000块</span> → ✓ <span class=\"zh\">没有8000块</span>.","examples":[{"zh":"你有一年没回国了吧？","py":"Nǐ yǒu yì nián méi huí guó le ba?","vi":"Cậu chưa về nước được một năm rồi nhỉ?"},{"zh":"你女儿今年有10岁了吗？","py":"Nǐ nǚ'ér jīnnián yǒu shí suì le ma?","vi":"Con gái chị năm nay được 10 tuổi chưa?"},{"zh":"我有一个月没给家里打电话了。","py":"Wǒ yǒu yí ge yuè méi gěi jiā li dǎ diànhuà le.","vi":"Đã một tháng nay mình không gọi điện về nhà."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">飞北京的机票____8000块钱吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没有，现在机票便宜。</span></span></span><span class=\"qz-hint\">Vé máy bay đi Bắc Kinh có tới 8000 tệ không? — Không đâu, giờ vé máy bay rẻ.</span>","answer":["有"],"explain":"飞北京的机票有8000块钱吗？ (Fēi Běijīng de jīpiào yǒu bāqiān kuài qián ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你男朋友____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没有，他今年29岁，比我还小一岁呢。</span></span></span><span class=\"qz-hint\">Bạn trai cậu được ba mươi tuổi chưa? — Chưa, năm nay anh ấy 29 tuổi, còn kém mình một tuổi.</span>","answer":["有三十岁了吗","有三十岁吗","有30岁了吗","有30岁吗"],"explain":"你男朋友有三十岁了吗？ (Nǐ nánpéngyou yǒu sānshí suì le ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们两个____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是啊，一年没见，你还是那样。</span></span></span><span class=\"qz-hint\">Hai đứa mình chưa gặp nhau được một năm rồi nhỉ? — Đúng thế, một năm không gặp, cậu vẫn như vậy.</span>","answer":["有一年没见了吧","有一年没见了"],"explain":"我们两个有一年没见了吧？ (Wǒmen liǎng ge yǒu yì nián méi jiàn le ba?)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp — các bạn đang làm bài thi","lines":[{"speaker":"飞","name":"Cô Nhất Phi","zh":"考试就要开始了，请大家写上姓名，写好后就可以做题了。","py":"Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiě shàng xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le.","vi":"Sắp bắt đầu thi rồi, mời các em ghi họ tên, ghi xong thì có thể làm bài."},{"gap":true,"zh":"……"},{"speaker":"月","name":"Gia Nguyệt","zh":"老师，我做完了。","py":"Lǎoshī, wǒ zuòwán le.","vi":"Thưa cô, em làm xong rồi ạ."},{"speaker":"中","name":"Thiên Trung","zh":"老师，我也做完了。","py":"Lǎoshī, wǒ yě zuòwán le.","vi":"Thưa cô, em cũng làm xong rồi ạ."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"……对了，你们考完试想做什么？","py":"…… Duìle, nǐmen kǎowán shì xiǎng zuò shénme?","vi":"…À phải rồi, thi xong các em định làm gì?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我很想去中国，虽然去过一次，但是很想再去一次。","py":"Wǒ hěn xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.","vi":"Em rất muốn đi Trung Quốc, tuy đã đi một lần rồi nhưng rất muốn đi thêm lần nữa."},{"speaker":"飞","name":"Cô Nhất Phi","zh":"不错，到中国后你就可以经常说中文了。","py":"Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le.","vi":"Hay đấy, đến Trung Quốc rồi em có thể thường xuyên nói tiếng Trung."}]},{"titleZh":"课文二 · 在咖啡店","titleVi":"Quán cà phê — kế hoạch đi Bắc Kinh","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"考完试了，我现在可以出国旅游了。","py":"Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","vi":"Thi xong rồi, giờ mình có thể đi du lịch nước ngoài rồi."},{"speaker":"文","name":"Lý Văn","zh":"你要去哪儿？","py":"Nǐ yào qù nǎr?","vi":"Cậu định đi đâu?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我要再去一次北京。","py":"Wǒ yào zài qù yí cì Běijīng.","vi":"Mình sẽ đi Bắc Kinh thêm một lần nữa."},{"speaker":"文","name":"Lý Văn","zh":"为什么还去北京？","py":"Wèi shénme hái qù Běijīng?","vi":"Sao lại đi Bắc Kinh nữa?"},{"speaker":"月","name":"Gia Nguyệt","zh":"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","py":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng……","vi":"Vì mình muốn ăn vịt quay, uống trà sữa, đến Đại học Bắc Kinh xem phim thêm lần nữa…"},{"speaker":"文","name":"Lý Văn","zh":"你想做的事情很多啊！","py":"Nǐ xiǎng zuò de shìqing hěn duō a!","vi":"Cậu muốn làm nhiều việc thật đấy!"},{"speaker":"月","name":"Gia Nguyệt","zh":"是啊，你看，我还在网上买好颐和园的门票了呢。","py":"Shì a, nǐ kàn, wǒ hái zài wǎngshang mǎihǎo Yíhé Yuán de ménpiào le ne.","vi":"Đúng thế, cậu xem, mình còn mua sẵn vé Di Hoà Viên trên mạng rồi đây."},{"speaker":"文","name":"Lý Văn","zh":"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","py":"Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohǎo jièshào jièshào.","vi":"Bạn cấp 3 của mình làm ngay ở Di Hoà Viên, có thể nhờ cậu ấy giới thiệu kỹ cho cậu."},{"speaker":"月","name":"Gia Nguyệt","zh":"太好了！出门旅游，多个朋友多条路。","py":"Tài hǎo le! Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","vi":"Tuyệt quá! Đi xa, thêm một người bạn là thêm một con đường."}]},{"titleZh":"课文三 · 在咖啡店","titleVi":"Quán cà phê — chuyện vé máy bay","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"李文，你有一年没回国了吧？","py":"Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?","vi":"Lý Văn, cậu chưa về nước được một năm rồi nhỉ?"},{"speaker":"文","name":"Lý Văn","zh":"不到一年。我六月的时候回去了一次。","py":"Bú dào yì nián. Wǒ Liùyuè de shíhou huíqùle yí cì.","vi":"Chưa đến một năm. Tháng sáu mình có về một lần."},{"speaker":"月","name":"Gia Nguyệt","zh":"我怎么忘了？还是我送你去的机场呢。","py":"Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne.","vi":"Sao mình lại quên nhỉ? Chính mình còn đưa cậu ra sân bay cơ mà."},{"speaker":"文","name":"Lý Văn","zh":"是啊。","py":"Shì a.","vi":"Đúng thế."},{"speaker":"月","name":"Gia Nguyệt","zh":"我记得你那次的机票很便宜。","py":"Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","vi":"Mình nhớ lần đó vé máy bay của cậu rất rẻ."},{"speaker":"文","name":"Lý Văn","zh":"没错，可能因为那个时候去北京的人不多吧。","py":"Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba.","vi":"Đúng rồi, có lẽ vì lúc đó người đi Bắc Kinh không nhiều."},{"speaker":"月","name":"Gia Nguyệt","zh":"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","py":"Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de.","vi":"Vé lần này tuy hơi đắt nhưng nghĩ đến sắp bay đi Bắc Kinh, mình vẫn rất vui."}]},{"titleZh":"课文四 · 在房间","titleVi":"Trong phòng — nhật ký Lý Văn","para":true,"speaker":"文","lines":[{"zh":"我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。","py":"Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā.","vi":"Tháng sáu mình có về Bắc Kinh một lần, giờ đã hơn nửa năm chưa về, mình hơi nhớ nhà."},{"zh":"就要过年了，我要回家过年。","py":"Jiù yào guònián le, wǒ yào huí jiā guònián.","vi":"Sắp Tết rồi, mình sẽ về nhà ăn Tết."},{"zh":"家月这次也要去北京，我们都是星期五的飞机。","py":"Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī.","vi":"Lần này Gia Nguyệt cũng đi Bắc Kinh, bọn mình đều bay chuyến thứ Sáu."},{"zh":"家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","py":"Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēidào Běijīng, zài yìqǐ fēihuí zhèlǐ.","vi":"Gia Nguyệt nói bọn mình giống như những chú chim nhỏ, cùng bay đến Bắc Kinh rồi lại cùng bay về đây."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Kể chuyện du lịch · Đi mấy lần?","q":{"zh":"两人一组，说说你的旅游：去过哪里、去过几次、吃得怎么样、玩得怎么样。","py":"Liǎng rén yì zǔ, shuōshuo nǐ de lǚyóu: qùguo nǎlǐ, qùguo jǐ cì, chī de zěnmeyàng, wán de zěnmeyàng.","vi":"Theo cặp, kể về chuyến du lịch: đã đi đâu, mấy lần, ăn thế nào, chơi thế nào."},"items":[{"lines":[{"who":"A","zh":"你去过北京吗？","py":"Nǐ qùguo Běijīng ma?","vi":"Bạn đi Bắc Kinh bao giờ chưa?"},{"who":"B","zh":"去过。","py":"Qùguo.","vi":"Đi rồi."}]},{"zh":"你去过几次？—— 去过两次，第一次是上高中的时候。","py":"Nǐ qùguo jǐ cì? —— Qùguo liǎng cì, dì-yī cì shì shàng gāozhōng de shíhou.","vi":"Bạn đi mấy lần rồi? — Hai lần, lần đầu là hồi học cấp 3."},{"zh":"吃得怎么样？—— 吃得很好，烤鸭多好吃啊！","py":"Chī de zěnmeyàng? —— Chī de hěn hǎo, kǎoyā duō hǎochī a!","vi":"Ăn uống thế nào? — Ăn rất ngon, vịt quay ngon biết bao!"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 11–15 · Nơi tôi thích nhất","prep":3,"talk":2,"q":{"zh":"请你说说你最喜欢的一个地方。","py":"Qǐng nǐ shuōshuo nǐ zuì xǐhuan de yí ge dìfang.","vi":"Hãy kể về một nơi bạn thích nhất."},"frame":[{"lbl":"开头","zh":"我最喜欢的地方是……，我去过……次。","py":"Wǒ zuì xǐhuan de dìfang shì ……, wǒ qùguo …… cì.","vi":"Nơi mình thích nhất là …, mình đã đến … lần.","ex":{"zh":"我最喜欢的地方是北京，我去过两次。","py":"Wǒ zuì xǐhuan de dìfang shì Běijīng, wǒ qùguo liǎng cì.","vi":"Nơi mình thích nhất là Bắc Kinh, mình đã đến hai lần."}},{"lbl":"中间","zh":"那里比我们这里……多了 / ……一点儿。","py":"Nàlǐ bǐ wǒmen zhèlǐ …… duō le / …… yìdiǎnr.","vi":"Ở đó … hơn chỗ mình nhiều / một chút.","ex":{"zh":"北京比我们这里冷多了，还经常下雪。","py":"Běijīng bǐ wǒmen zhèlǐ lěngduō le, hái jīngcháng xià xuě.","vi":"Bắc Kinh lạnh hơn chỗ mình nhiều, lại hay có tuyết."}},{"lbl":"中间","zh":"……门口站着……，大家手里都拿着……。","py":"…… ménkǒu zhànzhe ……, dàjiā shǒuli dōu názhe …….","vi":"Trước cổng … có … đang đứng, ai cũng cầm …","ex":{"zh":"颐和园门口站着很多人，大家手里都拿着门票。","py":"Yíhé Yuán ménkǒu zhànzhe hěn duō rén, dàjiā shǒuli dōu názhe ménpiào.","vi":"Trước cổng Di Hoà Viên có rất nhiều người, ai cũng cầm vé trên tay."}},{"lbl":"中间","zh":"我们……进去，里面多……啊！","py":"Wǒmen …… jìnqù, lǐmiàn duō …… a!","vi":"Bọn mình … vào trong, bên trong … biết bao!","ex":{"zh":"我们从门口走进去，里面多漂亮啊！","py":"Wǒmen cóng ménkǒu zǒu jìnqù, lǐmiàn duō piàoliang a!","vi":"Bọn mình từ cổng đi vào, bên trong đẹp biết bao!"}},{"lbl":"结尾","zh":"我有……没去了，希望……再去一次。","py":"Wǒ yǒu …… méi qù le, xīwàng …… zài qù yí cì.","vi":"Đã … mình chưa quay lại, mong … được đi thêm lần nữa.","ex":{"zh":"我有一年多没去了，希望明年能再去一次。","py":"Wǒ yǒu yì nián duō méi qù le, xīwàng míngnián néng zài qù yí cì.","vi":"Đã hơn một năm mình chưa quay lại, mong sang năm được đi thêm lần nữa."}}]}]},"review":{"range":"13–15","rows":[{"l":13,"zh":"双宾语句 (2)","vi":"Câu hai tân ngữ (2)","ex":{"zh":"我送给她一本书。","py":"Wǒ sòng gěi tā yì běn shū.","vi":"Mình tặng cô ấy một quyển sách."}},{"l":13,"zh":"比较句 (7)","vi":"Câu so sánh (7): chênh lệch cụ thể","ex":{"zh":"我哥哥比我大两岁。","py":"Wǒ gēge bǐ wǒ dà liǎng suì.","vi":"Anh trai mình hơn mình hai tuổi."}},{"l":13,"zh":"比较句 (8)","vi":"Câu so sánh (8): 一点儿 / 一些","ex":{"zh":"姐姐比我高一点儿。","py":"Jiějie bǐ wǒ gāo yìdiǎnr.","vi":"Chị gái cao hơn mình một chút."}},{"l":14,"zh":"存现句 (2)","vi":"Câu tồn hiện (2)","ex":{"zh":"楼下站着很多人。","py":"Lóu xià zhànzhe hěn duō rén.","vi":"Dưới nhà có rất nhiều người đang đứng."}},{"l":14,"zh":"程度副词 \"多\"","vi":"Phó từ mức độ 多","ex":{"zh":"她的汉语说得多好啊！","py":"Tā de Hànyǔ shuō de duō hǎo a!","vi":"Cô ấy nói tiếng Hán giỏi biết bao!"}},{"l":14,"zh":"复合趋向补语","vi":"Bổ ngữ xu hướng kép","ex":{"zh":"我们走回家去吧。","py":"Wǒmen zǒu huí jiā qù ba.","vi":"Chúng mình đi bộ về nhà đi."}},{"l":15,"zh":"动量补语 (1)","vi":"Bổ ngữ động lượng (1)","ex":{"zh":"我去过两次北京。","py":"Wǒ qùguo liǎng cì Běijīng.","vi":"Mình đã đến Bắc Kinh hai lần."}},{"l":15,"zh":"动量补语 (2)","vi":"Bổ ngữ động lượng (2)","ex":{"zh":"我来过这儿两次。","py":"Wǒ láiguo zhèr liǎng cì.","vi":"Mình đã đến đây hai lần."}},{"l":15,"zh":"\"有\"字句 (2)","vi":"Câu chữ 有 (2)","ex":{"zh":"你的老师有三十岁吗？","py":"Nǐ de lǎoshī yǒu sānshí suì ma?","vi":"Thầy/cô của bạn được ba mươi tuổi chưa?"}}]}}];
